        function pexpertSubView(v) {
            const views = { write: 'pexpertWriteView', opt: 'pexpertOptView', sd: 'pexpertSdView' };
            document.querySelectorAll('#tab-pexpert > div[id$="View"]').forEach(el => el.style.display = 'none');
            const view = document.getElementById(views[v]);
            if (view) view.style.display = '';
            document.querySelectorAll('#pexpertSubnav .tab').forEach(b => b.classList.remove('active'));
            const btn = document.querySelector('#pexpertSubnav .tab[data-psub="' + v + '"]');
            if (btn) btn.classList.add('active');
            if (v === 'sd' && typeof sdInit === 'function') sdInit();
            if (v === 'write') loadPexpertModels();
            if (v === 'opt') loadPexpertOptModels();
        }

        // 小工具：转义进 HTML 属性 / 通用复制（本段多个页面共用；escHtml 在全站已有）
        function escAttr(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/'/g, '&#39;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
        function copyText(text) {
            const v = String(text == null ? '' : text);
            if (!v) { showToast('没有可复制的内容', 'error'); return; }
            navigator.clipboard.writeText(v)
                .then(() => showToast('✅ 已复制到剪贴板', 'success'))
                .catch(() => showToast('复制失败，请手动全选复制', 'error'));
        }
        let scData = null;
        async function scInit() {
            if (scData) return;
            try {
                const r = await fetch('/data/shotcraft_catalog.json');
                scData = await r.json();
            } catch (e) { scData = { items: [], categories: [] }; }
            const sel = document.getElementById('scCat');
            if (sel && sel.options.length <= 1) {
                (scData.categories || []).forEach(c => {
                    const o = document.createElement('option');
                    o.value = c.id; o.textContent = `🎥 ${c.zh}`;
                    sel.appendChild(o);
                });
            }
            scRender();
        }
        function scRender() {
            const box = document.getElementById('scList');
            if (!box || !scData) return;
            const q = (document.getElementById('scQuery').value || '').trim().toLowerCase();
            const cat = document.getElementById('scCat').value || '';
            const items = (scData.items || []).filter(x =>
                (!cat || x.category === cat) &&
                (!q || (x.name + ' ' + x.summary + ' ' + x.use + ' ' + (x.tags || []).join(' ')).toLowerCase().includes(q)));
            const cnt = document.getElementById('scCount');
            if (cnt) cnt.textContent = `${items.length} / ${(scData.items || []).length} 张配方卡 · 来源 ${scData.source || 'video-shotcraft'}（${scData.license || 'MIT'}）`;
            box.innerHTML = items.slice(0, 200).map(x => `
                <div style="border:1px solid var(--border);border-radius:10px;padding:12px;background:var(--surface2,rgba(127,127,127,.04));">
                    <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">
                        <b style="font-size:13px;">${escHtml(x.name)}</b>
                        <span style="font-size:11px;padding:1px 8px;border-radius:10px;background:var(--accent);color:var(--on-accent);">${escHtml(x.cat_zh || x.category)}</span>
                    </div>
                    <div style="font-size:12px;color:var(--text2);margin-top:6px;line-height:1.7;">${escHtml(x.summary || '')}</div>
                    <div style="font-size:12px;color:var(--text2);margin-top:4px;">⏱ ${escHtml(x.duration || '—')} ｜ ⚡ ${escHtml(x.energy || '—')}</div>
                    <div style="font-size:12px;color:var(--text2);margin-top:4px;">🎯 ${escHtml(x.use || '')}</div>
                    <div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px;">
                        <button class="btn btn-sm" type="button" onclick="scCopyName('${escAttr(x.name)}')">📋 复制卡名</button>
                        ${x.preview ? `<a class="btn btn-sm" href="${escAttr(x.preview)}" target="_blank" rel="noopener">▶ 样片</a>` : ''}
                        <a class="btn btn-sm" href="${escAttr(x.card_url)}" target="_blank" rel="noopener">📄 配方卡</a>
                    </div>
                </div>`).join('') + (items.length > 200 ? `<div style="grid-column:1/-1;text-align:center;font-size:12px;color:var(--text2);">（只显示前 200 条，请用搜索 / 分类收窄）</div>` : '');
        }
        function scCopyName(name) { copyText(name); }

        // 上游 852wa/JIZURA（MIT）是**纯静态单文件应用**：由本站 /jizura/ 同源托管，
        // 没有进程、没有端口、不需要启停 —— 这里只负责「探状态 + 装载 iframe」。
        // ⚠️ 别给它加 start/stop 那套：没有可启停的东西。
        const JZ_URL = '/jizura/';
        let jzLoaded = false;      // 同一次会话只装载一次，避免每次切页重下 2.4MB
        let jzSrc = JZ_URL;        // 带 ?v=<版本> 的地址，随版本变化自动穿透缓存

        function jzSetState(text, color) {
            const el = document.getElementById('jzState');
            if (el) { el.textContent = text; if (color) el.style.color = color; }
        }

        function jzShowErr(msg) {
            const el = document.getElementById('jzErr');
            if (el) el.textContent = msg || '';
        }

        async function jzRefresh() {
            const down = document.getElementById('jzDown');
            const frame = document.getElementById('jzFrame');
            try {
                const r = await fetch('/api/jizura/info');
                const d = await r.json();
                if (!d || !d.installed) {
                    jzSetState('未安装', 'var(--warn-fg)');
                    jzShowErr('找不到 static/jizura/index.html');
                    if (down) down.style.display = 'flex';
                    if (frame) frame.style.display = 'none';
                    jzLoaded = false;
                    return d;
                }
                jzSrc = d.default_url || JZ_URL;
                jzShowErr('');
                jzSetState('就绪 · v' + d.version + ' · ' + d.size_mb + ' MB', 'var(--ok-fg)');
                if (down) down.style.display = 'none';
                return d;
            } catch (e) {
                jzSetState('状态未知', 'var(--err-fg)');
                jzShowErr('读取状态失败：' + (e && e.message ? e.message : e));
                return null;
            }
        }

        function jzLoad() {
            const frame = document.getElementById('jzFrame');
            if (!frame || jzLoaded) return;
            frame.src = jzSrc;
            frame.style.display = 'block';
            jzLoaded = true;
        }

        // 重载：清 src 再挂回去，强制 iframe 重新走一遍初始化
        function jzReload() {
            const frame = document.getElementById('jzFrame');
            jzLoaded = false;
            if (frame) { frame.style.display = 'none'; frame.removeAttribute('src'); }
            jzLoad();
        }

        async function jzInit() {
            const d = await jzRefresh();
            if (d && d.installed) jzLoad();
        }

        function mnInit() { /* 输入留在页面上即可，无需恢复 */ }
        async function mnGenerate() {
            const title = (document.getElementById('mnTitle').value || '').trim();
            const msg = document.getElementById('mnMsg');
            if (!title) { msg.textContent = '⚠ 请先填片名'; return; }
            const payload = {
                title: title,
                genre: document.getElementById('mnGenre').value,
                perspective: document.getElementById('mnPerspective').value,
                platform: document.getElementById('mnPlatform').value,
                target_seconds: parseInt(document.getElementById('mnDuration').value || '180', 10),
                points: (document.getElementById('mnPoints').value || '').trim(),
            };
            const btn = document.getElementById('mnGoBtn');
            btn.disabled = true; btn.textContent = '⏳ 生成中…';
            msg.textContent = '已提交，模型写作中（一般 10–60 秒）……';
            try {
                const r = await fetch('/api/movienarr/script', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                });
                const d = await gwJson(r, '电影解说');
                if (!d.success) { msg.textContent = '❌ ' + (d.error || '生成失败'); return; }
                // 后台线程生成 → 轮询取结果（云端网关对长耗时请求会 502，不能干等）
                const job = d.job_id;
                const deadline = Date.now() + 180000;
                while (Date.now() < deadline) {
                    await new Promise(res => setTimeout(res, 2500));
                    const rr = await fetch(`/api/movienarr/result/${job}`);
                    const rd = await rr.json();
                    if (!rd.success) { msg.textContent = '❌ ' + (rd.error || '生成失败'); return; }
                    if (!rd.done) continue;
                    msg.textContent = '';
                    document.getElementById('mnResultTitle').textContent = `《${title}》· ${payload.genre}`;
                    document.getElementById('mnScript').value = rd.script || '';
                    document.getElementById('mnResultBox').style.display = 'block';
                    return;
                }
                msg.textContent = '❌ 生成超时（180 秒），请重试或换更快的模型';
            } catch (e) {
                msg.textContent = '❌ ' + (e.message || e);
            } finally {
                btn.disabled = false; btn.textContent = '🚀 生成解说文案';
            }
        }
        function mnCopy() { copyText(document.getElementById('mnScript').value); }

        async function _bridgeProbe(url) {
            const r = await fetch('/api/bridge/probe', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ url })
            });
            return await r.json();
        }
        async function avProbe(inputId, msgId) {
            const el = document.getElementById(msgId);
            el.textContent = '探测中……';
            try {
                const d = await _bridgeProbe(document.getElementById(inputId).value.trim());
                if (d.reachable) el.textContent = `✅ 在线（HTTP ${d.status}，${d.ms}ms）${d.title ? ' · ' + d.title : ''}`;
                else el.textContent = '❌ ' + (d.error || '连不上');
            } catch (e) { el.textContent = '❌ ' + (e.message || e); }
        }
        function avOpen(inputId) { window.open(document.getElementById(inputId).value.trim(), '_blank', 'noopener'); }
        async function vsProbe() {
            const el = document.getElementById('vsApiMsg');
            const url = document.getElementById('vsApiUrl').value.trim();
            if (!url) { el.textContent = '⚠ 请先填 VoiceStudio 的本地 API 地址'; return; }
            el.textContent = '探测中……';
            try {
                const d = await _bridgeProbe(url);
                if (d.reachable) el.textContent = `✅ 在线（HTTP ${d.status}，${d.ms}ms）${d.title ? ' · ' + d.title : ''}`;
                else el.textContent = '❌ ' + (d.error || '连不上');
            } catch (e) { el.textContent = '❌ ' + (e.message || e); }
        }
        function vsOpen() {
            window.open('https://github.com/debpalash/VoiceStudio#readme', '_blank', 'noopener');
        }

        let pcJobTimer = null;
        function _pcCollect() {
            const platforms = [];
            if (document.getElementById('pcPlatDouyin').checked) platforms.push('douyin');
            if (document.getElementById('pcPlatXhs').checked) platforms.push('xiaohongshu');
            if (document.getElementById('pcPlatSph').checked) platforms.push('shipinhao');
            return {
                text: document.getElementById('pcText').value,
                platforms: platforms.length ? platforms : ['douyin'],
                commercial: document.getElementById('pcCommercial').checked,
                industries: document.getElementById('pcIndustry').value ? [document.getElementById('pcIndustry').value] : [],
            };
        }
        async function pcScan() {
            const msg = document.getElementById('pcMsg');
            const body = _pcCollect();
            if (!body.text.trim()) { msg.textContent = '⚠ 请先粘贴文案'; return; }
            msg.textContent = '扫描中……';
            try {
                const r = await fetch('/api/precheck/scan', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(body)
                });
                const d = await r.json();
                if (!d.success) { msg.textContent = '❌ ' + (d.error || '扫描失败'); return; }
                msg.textContent = `共 ${d.characters} 字，命中候选 ${d.candidates.length} 处、辟谣提示 ${d.myth_advisories.length} 处`;
                document.getElementById('pcScanResult').innerHTML = pcRenderScan(d);
            } catch (e) { msg.textContent = '❌ ' + (e.message || e); }
        }
        function pcRenderScan(d) {
            let h = '';
            if (d.candidates && d.candidates.length) {
                h += `<div style="font-size:13px;margin-bottom:6px;"><b>词面候选（候选≠违规，要结合语境看）</b></div>
                <div style="max-height:260px;overflow-y:auto;"><table style="width:100%;border-collapse:collapse;font-size:12px;">
                <tr style="color:var(--text2);text-align:left;"><th style="padding:4px 6px;">级别</th><th>命中</th><th>行</th><th>上下文</th><th>规则</th></tr>`;
                d.candidates.forEach(c => {
                    const sevColor = c.severity === 'critical' ? '#e74c3c' : (c.severity === 'high' ? '#e67e22' : '#95a5a6');
                    h += `<tr><td style="padding:4px 6px;color:${sevColor};font-weight:600;">${escHtml(c.severity_zh || c.severity)}</td>
                    <td><code>${escHtml(c.match)}</code></td><td>L${c.line}</td>
                    <td style="color:var(--text2);">${escHtml(c.context)}</td>
                    <td style="color:var(--text2);">${escHtml(c.rule)} ${escHtml(c.title)}</td></tr>`;
                });
                h += '</table></div>';
            } else {
                h += '<div style="font-size:13px;color:var(--text2);">词面零命中 —— 但零命中不等于安全，收益暗示 / 导流意图等语义风险仍需 AI 深审。</div>';
            }
            if (d.myth_advisories && d.myth_advisories.length) {
                h += `<div style="font-size:13px;margin:10px 0 6px;"><b>辟谣提示（这些自我审查其实不用做）</b></div>`;
                d.myth_advisories.forEach(m => { h += `<div style="font-size:12px;color:var(--text2);">L${m.line} <code>${escHtml(m.match)}</code>：${escHtml(m.note)} → ${escHtml(m.suggestion || '')}</div>`; });
            }
            return h;
        }
        async function pcReview() {
            const msg = document.getElementById('pcMsg');
            const body = _pcCollect();
            if (!body.text.trim()) { msg.textContent = '⚠ 请先粘贴文案'; return; }
            const btn = document.getElementById('pcReviewBtn');
            btn.disabled = true;
            msg.textContent = '已提交，AI 深审中（词面候选 + 全文语义判定，一般 20–90 秒）……';
            document.getElementById('pcReviewResult').innerHTML = '';
            try {
                const r = await fetch('/api/precheck/review', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(body)
                });
                const d = await gwJson(r, '发布预检');
                if (!d.success) { msg.textContent = '❌ ' + (d.error || '提交失败'); return; }
                msg.textContent = '';
                // 先把快扫结果也刷出来（返回里带了）
                document.getElementById('pcScanResult').innerHTML = pcRenderScan(d);
                // 轮询深审结果
                clearInterval(pcJobTimer);
                pcJobTimer = setInterval(async () => {
                    try {
                        const rr = await fetch(`/api/precheck/result/${d.job_id}`);
                        const rd = await rr.json();
                        if (!rd.success) { clearInterval(pcJobTimer); btn.disabled = false; msg.textContent = '❌ ' + (rd.error || '审核失败'); return; }
                        if (!rd.done) return;
                        clearInterval(pcJobTimer); btn.disabled = false;
                        document.getElementById('pcReviewResult').innerHTML = pcRenderReview(rd.review);
                        msg.textContent = '✅ 深审完成';
                    } catch (e) { /* 轮询抖动忽略，等下一拍 */ }
                }, 2500);
            } catch (e) { btn.disabled = false; msg.textContent = '❌ ' + (e.message || e); }
        }
        const PC_LEVEL_ZH = { must_fix: ['必改', '#e74c3c'], suggest: ['建议改', '#e67e22'], info: ['仅提示', '#3498db'] };
        const PC_VERDICT_ZH = { can_publish: ['可以发', '#27ae60'], fix_then_publish: ['改完可发', '#e67e22'], do_not_publish: ['不建议发', '#e74c3c'] };
        function pcRenderReview(rv) {
            if (!rv) return '';
            const platName = { douyin: '抖音', xiaohongshu: '小红书', shipinhao: '微信视频号' };
            let h = '';
            if (rv.verdicts) {
                h += '<div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:10px;">';
                Object.keys(rv.verdicts).forEach(p => {
                    const v = rv.verdicts[p] || {};
                    const zh = PC_VERDICT_ZH[v.verdict] || [v.verdict, 'var(--text2)'];
                    h += `<div style="border:1px solid var(--border);border-radius:10px;padding:8px 14px;">
                        <span style="font-size:12px;color:var(--text2);">${escHtml(platName[p] || p)}</span>
                        <b style="color:${zh[1]};margin-left:6px;">${escHtml(zh[0])}</b>
                        <div style="font-size:12px;color:var(--text2);margin-top:2px;">${escHtml(v.summary || '')}</div></div>`;
                });
                h += '</div>';
            }
            const groups = { must_fix: [], suggest: [], info: [] };
            (rv.issues || []).forEach(i => { (groups[i.level] || groups.info).push(i); });
            ['must_fix', 'suggest', 'info'].forEach(lv => {
                if (!groups[lv].length) return;
                const [name, color] = PC_LEVEL_ZH[lv];
                h += `<div style="font-size:13px;margin:10px 0 6px;"><b style="color:${color};">【${name}】${groups[lv].length} 处</b></div>`;
                groups[lv].forEach(i => {
                    h += `<div style="border-left:3px solid ${color};padding:6px 10px;margin-bottom:8px;background:var(--surface2,rgba(127,127,127,.04));border-radius:0 8px 8px 0;">
                        <div style="font-size:12px;color:var(--text2);">${escHtml(i.rule || '')} ${escHtml(i.title || '')}</div>
                        <div style="font-size:13px;margin:4px 0;">原文：<code>${escHtml(i.quote || '')}</code></div>
                        <div style="font-size:13px;color:var(--text2);">${escHtml(i.reason || '')}</div>
                        ${i.fix ? `<div style="font-size:13px;margin-top:4px;">✏️ 改法：${escHtml(i.fix)}</div>` : ''}
                    </div>`;
                });
            });
            if (rv.myth_notes && rv.myth_notes.length) {
                h += '<div style="font-size:12px;color:var(--text2);margin:8px 0;">💡 ' + rv.myth_notes.map(escHtml).join('；') + '</div>';
            }
            if (rv.good_points && rv.good_points.length) {
                h += '<div style="font-size:12px;color:var(--text2);margin:8px 0;">👍 写得稳、应保留：' + rv.good_points.map(escHtml).join('；') + '</div>';
            }
            if (rv.rewritten) {
                h += `<div style="margin-top:10px;"><label class="form-label">修改稿（保住钩子与信息量，改动只动越线处）</label>
                <textarea class="form-textarea" id="pcRewritten" rows="10">${escHtml(rv.rewritten)}</textarea>
                <button class="btn btn-sm" style="margin-top:6px;" type="button" onclick="copyText(document.getElementById('pcRewritten').value)">📋 复制修改稿</button></div>`;
            }
            if (rv.checklist && rv.checklist.length) {
                h += '<div style="font-size:12px;color:var(--text2);margin-top:10px;"><b>发布前检查单</b><br>' + rv.checklist.map(escHtml).join('<br>') + '</div>';
            }
            h += '<div style="font-size:11px;color:var(--text2);margin-top:8px;">结论含义：本次检查范围内未发现阻断问题，不承诺 100% 过审。规则框架来自 yuwen-publish-precheck（MIT）。</div>';
            return h;
        }

        function initDropZones() {
            const zones = [
                { id: 'img2imgDropZone', type: 'img2img' },
                { id: 'videoDropZone', type: 'video' }
            ];

            zones.forEach(({ id, type }) => {
                const zone = document.getElementById(id);
                if (!zone) return;

                // 阻止默认拖拽行为
                ['dragenter', 'dragover', 'dragleave', 'drop'].forEach(evt => {
                    zone.addEventListener(evt, (e) => {
                        e.preventDefault();
                        e.stopPropagation();
                    });
                });

                // 拖入
                zone.addEventListener('dragenter', () => zone.classList.add('drag-over'));
                zone.addEventListener('dragover', () => zone.classList.add('drag-over'));
                zone.addEventListener('dragleave', (e) => {
                    if (!zone.contains(e.relatedTarget)) {
                        zone.classList.remove('drag-over');
                    }
                });

                // 放下（支持多文件）
                zone.addEventListener('drop', (e) => {
                    zone.classList.remove('drag-over');
                    const files = e.dataTransfer.files;
                    for (let fi = 0; fi < files.length; fi++) {
                        handleUploadFile(files[fi], type);
                    }
                });
            });
        }

        async function handleUploadFile(file, type) {
            if (!file.type.startsWith('image/')) {
                showToast('请上传图片文件', 'error');
                return;
            }
            // V1.8.235：视频参照图封顶 5 张（中栏只有 5 个槽）——上传前就拦，
            // 免得服务端白存一份又进不了列表；拖拽批量丢进来时逐文件过闸。
            if (type === 'video' && uploadedVideoImgUrls.length >= VG_MAX_REF_IMAGES) {
                showToast('参照图最多 ' + VG_MAX_REF_IMAGES + ' 张，装不下了', 'warning');
                return;
            }

            showLoading('正在上传图片...');
            try {
                const formData = new FormData();
                formData.append('file', file);
                const resp = await fetch('/api/upload/image', { method: 'POST', body: formData });
                const data = await resp.json();

                if (data.success) {
                    const fullUrl = window.location.origin + data.url;
                    if (type === 'img2img') {
                        uploadedImg2ImgUrls.push(fullUrl);
                        updateMultiImageUI('img2img');
                    } else if (type === 'video') {
                        uploadedVideoImgUrls.push(fullUrl);
                        updateMultiImageUI('video');
                    }
                    showToast('图片上传成功！', 'success');
                } else {
                    showToast(data.error || '上传失败', 'error');
                }
            } catch (e) {
                showToast('上传失败: ' + e.message, 'error');
            } finally {
                hideLoading();
            }
        }

        function handleDropZoneFiles(input, type) {
            if (input.files && input.files.length > 0) {
                for (let i = 0; i < input.files.length; i++) {
                    handleUploadFile(input.files[i], type);
                }
            }
            input.value = '';
        }

        function updateMultiImageUI(type) {
            // V1.8.235：视频参照图改走「中栏 5 槽」渲染（vgRenderSlots），
            // img2img 仍用旧缩略图行。两条路都只维护这一个分发点。
            if (type === 'video') { vgRenderSlots(); return; }
            const urls = uploadedImg2ImgUrls;
            const thumbsId = 'img2imgThumbs';
            const urlInputId = 'img2imgUrl';
            const thumbsEl = document.getElementById(thumbsId);
            if (!thumbsEl) return;

            thumbsEl.innerHTML = urls.map((u, idx) => {
                const localPath = u.replace(window.location.origin, '');
                return `<div style="position:relative;display:inline-block;width:64px;height:64px;">
                    <img src="${localPath}" style="width:64px;height:64px;object-fit:cover;border-radius:6px;border:1px solid var(--border);">
                    <button onclick="removeMultiImage('${type}', ${idx})" style="position:absolute;top:-5px;right:-5px;width:18px;height:18px;border-radius:50%;background:var(--error);color:var(--on-accent);border:none;cursor:pointer;font-size:10px;line-height:1;padding:0;display:flex;align-items:center;justify-content:center;">✕</button>
                </div>`;
            }).join('');

            // 同步 URL 输入框
            document.getElementById(urlInputId).value = urls.join(', ');
        }

        function removeMultiImage(type, idx) {
            const urls = type === 'img2img' ? uploadedImg2ImgUrls : uploadedVideoImgUrls;
            urls.splice(idx, 1);
            updateMultiImageUI(type);
        }

        async function restartServer() {
            if (!confirm('确定要重启后台服务吗？重启期间页面会短暂失去响应（约 10~30 秒），完成后自动恢复。')) return;
            try {
                await fetch('/api/server/restart', { method: 'POST' });
            } catch (e) { /* 旧进程已退出，连接断开属正常 */ }
            document.body.innerHTML = '<div style="display:flex;align-items:center;justify-content:center;height:100vh;flex-direction:column;gap:16px;color:var(--text2);font-size:16px;">'
                + '<div style="font-size:48px;">🔄</div><div>正在重启后台服务…</div>'
                + '<div id="restartHint" style="font-size:13px;">通常 10~30 秒，恢复后页面自动刷新</div></div>';
            const t0 = Date.now();
            for (let i = 0; i < 45; i++) {
                await new Promise(r => setTimeout(r, 2000));
                try {
                    const r = await fetch('/api/member/license?_t=' + Date.now(), { cache: 'no-store' });
                    if (r.ok) { location.reload(); return; }
                } catch (e) { /* 还没起来，继续等 */ }
                const hint = document.getElementById('restartHint');
                if (hint) hint.textContent = '已等待 ' + Math.round((Date.now() - t0) / 1000) + ' 秒…';
            }
            const hint = document.getElementById('restartHint');
            if (hint) hint.innerHTML = '⏳ 等待超时，请手动刷新页面；若仍无响应请重新运行程序。';
        }

        function showToast(message, type = 'info') {
            const toast = document.getElementById('toast');
            toast.textContent = message;
            toast.className = `toast toast-${type} show`;
            clearTimeout(toast._timeout);
            toast._timeout = setTimeout(() => toast.classList.remove('show'), 3000);
        }

        async function copyPromptText(id) {
            const el = document.getElementById(id);
            const text = (el.value || '').trim();
            if (!text) { showToast('输入框是空的，没有内容可复制', 'info'); return; }
            try {
                await navigator.clipboard.writeText(text);
                showToast('已复制到剪贴板', 'success');
            } catch (e) {
                // 剪贴板 API 不可用（非 https / 权限拒绝）时降级
                el.select();
                document.execCommand('copy');
                showToast('已复制到剪贴板', 'success');
            }
        }

        function clearPromptText(id) {
            const el = document.getElementById(id);
            if (!(el.value || '').trim()) { showToast('输入框已经是空的', 'info'); return; }
            el.value = '';
            el.dispatchEvent(new Event('input', { bubbles: true }));
            showToast('已清空', 'success');
        }

        function showLoading(text = '处理中...') {
            document.getElementById('loadingText').textContent = text;
            document.getElementById('loadingOverlay').classList.add('show');
        }
        function hideLoading() {
            document.getElementById('loadingOverlay').classList.remove('show');
        }

        let HEADER_MASKED_KEY = '';

        async function checkApiKeyStatus() {
            try {
                const resp = await fetch('/api/config', { cache: 'no-store' });
                const data = await resp.json();
                HEADER_MASKED_KEY = data.api_key_masked || '';
            } catch (e) {
                HEADER_MASKED_KEY = '';
            }
            await refreshHeaderIdentity();
        }

        async function refreshHeaderIdentity() {
            const dot = document.getElementById('statusDot');
            const text = document.getElementById('statusText');
            const box = document.getElementById('apiKeyStatus');
            const lo = document.getElementById('btnMemberLogout');
            let name = '', hint = '', member = null;
            try {
                const hdrs = {};
                const at = localStorage.getItem('agnes_admin_token') || '';
                if (at) hdrs['X-Admin-Token'] = at;
                const r = await fetch('/api/member/whoami?_t=' + Date.now(), { headers: hdrs, cache: 'no-store' });
                const d = await r.json();
                if (d && d.success) {
                    name = d.display_name || '';
                    hint = d.hint || '';
                    member = d.member || null;
                }
            } catch (e) { /* 取不到身份就回落到 Key 掩码 */ }
            // 有会员记录才给「登出」—— 管理员登录时 whoami 的 role 是 admin，
            // 但本机会员照样可以登出（member 字段还在）。
            if (lo) lo.style.display = (member && member.id) ? '' : 'none';
            if (name) {
                if (dot) dot.classList.add('active');
                if (text) text.textContent = name;
                if (box) box.title = hint || name;
            } else if (HEADER_MASKED_KEY) {
                if (dot) dot.classList.add('active');
                if (text) text.textContent = 'API Key: ' + HEADER_MASKED_KEY;
                if (box) box.title = hint || '本机尚未激活会员，暂以 API Key 标识';
            } else {
                if (dot) dot.classList.remove('active');
                if (text) text.textContent = hint || '未配置 API Key';
            }
        }

        // 登出 = 解除「本浏览器 ↔ 会员号」的绑定 + 清掉本机保存的 KEY。
        // 只清页面显示是不行的：旧会员记录的 machine 还指着同一个浏览器身份，
        // 下一个人登录后会跟旧会员撞在一起（身份串号、资产互见）。
        async function memberLogout() {
            const nm = (document.getElementById('statusText') || {}).textContent || '当前会员';
            if (!confirm('确定登出「' + nm + '」吗？\n\n登出后本机保存的 KEY 会一并清除，可输入其它会员卡号登录。')) return;
            try {
                showLoading('正在登出...');
                const r = await fetch('/api/member/logout', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: '{}'
                });
                const d = await r.json().catch(function () { return {}; });
                hideLoading();
                if (d && d.success && d.logged_out) {
                    alert(d.message || '已登出');
                    location.reload();
                    return;
                }
                if (d && d.success) {
                    alert(d.message || '当前浏览器没有登录的会员');
                    return;
                }
                alert('登出失败：' + ((d && d.error) || '未知错误'));
            } catch (e) {
                hideLoading();
                alert('登出失败：' + e);
            }
        }

        // 强制刷新页面（清缓存重新加载，不会动后台进程）
        // 手机浏览器里双指缩放、双指下拉、顶部下拉都会触发页面刷新，正在排队的任务会被打断。
        // 开启后：多指手势、下拉刷新、双击缩放、Ctrl+滚轮缩放、边缘滑动返回、F5 / Ctrl+R 全部拦掉。
        // 关掉后一切照旧 —— 单 KEY 用户不会被锁死，这里也一样，随时可解锁。
        const PAGE_LOCK_KEY = 'agnes_page_lock';
        let _lockStartPos = null;

        function pageLockOn() {
            return document.documentElement.classList.contains('page-locked');
        }

        function _lockInScrollable(el) {
            // 手指所在位置是否处于「还能往上滚」的容器里：是就别拦，否则正常滚动会被打断
            let n = el;
            while (n && n !== document.body && n !== document.documentElement) {
                try { if (n.scrollTop > 0) return true; } catch (e) { /* 忽略 */ }
                n = n.parentElement;
            }
            return false;
        }

        function _lockSetViewport(on) {
            const mv = document.querySelector('meta[name="viewport"]');
            if (!mv) return;
            mv.setAttribute('content', on
                ? 'width=device-width, initial-scale=1.0, maximum-scale=1.0, minimum-scale=1.0, user-scalable=no'
                : 'width=device-width, initial-scale=1.0');
        }

        function applyPageLock(on, silent) {
            document.documentElement.classList.toggle('page-locked', !!on);
            _lockSetViewport(!!on);
            const b = document.getElementById('btnPageLock');
            if (b) {
                b.textContent = on ? '🔒 已锁定' : '🔓 未锁定';
                b.title = on ? '页面已锁定：缩放 / 下拉刷新 / F5 均已禁用（点击解锁）'
                             : '页面未锁定：点击开启防误触（禁止缩放与刷新）';
                b.style.color = on ? 'var(--success)' : '';
                b.style.borderColor = on ? 'var(--success)' : '';
            }
            try { localStorage.setItem(PAGE_LOCK_KEY, on ? '1' : '0'); } catch (e) { /* 隐私模式 */ }
            if (!silent && typeof showToast === 'function') {
                showToast(on ? '页面已锁定：双指缩放 / 下拉刷新 / F5 都不可用了（点顶栏 🔒 解锁）'
                             : '页面已解锁：缩放与刷新恢复正常', on ? 'success' : 'info');
            }
        }

        function togglePageLock() {
            applyPageLock(!pageLockOn());
        }

        function initPageLock() {
            let on = true;                      // 默认锁死：防手机误触刷新
            try { if (localStorage.getItem(PAGE_LOCK_KEY) === '0') on = false; } catch (e) { /* 隐私模式 */ }
            applyPageLock(on, true);

            const locked = () => pageLockOn();

            // 1) 多指手势（双指缩放 / 双指下拉刷新）：一律拦掉
            document.addEventListener('touchstart', function (e) {
                if (!locked()) return;
                if (e.touches && e.touches.length > 1) { e.preventDefault(); _lockStartPos = null; return; }
                const t = e.touches && e.touches[0];
                _lockStartPos = t ? { x: t.clientX, y: t.clientY } : null;
            }, { passive: false });

            document.addEventListener('touchmove', function (e) {
                if (!locked() || !e.touches) return;
                if (e.touches.length > 1) { e.preventDefault(); return; }
                if (!_lockStartPos) return;
                const t = e.touches[0];
                const tgt = e.target;
                // 画布（手绘 / 图像编辑）自己要处理手势，交给它
                if (tgt && (tgt.tagName === 'CANVAS' || (tgt.closest && tgt.closest('canvas')))) return;
                const dy = t.clientY - _lockStartPos.y;
                const dx = t.clientX - _lockStartPos.x;
                // 页面已在顶部还继续往下拉 → 下拉刷新手势
                if (dy > 6 && Math.abs(dy) > Math.abs(dx) && (window.scrollY || 0) <= 0 && !_lockInScrollable(tgt)) {
                    e.preventDefault();
                    return;
                }
                // 从屏幕左右边缘起手的横向滑动 → iOS 的滑动返回 / 前进
                if (_lockStartPos.x <= 16 && Math.abs(dx) > 10 && Math.abs(dx) > Math.abs(dy)) {
                    e.preventDefault();
                }
            }, { passive: false });

            document.addEventListener('touchend', function () { _lockStartPos = null; }, { passive: true });
            document.addEventListener('touchcancel', function () { _lockStartPos = null; }, { passive: true });

            // 2) iOS Safari 的手势缩放事件（它忽略 user-scalable，只能这么拦）
            ['gesturestart', 'gesturechange', 'gestureend'].forEach(function (evt) {
                document.addEventListener(evt, function (e) { if (locked()) e.preventDefault(); }, { passive: false });
            });

            // 3) 双击缩放（画布 / iframe / 可编辑区不拦，避免破坏双击编辑）
            document.addEventListener('dblclick', function (e) {
                if (!locked()) return;
                const t = e.target;
                if (t && (t.tagName === 'CANVAS' || t.tagName === 'IFRAME' || t.isContentEditable)) return;
                e.preventDefault();
            }, { passive: false });

            // 4) 桌面端 Ctrl / Cmd + 滚轮缩放
            document.addEventListener('wheel', function (e) {
                if (locked() && (e.ctrlKey || e.metaKey)) e.preventDefault();
            }, { passive: false });

            // 5) 键盘刷新：F5 / Ctrl+R / Cmd+R / Ctrl+Shift+R
            document.addEventListener('keydown', function (e) {
                if (!locked()) return;
                const k = (e.key || '').toLowerCase();
                if (k === 'f5' || ((e.ctrlKey || e.metaKey) && k === 'r')) {
                    e.preventDefault();
                    if (typeof showToast === 'function') {
                        showToast('页面已锁定，刷新被拦截（点顶栏 🔒 解锁后再刷新）', 'info');
                    }
                }
            }, { passive: false });
        }

        function hardRefresh() {
            if (typeof pageLockOn === 'function' && pageLockOn()) {
                if (typeof showToast === 'function') {
                    showToast('页面已锁定，刷新被拦截（先点顶栏 🔒 解锁）', 'info');
                }
                return;
            }
            const base = location.href.split('#')[0].split('?')[0];
            location.replace(base + '?_r=' + Date.now());
        }

        function openMemberSettings() {
            switchTab('providers');
            const el = document.getElementById('settingsPanelMember');
            if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }

        // 全局 JS 错误提示：任何未捕获错误都会弹出，便于定位"点击无反应"类问题
        window.addEventListener('error', function (ev) {
            try {
                if (typeof showToast === 'function' && ev && ev.message) {
                    showToast('页面脚本错误: ' + ev.message, 'error');
                }
            } catch (e) { /* ignore */ }
        });

        let gateAccTab = 'login';
        function gateSteps(which) {
            const s1 = document.getElementById('gateStep1'),
                  s2 = document.getElementById('gateStep2'),
                  s4 = document.getElementById('gateStep4');
            const on = el => { if (el) { el.style.background = 'var(--accent)'; el.style.color = '#fff'; } };
            const done = el => { if (el) { el.style.background = 'var(--ok-bg)'; el.style.color = 'var(--success, #1a9d5c)'; } };
            const idle = el => { if (el) { el.style.background = 'var(--surface2)'; el.style.color = 'var(--text2)'; } };
            [s1, s2, s4].forEach(idle);
            if (which === 'account') { on(s1); }
            else if (which === 'bind') { if (s1) s1.innerHTML = '✓ 已登录'; done(s1); on(s2); }
            else if (which === 'keys') { done(s1); done(s2); on(s4); }
            else if (which === 'info') { done(s1); done(s2); done(s4); }
        }
        function gateShow(which, d) {
            const ov = document.getElementById('gateOverlay');
            if (ov) ov.style.display = 'flex';
            const boxes = {
                account: document.getElementById('gateAccount'),
                bind: document.getElementById('gateBind'),
                keys: document.getElementById('gateVendors'),
                info: document.getElementById('gateInfo')
            };
            Object.keys(boxes).forEach(function (k) {
                if (boxes[k]) boxes[k].style.display = (k === which) ? 'block' : 'none';
            });
            const ab = document.getElementById('gateAdminBox'); if (ab) ab.style.display = 'none';
            const sub = document.getElementById('gateSub');
            if (sub) {
                sub.textContent = which === 'account' ? '第 1 步 / 共 2 步 · 注册或登录账号'
                    : which === 'bind' ? '第 2 步 / 共 2 步 · 绑定会员卡即刻解锁'
                        : which === 'keys' ? '配置平台 KEY（可跳过）' : '账户与会员卡';
            }
            gateSteps(which);
            if (which === 'account') gateAccountTab(gateAccTab);
            if (which === 'bind' && d && d.account) {
                const w = document.getElementById('gateBindWho');
                if (w) w.textContent = '当前账号：' + (d.account.email || '—');
            }
            if (which === 'keys' && d && Array.isArray(d.missing)) {
                // 某一把已经配好的话，给个"已配置"提示（仍可覆盖填写）
                if (!d.missing.includes('sensenova')) {
                    const el = document.getElementById('gateSenseNovaKey');
                    if (el) el.placeholder = '商汤 Key 已配置 ✓（如需更换可重新填写）';
                }
                if (!d.missing.includes('agnes')) {
                    const el = document.getElementById('gateAgnesKey');
                    if (el) el.placeholder = 'AGNES Key 已配置 ✓（如需更换可重新填写）';
                }
            }
            if (which === 'info') accountRefreshInfo();
        }
        function gateHide() {
            const ov = document.getElementById('gateOverlay');
            if (ov) ov.style.display = 'none';
            // 门禁放行 = 刚登录/刚解锁：此刻才拉得到模型清单，重载一次
            // （DOMContentLoaded 那次在门禁后失败，5 个视频下拉曾是空的）
            if (typeof loadDramaModels === 'function') loadDramaModels();
        }
        function gateAccountTab(tab) {
            gateAccTab = (tab === 'register') ? 'register' : 'login';
            const isReg = gateAccTab === 'register';
            const tl = document.getElementById('gateTabLogin'),
                  tr = document.getElementById('gateTabRegister');
            const on = el => { if (el) { el.style.background = 'var(--accent)'; el.style.color = '#fff'; el.style.borderColor = 'var(--accent)'; } };
            const off = el => { if (el) { el.style.background = ''; el.style.color = ''; el.style.borderColor = ''; } };
            if (isReg) { off(tl); on(tr); } else { on(tl); off(tr); }
            const btn = document.getElementById('gateAccSubmit');
            if (btn) btn.textContent = isReg ? '✍️ 注册并登录' : '🔑 登录';
            const hint = document.getElementById('gateAccHint');
            if (hint) hint.textContent = isReg
                ? '用邮箱注册一个账号，登录后再绑定会员卡即可解锁全部功能。'
                : '已有账号？填邮箱和密码登录即可。忘记密码请联系管理员。';
            const pwd = document.getElementById('gatePassword');
            if (pwd) pwd.setAttribute('autocomplete', isReg ? 'new-password' : 'current-password');
        }
        function gateCardToggle() {
            const b = document.getElementById('gateCardBox');
            if (b) b.style.display = (b.style.display === 'block') ? 'none' : 'block';
        }
        function gateTempToggle() {
            const b = document.getElementById('gateTempBox');
            if (b) b.style.display = (b.style.display === 'block') ? 'none' : 'block';
        }
        async function gateSubmitTemp() {
            const code = ((document.getElementById('gateTempCode') || {}).value || '').trim().toUpperCase();
            const name = ((document.getElementById('gateTempName') || {}).value || '').trim();
            if (!code) { gateMsg('gateTempMsg', '请输入临时卡号', true); return; }
            if (name && !/^[\u4e00-\u9fa5A-Za-z0-9_\-·]{2,12}$/.test(name)) {
                gateMsg('gateTempMsg', '昵称须为 2-12 个字（中文 / 字母 / 数字）', true); return;
            }
            gateMsg('gateTempMsg', '进入中…');
            let d;
            try {
                const r = await fetch('/api/member/temp-login', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ code: code, name: name })
                });
                d = await _qJson(r);
            } catch (e) { gateMsg('gateTempMsg', '网络异常，请重试', true); return; }
            if (!d.success) { gateMsg('gateTempMsg', d.error || '登录失败', true); return; }
            showToast('临时体验卡已激活 · 仅 AI 全能对话', 'success');
            enterTempMode(d.member, d.expire_at);
        }

        // ===== 临时体验卡：仅 AI 全能对话模式（V1.8.196）=====
        let _tempExpireAt = null, _tempTimer = null;
        function enterTempMode(member, expireAt) {
            window._tempMember = member || null;
            _tempExpireAt = expireAt ? new Date(expireAt) : null;
            document.body.setAttribute('data-temp', '1');
            const bar = document.getElementById('tempBar');
            if (bar) bar.style.display = 'flex';
            const nm = document.querySelector('#tempBar .tb-name');
            if (nm) nm.textContent = '✦ 临智AI' + (member && member.name ? ' · ' + member.name : ' · 临时体验');
            gateHide();
            updateTempBar();
            clearInterval(_tempTimer);
            if (_tempExpireAt) _tempTimer = setInterval(updateTempBar, 1000);
        }
        function updateTempBar() {
            const el = document.getElementById('tempTimerText');
            if (!el) return;
            if (!_tempExpireAt) { el.textContent = '剩余 —（不限时）'; el.classList.remove('low'); return; }
            let sec = Math.round((_tempExpireAt - Date.now()) / 1000);
            if (sec < 0) sec = 0;
            const m = Math.floor(sec / 60), s = sec % 60;
            el.textContent = '剩余 ' + m + ' 分 ' + s.toString().padStart(2, '0') + ' 秒';
            el.classList.toggle('low', sec <= 120);
            if (sec <= 0) {
                el.textContent = '已过期，正在退出…';
                clearInterval(_tempTimer);
                setTimeout(tempExit, 800);
            }
        }
        async function tempExit() {
            try {
                await fetch('/api/member/temp-logout', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' }
                });
            } catch (e) { /* ignore */ }
            document.body.removeAttribute('data-temp');
            const bar = document.getElementById('tempBar');
            if (bar) bar.style.display = 'none';
            window._tempMember = null;
            _tempExpireAt = null;
            clearInterval(_tempTimer);
            localStorage.removeItem('agnes_temp');
            showToast('已退出临时体验卡', 'success');
            setTimeout(function () { location.reload(); }, 400);
        }
        async function gateSubmitAccount() {
            const email = ((document.getElementById('gateEmail') || {}).value || '').trim();
            const pwd = ((document.getElementById('gatePassword') || {}).value || '');
            if (!email) { gateMsg('gateAccountMsg', '请输入邮箱', true); return; }
            if (!pwd) { gateMsg('gateAccountMsg', '请输入密码', true); return; }
            if (gateAccTab === 'register' && pwd.length < 6) {
                gateMsg('gateAccountMsg', '密码至少 6 位', true); return;
            }
            gateMsg('gateAccountMsg', gateAccTab === 'register' ? '注册中…' : '登录中…');
            const url = gateAccTab === 'register' ? '/api/account/register' : '/api/account/login';
            const d = await _qJson(await fetch(url, {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ email: email, password: pwd })
            }));
            if (!d.success) { gateMsg('gateAccountMsg', d.error || '操作失败，请重试', true); return; }
            const pw = document.getElementById('gatePassword'); if (pw) pw.value = '';
            showToast(d.message || '成功', 'success');
            window._accState = d;
            await gateAfter();
            accountRefreshButton();
        }
        async function gateSubmitBind() {
            const code = ((document.getElementById('gateBindCode') || {}).value || '').trim();
            const name = ((document.getElementById('gateBindName') || {}).value || '').trim();
            if (!code) { gateMsg('gateBindMsg', '请输入会员卡号', true); return; }
            if (name && !/^[\u4e00-\u9fa5A-Za-z0-9_\-·]{2,12}$/.test(name)) {
                gateMsg('gateBindMsg', '会员名称须为 2-12 个字（中文 / 字母 / 数字）', true); return;
            }
            gateMsg('gateBindMsg', '绑定中…');
            const d = await _qJson(await fetch('/api/account/bind-card', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ code: code, name: name })
            }));
            if (!d.success) { gateMsg('gateBindMsg', d.error || '绑定失败', true); return; }
            showToast('💎 会员卡绑定成功，全部功能已解锁', 'success');
            window._accState = d;
            await gateAfter();
            accountRefreshButton();
        }
        async function accountLogout() {
            try { await fetch('/api/account/logout', { method: 'POST' }); } catch (e) { /* ignore */ }
            showToast('已退出登录', 'success');
            setTimeout(function () { location.reload(); }, 500);
        }
        async function accountRefreshButton() {
            // 顶栏「👤 账户」：未登录显示「登录 / 注册」，已登录显示邮箱
            const btn = document.getElementById('btnAccount');
            if (!btn) return;
            try {
                const d = await (await fetch('/api/account/me')).json();
                window._accState = d;
                if (d && d.logged_in && d.account && d.account.email) {
                    btn.textContent = '👤 ' + d.account.email;
                    btn.title = d.bound ? '账户已登录并绑定会员卡' : '账户已登录，还没有绑定会员卡';
                } else if (d && d.unlock) {
                    btn.textContent = '🎟 会员卡已激活';
                    btn.title = '本机已用会员卡激活（未注册账号）';
                } else {
                    btn.textContent = '👤 登录 / 注册';
                    btn.title = '注册或登录账号，绑定会员卡后解锁全部功能';
                }
            } catch (e) { /* 未解锁时接口异常也别影响页面 */ }
        }
        function openAccountPanel() {
            const st = window._accState || {};
            gateShow((st.logged_in || st.unlock) ? 'info' : 'account');
        }
        async function accountRefreshInfo() {
            const body = document.getElementById('gateInfoBody');
            if (!body) return;
            let d = window._accState || {};
            try {
                d = await (await fetch('/api/account/me')).json();
                window._accState = d;
            } catch (e) { /* ignore */ }
            const acc = (d && d.account) || {};
            const m = (d && d.member) || {};
            const rows = [];
            rows.push('账号：' + (acc.email || (d && d.unlock ? '（会员卡直接登录，未注册账号）' : '未登录')));
            if (m && m.name) rows.push('会员：' + m.name + (m.code ? '（' + m.code + '）' : ''));
            if (m && (m.level_name || m.level)) rows.push('等级：' + (m.level_name || m.level));
            rows.push('状态：' + ((d && d.unlock) ? '✅ 已解锁全部功能' : '⛔ 未解锁，请先绑定会员卡'));
            body.innerHTML = rows.map(function (t) { return '<div>' + t + '</div>'; }).join('');
            accountRefreshButton();
        }
        async function bootGate() {
            accountRefreshButton();      // 顶栏「👤 账户」按钮文案（未登录 / 已登录邮箱）
            try {
                const d = await (await fetch('/api/member/gate')).json();
                // 临时体验卡：已登录但只开放 AI 对话 → 直接进仅对话模式，不走解锁流程
                if (d.temp) { enterTempMode((d.license || {}).member, (d.license || {}).expire_at); return; }
                if (d.unlocked) { gateHide(); return; }
                if (!d.gate || d.gate === 'none') { gateHide(); return; }
                gateShow(d.gate, d);
            } catch (e) {
                gateHide();   // 接口异常别把人卡在门外
            }
        }
        function gateMsg(id, t, err) {
            const el = document.getElementById(id);
            if (el) el.innerHTML = err ? `<span style="color:var(--error);">${t}</span>` : `<span style="color:var(--success);">${t}</span>`;
        }
        async function gateAfter() {
            const d = await (await fetch('/api/member/gate')).json();
            if (d.unlocked || !d.gate || d.gate === 'none') { gateHide(); return; }
            gateShow(d.gate, d);
        }
        async function gateSubmitMember() {
            const code = (document.getElementById('gateMemberCode') || {}).value || '';
            const name = (document.getElementById('gateMemberName') || {}).value || '';
            if (!code.trim()) { gateMsg('gateMemberMsg', '请输入会员号', true); return; }
            // 名字可以留空（卡号已绑定名字时后端会自动取用）；填了就要合规
            if (name.trim() && !/^[\u4e00-\u9fa5A-Za-z0-9_\-·]{2,12}$/.test(name.trim())) {
                gateMsg('gateMemberMsg', '会员名称须为 2-12 个字（中文 / 字母 / 数字）', true);
                return;
            }
            gateMsg('gateMemberMsg', '验证中…');
            const d = await _qJson(await fetch('/api/member/license/activate', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ code: code.trim(), name: name.trim() })
            }));
            if (!d.success) { gateMsg('gateMemberMsg', d.error || '激活失败', true); return; }
            showToast(d.message, 'success');
            await gateAfter();
        }
        function gateToggleAdmin() {
            const b = document.getElementById('gateAdminBox');
            if (b) b.style.display = b.style.display === 'none' ? 'block' : 'none';
        }
        async function _gateTestKey(vendor, key) {
            // 返回 {ok, soft}：ok=测试通过；soft=非鉴权类失败（超时/网络），允许保存不拦人
            try {
                const r = await fetch('/api/config/test-key', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ vendor: vendor, api_key: key })
                });
                const d = await r.json();
                if (d.success) return { ok: true, soft: false, msg: d.message || '有效' };
                const hard = /无效|被拒绝/.test(d.error || '');
                return { ok: false, soft: !hard, msg: d.error || '测试失败' };
            } catch (e) {
                return { ok: false, soft: true, msg: '网络异常：' + e.message };
            }
        }
        async function gateSubmitVendors() {
            const skEl = document.getElementById('gateSenseNovaKey'), akEl = document.getElementById('gateAgnesKey');
            const sk = ((skEl || {}).value || '').trim(), ak = ((akEl || {}).value || '').trim();
            if (!sk) { gateMsg('gateVendorsMsg', '请填写商汤 SenseNova Key（必填）', true); return; }
            if (!ak) { gateMsg('gateVendorsMsg', '请填写 AGNES 平台 Key（必填）', true); return; }
            //    后端 _write_config_target() 也会拦 —— 页面提示可以绕过去，落盘不能。
            if (!/^sk-/i.test(ak)) {
                gateMsg('gateVendorsMsg', '⚠️ AGNES Key 必须是国际站 Key（以 sk- 开头）。国内站 Key（wk- 开头）与本平台接口不通用，填了会一直返回「无效令牌」。', true);
                return;
            }
            gateMsg('gateVendorsMsg', '正在验证两把 KEY 的有效性，请稍候…');
            const t1 = await _gateTestKey('sensenova', sk);
            if (!t1.ok && !t1.soft) { gateMsg('gateVendorsMsg', '❌ 商汤 Key 验证未通过：' + t1.msg, true); return; }
            const t2 = await _gateTestKey('agnes', ak);
            if (!t2.ok && !t2.soft) { gateMsg('gateVendorsMsg', '❌ AGNES Key 验证未通过：' + t2.msg, true); return; }
            const d = await (await fetch('/api/config', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ sensenova_api_key: sk, api_key: ak })
            })).json();
            if (!d.success) { gateMsg('gateVendorsMsg', d.error || '保存失败，请重试', true); return; }
            gateMsg('gateVendorsMsg', '✅ 双 KEY 已验证并保存到你的会员独立空间');
            showToast('双平台 KEY 配置完成，欢迎加入！', 'success');
            if (typeof checkApiKeyStatus === 'function') checkApiKeyStatus();
            await gateAfter();
        }
