        function _provFillSelect(sel, map, current) {
            if (!sel) return;
            sel.innerHTML = Object.keys(map).map(function (k) {
                return '<option value="' + k + '">' + map[k] + '</option>';
            }).join('');
            if (current) sel.value = current;
        }
        // V1.8.207：设置弹窗全部抽屉化 —— 打开时把 11 个 settings-panel 收成「一列标题」，
        // 用户点哪个标题就展开哪个（再点收起）。用 dataset 打标只初始化一次，
        // 避免每次开窗重复绑 listener（绑两次会一次点击展开又立刻收起 = 看着没反应）。
        function initSettingsAccordion() {
            document.querySelectorAll('#tab-providers .settings-panel').forEach(function (p) {
                if (p.dataset.accReady === '1') return;
                p.dataset.accReady = '1';
                p.classList.add('collapsed');       // 默认全部收起
                let h = null;
                for (const c of p.children) {
                    if (c.classList && c.classList.contains('prov-h')) { h = c; break; }
                }
                if (!h) return;
                h.setAttribute('role', 'button');
                h.setAttribute('tabindex', '0');
                const toggle = function () { p.classList.toggle('collapsed'); };
                h.addEventListener('click', toggle);
                h.addEventListener('keydown', function (e) {
                    if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggle(); }
                });
            });
        }

        function openProvidersModal() {
            const ov = document.getElementById('providersModal');
            const pane = document.getElementById('tab-providers');
            if (ov) ov.style.display = 'flex';
            if (pane) pane.classList.add('active');   // tab-content 默认 display:none，浮窗里也要点亮
            initSettingsAccordion();
            if (typeof loadProvidersModule === 'function') loadProvidersModule();
        }

        function closeProvidersModal() {
            const ov = document.getElementById('providersModal');
            const pane = document.getElementById('tab-providers');
            if (ov) ov.style.display = 'none';
            if (pane) pane.classList.remove('active');
        }

        async function loadProvidersModule() {
            _provFillSelect(document.getElementById('provTextModel'), PROV_TEXT_MODELS, null);
            _provFillSelect(document.getElementById('provImageModel'), PROV_IMAGE_MODELS, null);
            _provFillSelect(document.getElementById('provVideoModel'), PROV_VIDEO_MODELS, null);
            try {
                const cfg = await (await fetch('/api/config')).json();
                const tm = cfg.default_text_model || 'agnes-3.0-flash';
                const im = cfg.default_image_model || 'sensenova-u1.5-lite';
                const vm = cfg.default_video_model || 'agnes-video-2.5-flash';
                const tSel = document.getElementById('provTextModel');
                const iSel = document.getElementById('provImageModel');
                const vSel = document.getElementById('provVideoModel');
                if (tSel && PROV_TEXT_MODELS[tm]) tSel.value = tm;
                if (iSel && PROV_IMAGE_MODELS[im]) iSel.value = im;
                if (vSel && PROV_VIDEO_MODELS[vm]) vSel.value = vm;
                // Key 输入框 placeholder 显示已配置状态
                if (cfg.api_key_masked) { const e = document.getElementById('apiKeyInput'); if (e) e.placeholder = '已配置: ' + cfg.api_key_masked; }
                if (cfg.deepseek_api_key_masked) { const e = document.getElementById('deepseekApiKeyInput'); if (e) e.placeholder = '已配置: ' + cfg.deepseek_api_key_masked; }
                if (cfg.doubao_api_key_masked) { const e = document.getElementById('doubaoApiKeyInput'); if (e) e.placeholder = '已配置: ' + cfg.doubao_api_key_masked; }
                if (cfg.qwen_api_key_masked) { const e = document.getElementById('qwenApiKeyInput'); if (e) e.placeholder = '已配置: ' + cfg.qwen_api_key_masked; }
                if (cfg.minimax_api_key_masked) { const e = document.getElementById('minimaxApiKeyInput'); if (e) e.placeholder = '已配置: ' + cfg.minimax_api_key_masked; }
                if (cfg.dots_api_key_masked) { const e = document.getElementById('dotsApiKeyInput'); if (e) e.placeholder = '已配置: ' + cfg.dots_api_key_masked; }
                const sn = document.getElementById('sensenovaTextKeyInput');
                if (sn) sn.placeholder = cfg.sensenova_api_key_masked ? '已配置: ' + cfg.sensenova_api_key_masked : '商汤 API Key（文本 + 生图共用）';
            } catch (e) { /* ignore */ }
            if (typeof loadSensenovaImageKeys === 'function') loadSensenovaImageKeys();
            if (typeof mountVideoKeys === 'function') mountVideoKeys('provVideoKeysPanel');
            if (typeof loadOllamaConfig === 'function') loadOllamaConfig();
            if (typeof updateLoadStatus === 'function') updateLoadStatus();
            if (typeof renderBuykeyList === 'function') renderBuykeyList();
            if (typeof loadMemberModule === 'function') loadMemberModule();
            if (typeof loadInkosTemplates === 'function') loadInkosTemplates();
        }
        async function saveProvidersModels() {
            const tSel = document.getElementById('provTextModel');
            const iSel = document.getElementById('provImageModel');
            const vSel = document.getElementById('provVideoModel');
            const st = document.getElementById('provModelStatus');
            if (!tSel || !iSel || !vSel) return;
            st.textContent = '保存中…';
            try {
                const d = await (await fetch('/api/config', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        default_text_model: tSel.value,
                        default_image_model: iSel.value,
                        default_video_model: vSel.value
                    })
                })).json();
                if (d.success) {
                    st.innerHTML = '<span style="color:var(--success);">✅ 默认模型已保存</span>';
                    showToast('全局默认模型已保存', 'success');
                } else {
                    st.innerHTML = '<span style="color:var(--error);">' + (d.message || '保存失败') + '</span>';
                }
            } catch (e) {
                st.innerHTML = '<span style="color:var(--error);">保存失败: ' + e.message + '</span>';
            }
        }

        async function loadInkosTemplates() {
            const wEl = document.getElementById('inkosTplWriting');
            const iEl = document.getElementById('inkosTplImage');
            const stEl = document.getElementById('inkosTplStatus');
            if (!wEl || !iEl) return;
            try {
                const d = await (await fetch('/api/inkos/templates')).json();
                if (typeof d.writing === 'string') wEl.value = d.writing;
                if (typeof d.image === 'string') iEl.value = d.image;
                if (stEl) stEl.innerHTML = '<span style="color:var(--text2);">已加载（默认/已保存）</span>';
            } catch (e) {
                if (stEl) stEl.innerHTML = '<span style="color:var(--error);">加载失败: ' + e.message + '</span>';
            }
        }
        async function saveInkosTemplates() {
            const wEl = document.getElementById('inkosTplWriting');
            const iEl = document.getElementById('inkosTplImage');
            const stEl = document.getElementById('inkosTplStatus');
            if (!wEl || !iEl) return;
            const token = (sessionStorage.getItem('adminToken') || localStorage.getItem('adminToken') || '').trim();
            if (!token) {
                if (stEl) stEl.innerHTML = '<span style="color:var(--error);">请先到「会员」页登录管理密码</span>';
                return;
            }
            if (stEl) stEl.innerHTML = '<span style="color:var(--text2);">保存中…</span>';
            try {
                const r = await fetch('/api/inkos/templates', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'X-Admin-Token': token },
                    body: JSON.stringify({ writing: wEl.value, image: iEl.value })
                });
                const d = await r.json();
                if (d.success) {
                    if (stEl) stEl.innerHTML = '<span style="color:var(--success);">✅ 已保存（已写入 InkOS .env，studio 重启生效）</span>';
                    showToast('写作/生图模板已保存', 'success');
                } else {
                    if (stEl) stEl.innerHTML = '<span style="color:var(--error);">' + (d.error || '保存失败') + '</span>';
                }
            } catch (e) {
                if (stEl) stEl.innerHTML = '<span style="color:var(--error);">保存失败: ' + e.message + '</span>';
            }
        }
