        function renderBuykeyList() {
            const el = document.getElementById('buykeyList');
            if (!el || el.dataset.rendered) return;
            el.innerHTML = KEY_PLATFORMS.map(p => `
                <a href="${p.url}" target="_blank" rel="noopener"
                   style="display:flex;align-items:center;gap:12px;padding:10px 14px;border:1px solid var(--border);
                          border-radius:10px;background:var(--surface2);text-decoration:none;color:inherit;
                          transition:border-color .15s;" onmouseover="this.style.borderColor='var(--accent)'"
                   onmouseout="this.style.borderColor='var(--border)'">
                    <span style="font-size:22px;line-height:1;">${p.icon}</span>
                    <span style="flex:1;">
                        <span style="display:block;font-size:13px;font-weight:600;color:var(--accent);">${p.name} ↗</span>
                        <span style="display:block;font-size:12px;color:var(--text2);margin-top:2px;">${p.note}</span>
                        <span style="display:block;font-size:11px;color:var(--text2);opacity:.75;margin-top:1px;">${p.url}</span>
                    </span>
                </a>`).join('');
            el.dataset.rendered = '1';
        }

        let updPending = null;      // 最近一次 check 的结果，apply 时复用

        function _updFmt(bytes) {
            if (!bytes) return '0 KB';
            return bytes > 1048576 ? (bytes / 1048576).toFixed(2) + ' MB'
                                   : (bytes / 1024).toFixed(1) + ' KB';
        }

        async function updateLoadStatus() {
            try {
                const d = await (await fetch('/api/update/status')).json();
                if (!d.success) return;
                const el = document.getElementById('updCurrentVer');
                if (el) {
                    el.textContent = d.current_version +
                        (d.updated ? '（已应用云端更新，内置 ' + d.builtin_version + '）' : '');
                }
                const src = document.getElementById('updSourceInput');
                if (src && !src.value) src.value = d.update_url || '';
            } catch (e) { /* 忽略：设置面板其它功能不受影响 */ }
        }

        async function updateSaveSource() {
            const v = (document.getElementById('updSourceInput') || {}).value || '';
            try {
                const d = await (await fetch('/api/update/source', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ url: v.trim() })
                })).json();
                showToast(d.success ? (d.message || '已保存') : ('保存失败：' + d.error),
                          d.success ? 'success' : 'error');
            } catch (e) { showToast('保存失败：' + e.message, 'error'); }
        }

        async function updateCheck() {
            const btn = document.getElementById('updCheckBtn');
            const box = document.getElementById('updResult');
            if (!box) return;
            if (btn) { btn.disabled = true; btn.textContent = '🔍 检查中…'; }
            box.innerHTML = '<span style="color:var(--text2);">正在比对云端清单…</span>';
            try {
                const d = await (await fetch('/api/update/check', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({})
                })).json();
                if (!d.success) {
                    box.innerHTML = '<span style="color:var(--error);">' + (d.error || '检查失败') + '</span>';
                    return;
                }
                if (d.up_to_date) {
                    box.innerHTML = '<span style="color:var(--success);">✓ 已是最新（' +
                        d.current + '）</span>';
                    return;
                }

                if (d.needs_full) {
                    const f = d.full || {};
                    box.innerHTML = '<div style="color:var(--warning);">这个版本需要<b>全量重装</b>' +
                        '（改了依赖或目录结构，增量更新不适用）。</div>' +
                        (f.url ? '<div style="margin-top:6px;"><a href="' + f.url +
                            '" target="_blank" class="btn btn-sm btn-primary">⬇ 下载完整安装包' +
                            (f.size ? '（' + _updFmt(f.size) + '）' : '') + '</a></div>' : '');
                    return;
                }

                updPending = d;
                const kind = d.repair ? '本地文件与云端不一致' :
                             (d.newer ? '有新版本' : '有更新');
                const notes = (d.notes || []).length
                    ? '<div style="margin:6px 0;color:var(--text2);">更新日志：' +
                      (d.notes || []).map(n => '<div>· ' + n + '</div>').join('') + '</div>'
                    : '';
                box.innerHTML =
                    '<div>' + kind + '：<b>' + d.current + '</b> → <b style="color:var(--accent);">' +
                    d.latest + '</b></div>' + notes +
                    '<div style="margin-top:6px;">需同步 <b>' + d.changes.length +
                    '</b> 个文件（共 ' + _updFmt(d.total_bytes) + '），只下载哈希不同的：</div>' +
                    '<div style="max-height:150px;overflow-y:auto;background:var(--surface2);' +
                    'border-radius:6px;padding:8px;margin:6px 0;font-size:12px;">' +
                    d.changes.map(c => '<div>' + c.rel + ' <span style="color:var(--text2);">' +
                        _updFmt(c.size) + '</span></div>').join('') + '</div>' +
                    '<button class="btn btn-sm btn-primary" onclick="updateApply()">⬇ 立即更新</button>' +
                    '<div style="color:var(--text2);font-size:12px;margin-top:6px;">' +
                    '更新完成后需要重启程序才生效。</div>';
            } catch (e) {
                box.innerHTML = '<span style="color:var(--error);">检查异常：' + e.message + '</span>';
            } finally {
                if (btn) { btn.disabled = false; btn.textContent = '🔍 检查更新'; }
            }
        }

        async function updateApply() {
            if (!updPending) { showToast('请先点「检查更新」', 'error'); return; }
            const box = document.getElementById('updResult');
            if (box) box.innerHTML = '<span style="color:var(--text2);">正在下载并校验…</span>';
            try {
                const d = await (await fetch('/api/update/apply', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ confirm: true })
                })).json();
                if (!d.success) {
                    box.innerHTML = '<span style="color:var(--error);">' + (d.error || '更新失败') +
                        '</span>' + ((d.failed || []).length
                            ? '<div style="font-size:12px;margin-top:6px;">' +
                              d.failed.map(f => '<div>· ' + f.rel + '：' + f.error + '</div>').join('') +
                              '</div>' : '');
                    return;
                }
                box.innerHTML = '<div style="color:var(--success);">✓ 已更新 ' + d.applied.length +
                    ' 个文件（' + _updFmt(d.bytes) + '），版本 ' + d.version + '</div>' +
                    '<div style="margin-top:6px;color:var(--warning);">请重启程序生效。</div>';
                showToast('更新完成，请重启程序', 'success');
                updPending = null;
                updateLoadStatus();
            } catch (e) {
                if (box) box.innerHTML = '<span style="color:var(--error);">更新异常：' + e.message + '</span>';
            }
        }

        let ollamaDetectedModels = [];

        async function loadOllamaConfig() {
            try {
                const resp = await fetch('/api/ollama/config');
                const data = await resp.json();
                if (data.success) {
                    const cfg = data.config;
                    document.getElementById('ollamaEnabled').checked = cfg.enabled || false;
                    document.getElementById('ollamaBaseUrl').value = cfg.base_url || 'http://localhost:11434';
                    toggleOllamaSection();
                    if (cfg.enabled && cfg.models && cfg.models.length > 0) {
                        ollamaDetectedModels = cfg.models;
                        document.getElementById('ollamaModelsResult').innerHTML = 
                            `<span style="color:var(--success);">✅ 已启用，检测到 ${cfg.models.length} 个模型: ${cfg.models.join(', ')}</span>`;
                    }
                }
            } catch (e) {
                console.error('加载 Ollama 配置失败:', e);
            }
        }

        function toggleOllamaSection() {
            const enabled = document.getElementById('ollamaEnabled').checked;
            document.getElementById('ollamaBaseUrl').disabled = !enabled;
            document.getElementById('ollamaDetectBtn').disabled = !enabled;
            if (!enabled) {
                document.getElementById('ollamaModelsResult').innerHTML = '';
            }
        }

        async function detectOllamaModels() {
            const baseUrl = document.getElementById('ollamaBaseUrl').value.trim() || 'http://localhost:11434';
            const btn = document.getElementById('ollamaDetectBtn');
            const resultEl = document.getElementById('ollamaModelsResult');
            btn.disabled = true;
            btn.textContent = '🔄 检测中...';
            resultEl.innerHTML = '';
            try {
                const resp = await fetch('/api/ollama/detect', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ base_url: baseUrl })
                });
                const data = await resp.json();
                if (data.success && data.models.length > 0) {
                    ollamaDetectedModels = data.models;
                    resultEl.innerHTML = `<span style="color:var(--success);">✅ 检测到 ${data.models.length} 个模型:</span><br>` +
                        data.models.map(m => `<label style="display:inline-flex;align-items:center;gap:2px;margin:2px 4px;font-size:11px;cursor:pointer;">
                            <input type="checkbox" class="ollama-model-cb" value="${m}" checked> ${m}
                        </label>`).join('');
                } else if (data.success) {
                    resultEl.innerHTML = '<span style="color:var(--text2);">Ollama 已连接，但未找到可用模型。请先用 `ollama pull` 下载模型</span>';
                    ollamaDetectedModels = [];
                } else {
                    resultEl.innerHTML = `<span style="color:var(--error);">❗ ${data.error || '检测失败'}</span>`;
                }
            } catch (e) {
                resultEl.innerHTML = `<span style="color:var(--error);">❗ 检测失败: ${e.message}</span>`;
            }
            btn.disabled = false;
            btn.textContent = '🔍 检测模型';
        }

        async function saveOllamaConfig() {
            const enabled = document.getElementById('ollamaEnabled').checked;
            const baseUrl = document.getElementById('ollamaBaseUrl').value.trim() || 'http://localhost:11434';
            // 收集勾选的模型
            const checkboxes = document.querySelectorAll('.ollama-model-cb:checked');
            const models = Array.from(checkboxes).map(cb => cb.value);
            try {
                const resp = await fetch('/api/ollama/config', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ enabled, base_url: baseUrl, models })
                });
                const data = await resp.json();
                if (data.success) {
                    showToast('Ollama 配置已保存', 'success');
                    // 刷新模型下拉列表
                    if (typeof loadDramaModels === 'function') loadDramaModels();
                }
            } catch (e) {
                showToast('保存 Ollama 配置失败: ' + e.message, 'error');
            }
        }

        // 快捷预设：选中后自动填充表单，用户不用手填
        const CUSTOM_MODEL_PRESETS = {
            'pool_doubao:seedance_2_0_mini': {
                name: '豆包账号池 (Seedance 2.0 Mini)',
                type: 'video',
                base_url: 'http://127.0.0.1:17888',
                api_key: 'local-doubao-key'
            },
            'pool_doubao:seedance_2_0_fast': {
                name: '豆包账号池 (Seedance 2.0 Fast)',
                type: 'video',
                base_url: 'http://127.0.0.1:17888',
                api_key: 'local-doubao-key'
            },
            'pool_dola:seedance-v2.0': {
                name: 'Dola账号池 (seedance-v2.0)',
                type: 'video',
                base_url: 'http://127.0.0.1:8000',
                api_key: 'sk-local-key'
            }
        };

        // 号池预设的 Key 已自动填好，锁定不允许修改，防止改错导致 401 报错；
        // 手动填写（通用）时才允许自定义 Key。
        function setApiKeyLocked(locked) {
            const input = document.getElementById('customModelApiKey');
            const hint = document.getElementById('customModelApiKeyLockHint');
            input.readOnly = locked;
            input.style.opacity = locked ? '0.6' : '1';
            input.style.cursor = locked ? 'not-allowed' : 'text';
            hint.style.display = locked ? 'inline' : 'none';
        }

        function applyCustomModelPreset() {
            const presetId = document.getElementById('customModelPreset').value;
            const p = CUSTOM_MODEL_PRESETS[presetId];
            if (!p) {
                // 手动填写：清空表单
                ['customModelId', 'customModelName', 'customModelBaseUrl', 'customModelApiKey'].forEach(id => {
                    document.getElementById(id).value = '';
                });
                document.getElementById('customModelType').value = 'text';
                setApiKeyLocked(false);
                return;
            }
            document.getElementById('customModelId').value = presetId;
            document.getElementById('customModelName').value = p.name;
            document.getElementById('customModelType').value = p.type;
            document.getElementById('customModelBaseUrl').value = p.base_url;
            document.getElementById('customModelApiKey').value = p.api_key;
            setApiKeyLocked(true);
        }

        async function loadCustomModelsList() {
            try {
                const resp = await fetch('/api/custom-models');
                const data = await resp.json();
                const el = document.getElementById('customModelsList');
                if (!data.models || data.models.length === 0) {
                    el.innerHTML = '<div style="font-size:11px;color:var(--text2);">暂无自定义模型</div>';
                    return;
                }
                const typeLabels = { text: '📝文本', image: '🖼生图', video: '🎬视频' };
                el.innerHTML = data.models.map(m => `
                    <div style="display:flex;justify-content:space-between;align-items:center;padding:4px 8px;background:var(--surface2);border-radius:4px;margin-bottom:4px;font-size:11px;">
                        <span><b>${m.name}</b> <span style="color:var(--text2);">[${typeLabels[m.type] || m.type}]</span> <code style="font-size:10px;color:var(--accent);">${m.id}</code></span>
                        <button onclick="deleteCustomModel('${m.id}')" style="color:var(--error);background:none;border:none;cursor:pointer;font-size:12px;" title="删除">✖</button>
                    </div>
                `).join('');
            } catch (e) {
                console.error('加载自定义模型失败:', e);
            }
        }

        async function saveCustomModel() {
            const modelId = document.getElementById('customModelId').value.trim();
            const displayName = document.getElementById('customModelName').value.trim();
            const modelType = document.getElementById('customModelType').value;
            const baseUrl = document.getElementById('customModelBaseUrl').value.trim();
            const apiKey = document.getElementById('customModelApiKey').value.trim();

            if (!modelId || !displayName || !baseUrl) {
                showToast('请填写模型 ID、名称和 API 地址', 'error');
                return;
            }

            try {
                const resp = await fetch('/api/custom-models', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        model_id: modelId,
                        display_name: displayName,
                        model_type: modelType,
                        base_url: baseUrl,
                        api_key: apiKey
                    })
                });
                const data = await resp.json();
                if (data.success) {
                    showToast('自定义模型已添加', 'success');
                    document.getElementById('addCustomModelForm').style.display = 'none';
                    // 清空输入框 + 重置预设
                    ['customModelId', 'customModelName', 'customModelBaseUrl', 'customModelApiKey'].forEach(id => {
                        document.getElementById(id).value = '';
                    });
                    document.getElementById('customModelPreset').value = '';
                    setApiKeyLocked(false);
                    // 重新加载模型列表
                    loadDramaModels();
                } else {
                    showToast('添加失败: ' + (data.error || ''), 'error');
                }
            } catch (e) {
                showToast('添加失败: ' + e.message, 'error');
            }
        }

        async function deleteCustomModel(modelId) {
            if (!confirm(`确定要删除模型 "${modelId}" 吗？`)) return;
            try {
                const resp = await fetch('/api/custom-models', {
                    method: 'DELETE',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ model_id: modelId })
                });
                const data = await resp.json();
                if (data.success) {
                    showToast('已删除', 'success');
                    loadCustomModelsList();
                    loadDramaModels();
                } else {
                    showToast('删除失败: ' + (data.error || ''), 'error');
                }
            } catch (e) {
                showToast('删除失败: ' + e.message, 'error');
            }
        }

        // V1.8.207：Agnes 主 KEY 单独的「保存 / 一键清空」。
        // 以前只能靠下面「💾 保存全部 Key」保存，清空更是没入口（想换 KEY 只能覆盖）。
        // 后端 /api/config 已支持 api_key='__clear__' = 删除该字段，清空走这条路。
        async function saveAgnesKey() {
            const el = document.getElementById('apiKeyInput');
            const st = document.getElementById('agnesKeyStatus');
            const v = (el && el.value ? el.value : '').trim();
            if (!v) { showToast('请先填入 Agnes KEY', 'error'); return; }
            try {
                const d = await (await fetch('/api/config', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ api_key: v })
                })).json();
                if (d.success) {
                    el.value = '';
                    const cfg = await (await fetch('/api/config')).json();
                    el.placeholder = cfg.api_key_masked ? `已配置: ${cfg.api_key_masked}` : 'sk-…';
                    if (st) st.textContent = '已保存';
                    showToast('Agnes KEY 已保存', 'success');
                } else {
                    // 后端 key_endpoint_mismatch 会给出人话（如 wk- 打国际站必 401）
                    showToast(d.error || d.message || '保存失败', 'error');
                }
            } catch (e) { showToast('保存失败: ' + e.message, 'error'); }
        }

        async function clearAgnesKey() {
            if (!confirm('确定清空 Agnes 主 KEY？\n\n'
                       + '· 只清这一把（其它厂商 KEY、视频 KEY 池都不动）\n'
                       + '· 清空后 Agnes 系列模型（文本 / 生图 / 生视频）立即不可用，\n'
                       + '  直到你重新填入 KEY 并保存。')) return;
            const btn = document.getElementById('agnesKeyClearBtn');
            const st = document.getElementById('agnesKeyStatus');
            if (btn) btn.disabled = true;
            try {
                const d = await (await fetch('/api/config', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ api_key: '__clear__' })
                })).json();
                if (d.success) {
                    const el = document.getElementById('apiKeyInput');
                    if (el) { el.value = ''; el.placeholder = 'sk-…'; }
                    if (st) st.textContent = '已清空';
                    showToast('Agnes KEY 已清空', 'success');
                    if (typeof checkApiKeyStatus === 'function') checkApiKeyStatus();
                } else {
                    showToast(d.error || d.message || '清空失败', 'error');
                }
            } catch (e) {
                showToast('清空失败: ' + e.message, 'error');
            } finally {
                if (btn) btn.disabled = false;
            }
        }

        async function saveApiKey() {
            const apiKey = document.getElementById('apiKeyInput').value.trim();
            const deepseekApiKey = document.getElementById('deepseekApiKeyInput').value.trim();
            const doubaoApiKey = document.getElementById('doubaoApiKeyInput').value.trim();
            const qwenApiKey = document.getElementById('qwenApiKeyInput').value.trim();
            const minimaxApiKey = document.getElementById('minimaxApiKeyInput').value.trim();
            const dotsApiKey = document.getElementById('dotsApiKeyInput').value.trim();
            const sensenovaKey = (document.getElementById('sensenovaTextKeyInput') || {}).value || '';
            const ollamaEnabled = document.getElementById('ollamaEnabled').checked;
            if (!apiKey && !deepseekApiKey && !doubaoApiKey && !qwenApiKey && !minimaxApiKey
                && !dotsApiKey && !sensenovaKey.trim() && !ollamaEnabled) {
                showToast('请至少输入一个 API Key 或启用 Ollama', 'error');
                return;
            }
            try {
                const payload = { api_key: apiKey };
                if (deepseekApiKey) payload.deepseek_api_key = deepseekApiKey;
                if (doubaoApiKey) payload.doubao_api_key = doubaoApiKey;
                if (qwenApiKey) payload.qwen_api_key = qwenApiKey;
                if (minimaxApiKey) payload.minimax_api_key = minimaxApiKey;
                if (dotsApiKey) payload.dots_api_key = dotsApiKey;
                if (sensenovaKey.trim()) payload.sensenova_api_key = sensenovaKey.trim();
                const resp = await fetch('/api/config', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                });
                const data = await resp.json();
                if (data.success) {
                    showToast('API Key 已保存', 'success');
                    // 刷新 placeholder 显示
                    ['apiKeyInput', 'deepseekApiKeyInput', 'doubaoApiKeyInput', 'qwenApiKeyInput', 'minimaxApiKeyInput',
                     'dotsApiKeyInput', 'sensenovaTextKeyInput'].forEach(id => {
                        const el = document.getElementById(id);
                        if (el) el.value = '';
                    });
                    const cfg = await (await fetch('/api/config')).json();
                    if (cfg.api_key_masked) document.getElementById('apiKeyInput').placeholder = `已配置: ${cfg.api_key_masked}`;
                    else document.getElementById('apiKeyInput').placeholder = 'sk-...';
                    if (cfg.deepseek_api_key_masked) document.getElementById('deepseekApiKeyInput').placeholder = `已配置: ${cfg.deepseek_api_key_masked}`;
                    if (cfg.doubao_api_key_masked) document.getElementById('doubaoApiKeyInput').placeholder = `已配置: ${cfg.doubao_api_key_masked}`;
                    if (cfg.qwen_api_key_masked) document.getElementById('qwenApiKeyInput').placeholder = `已配置: ${cfg.qwen_api_key_masked}`;
                    if (cfg.minimax_api_key_masked) document.getElementById('minimaxApiKeyInput').placeholder = `已配置: ${cfg.minimax_api_key_masked}`;
                    if (cfg.dots_api_key_masked) document.getElementById('dotsApiKeyInput').placeholder = `已配置: ${cfg.dots_api_key_masked}`;
                    const sn2 = document.getElementById('sensenovaTextKeyInput');
                    if (sn2) sn2.placeholder = cfg.sensenova_api_key_masked ? `已配置: ${cfg.sensenova_api_key_masked}` : '商汤 API Key（文本 + 生图共用）';
                    checkApiKeyStatus();
                } else {
                    showToast(data.message || '保存失败', 'error');
                }
                // 同时保存 Ollama 配置
                await saveOllamaConfig();
            } catch (e) {
                showToast('保存失败: ' + e.message, 'error');
            }
        }

        // 测某厂商的 KEY 通不通（留空则测已保存的那把）
        async function testVendorKey(vendor, inputId) {
            const el = document.getElementById(inputId);
            const statusId = vendor === 'sensenova' ? 'sensenovaTextKeyStatus' : null;
            const box = statusId ? document.getElementById(statusId) : null;
            const v = (el && el.value ? el.value : '').trim();
            if (box) box.innerHTML = '<span style="color:var(--text2);">正在测试…</span>';
            try {
                const d = await (await fetch('/api/config/test-key', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ vendor: vendor, api_key: v })
                })).json();
                const ok = !!d.success;
                const msg = ok ? ('✓ ' + (d.message || '有效')) : ('✗ ' + (d.error || '测试失败'));
                if (box) box.innerHTML = `<span style="color:${ok ? 'var(--success)' : 'var(--error)'};">${msg}</span>`;
                else showToast(msg, ok ? 'success' : 'error');
            } catch (e) {
                if (box) box.innerHTML = '<span style="color:var(--error);">测试异常：' + e.message + '</span>';
                else showToast('测试异常：' + e.message, 'error');
            }
        }

        // 车道数由后端按「配了几把 KEY」算：两把 → 2 条车道；一把 → 单线。
        // 单 KEY 用户不会被强制双线，缺哪把都不会跑不起来。
        async function loadSensenovaImageKeys() {
            const box = document.getElementById('sensenovaImageKeyStatus');
            try {
                const d = await (await fetch('/api/image/lanes')).json();
                const aEl = document.getElementById('sensenovaImageKeyAInput');
                const bEl = document.getElementById('sensenovaImageKeyBInput');
                if (aEl) aEl.placeholder = d.key_a_masked ? ('已配置: ' + d.key_a_masked) : '商汤 KEY A（未配置）';
                if (bEl) bEl.placeholder = d.key_b_masked ? ('已配置: ' + d.key_b_masked) : '商汤 KEY B（不填就是单线）';
                if (box) {
                    box.innerHTML = d.dual
                        ? '<span style="color:var(--success);">✓ 双 KEY 已配置（' + (d.key_a_masked || 'A') + ' ＋ ' + (d.key_b_masked || 'B') + '）→ 排队生图可开 2 条车道</span>'
                        : '<span style="color:var(--warning);">当前 ' + (d.count || 0) + ' 把 KEY → 单线运行（再填一把即可双线）</span>';
                }
                return d;
            } catch (e) {
                if (box) box.innerHTML = '<span style="color:var(--error);">检测失败：' + e.message + '</span>';
                return null;
            }
        }

        async function saveSensenovaImageKeys() {
            const aEl = document.getElementById('sensenovaImageKeyAInput');
            const bEl = document.getElementById('sensenovaImageKeyBInput');
            const a = (aEl && aEl.value ? aEl.value : '').trim();
            const b = (bEl && bEl.value ? bEl.value : '').trim();
            if (!a && !b) { showToast('请至少填写一把商汤 KEY', 'error'); return; }
            const payload = {};
            if (a) payload.sensenova_api_key = a;
            if (b) payload.sensenova_api_key_b = b;
            try {
                const d = await (await fetch('/api/config', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(payload)
                })).json();
                if (!d.success) { showToast(d.message || '保存失败', 'error'); return; }
                showToast(b ? '双 KEY 已保存：排队生图可开 2 条车道' : 'KEY 已保存（单线运行）', 'success');
                if (aEl) aEl.value = '';
                if (bEl) bEl.value = '';
                await loadSensenovaImageKeys();
                if (typeof queueRefreshLanes === 'function') queueRefreshLanes();
            } catch (e) {
                showToast('保存失败: ' + e.message, 'error');
            }
        }

        async function clearSensenovaImageKeyB() {
            if (!confirm('确定清空 B 槽 KEY？清空后排队生图器会退回单线运行。')) return;
            try {
                const d = await (await fetch('/api/config', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ sensenova_api_key_b: '__clear__' })
                })).json();
                if (d.success) {
                    showToast('B 槽已清空，排队生图退回单线', 'success');
                    await loadSensenovaImageKeys();
                    if (typeof queueRefreshLanes === 'function') queueRefreshLanes();
                } else showToast(d.message || '清空失败', 'error');
            } catch (e) { showToast('清空失败: ' + e.message, 'error'); }
        }

        async function testSensenovaImageKey(slot) {
            const id = (slot === 1) ? 'sensenovaImageKeyBInput' : 'sensenovaImageKeyAInput';
            const box = document.getElementById('sensenovaImageKeyStatus');
            const el = document.getElementById(id);
            const v = (el && el.value ? el.value : '').trim();
            if (!v) {
                if (box) box.innerHTML = '<span style="color:var(--error);">请先填入要测试的 KEY</span>';
                return;
            }
            if (box) box.innerHTML = '<span style="color:var(--text2);">正在测试…</span>';
            try {
                const d = await (await fetch('/api/config/test-key', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ vendor: 'sensenova', api_key: v })
                })).json();
                const ok = !!d.success;
                const msg = ok ? ('✓ ' + (d.message || '有效')) : ('✗ ' + (d.error || '测试失败'));
                if (box) box.innerHTML = '<span style="color:' + (ok ? 'var(--success)' : 'var(--error)') + ';">' + msg + '</span>';
            } catch (e) {
                if (box) box.innerHTML = '<span style="color:var(--error);">测试异常：' + e.message + '</span>';
            }
        }

        let MEMBER_TOKEN = localStorage.getItem('agnes_admin_token') || '';
        let MEMBER_DATA = { unlocked: false };
        let mCardStatus = '', mMemStatus = '', mPanel = 'cards';
        let mSelected = new Set();

        function _mHdr() {
            const h = { 'Content-Type': 'application/json' };
            if (MEMBER_TOKEN) h['X-Admin-Token'] = MEMBER_TOKEN;
            return h;
        }

        async function _mFetch(path, opts) {
            const r = await fetch(path, Object.assign({ headers: _mHdr() }, opts || {}));
            let d = {};
            try { d = await r.json(); } catch (e) { d = {}; }
            if (r.status === 401 || d.need_admin) {
                MEMBER_TOKEN = '';
                localStorage.removeItem('agnes_admin_token');
                memberApplyLock();
                if (mPanel !== 'license') showToast('管理会话已失效，请重新输入管理密码', 'error');
            }
            return d;
        }

        // 老版这块只有「会员管理」——那是发卡后台，要管理密码；会员自己进去既看不到
        // 「我是谁」，也找不到登出口，换账号只能清浏览器数据。现在登录/登出放第一屏
        // （不需要密码），发卡后台折叠在后面，管理员点「⚙ 管理后台」展开。
        const MEMBER_ADMIN_OPEN_KEY = 'agnes_member_admin_open';
        let mUserPanel = 'login';
        let MEMBER_NOW = null;

        function memberToggleAdmin(force) {
            const wrap = document.getElementById('memberAdminWrap');
            const btn = document.getElementById('mAdminToggle');
            if (!wrap) return;
            const wasOpen = wrap.style.display !== 'none';
            const open = (typeof force === 'boolean') ? force : !wasOpen;
            wrap.style.display = open ? 'block' : 'none';
            try { localStorage.setItem(MEMBER_ADMIN_OPEN_KEY, open ? '1' : '0'); } catch (e) { /* 无痕模式忽略 */ }
            if (btn) {
                btn.textContent = open ? '⚙ 收起管理后台' : '⚙ 管理后台';
                btn.style.background = open ? 'var(--accent)' : '';
                btn.style.borderColor = open ? 'var(--accent)' : '';
            }
            // 只在「刚展开」时加载：否则这里会被 loadMemberModule 反调，形成死循环
            if (open && !wasOpen) loadMemberModule();
        }

        function memberUserSwitch(p) {
            mUserPanel = p;
            ['login', 'logout'].forEach(k => {
                const pane = document.getElementById('mPanel' + k.charAt(0).toUpperCase() + k.slice(1));
                const btn = document.getElementById('mTab' + k.charAt(0).toUpperCase() + k.slice(1));
                if (pane) pane.style.display = (k === p) ? 'block' : 'none';
                if (btn) {
                    btn.style.background = (k === p) ? 'var(--accent)' : '';
                    btn.style.borderColor = (k === p) ? 'var(--accent)' : '';
                }
            });
            memberRenderNow();
        }

        async function memberRefreshNow() {
            let d = {};
            try {
                const r = await fetch('/api/member/whoami?_t=' + Date.now(), { headers: _mHdr(), cache: 'no-store' });
                d = await r.json().catch(function () { return {}; });
            } catch (e) { d = {}; }
            MEMBER_NOW = (d && d.success && d.member && d.member.id) ? d : null;
            memberRenderNow();
            return MEMBER_NOW;
        }

        function memberRenderNow() {
            const now = MEMBER_NOW;
            const m = now && now.member;
            const box = document.getElementById('memberNowBox');
            if (box) {
                if (m) {
                    box.innerHTML =
                        '<div style="font-size:14px;font-weight:700;color:var(--success);">✓ 已登录：' + _mEsc(m.name || '会员') + '</div>' +
                        '<div style="font-size:12px;color:var(--text2);">卡号 <code>' + _mEsc(m.code || '-') + '</code>' +
                        (m.level_name ? '　等级 ' + _mEsc(m.level_name) : '') +
                        '　' + (m.expire_at ? '到期 ' + String(m.expire_at).slice(0, 10) : '永久有效') +
                        (now.license_valid === false ? '　<span style="color:var(--error);">授权已失效</span>' : '') + '</div>';
                } else {
                    box.innerHTML =
                        '<div style="font-size:14px;font-weight:700;">○ 未登录</div>' +
                        '<div style="font-size:12px;color:var(--text2);">输入会员卡号即可登录；要换账号请到「⏏ 会员登出」。</div>';
                }
            }
            const lbox = document.getElementById('mLogoutBox');
            if (lbox) {
                lbox.innerHTML = m
                    ? ('当前登录会员：<b>' + _mEsc(m.name || '会员') + '</b>　卡号 <code>' + _mEsc(m.code || '-') + '</code><br>' +
                       '<span style="font-size:12px;color:var(--text2);">登出会解绑这台设备并清空本机保存的 KEY，之后即可登录其它卡号。</span>')
                    : '<span style="color:var(--text2);">当前浏览器没有登录的会员，无需登出。要登录请切到「🔑 会员登录」。</span>';
            }
            const lb = document.getElementById('mLogoutBtn');
            if (lb) lb.style.display = m ? '' : 'none';
            const lt = document.getElementById('mTabLogin');
            if (lt) lt.textContent = m ? '🔑 会员登录 / 续期' : '🔑 会员登录';
        }

        async function memberLogin() {
            const code = ((document.getElementById('mLoginCode') || {}).value || '').trim();
            const name = ((document.getElementById('mLoginName') || {}).value || '').trim();
            const box = document.getElementById('mLoginMsg');
            if (!box) return;
            if (!code) { box.innerHTML = '<span style="color:var(--error);">请输入会员卡号</span>'; return; }
            if (name && !/^[\u4e00-\u9fa5A-Za-z0-9_\-·]{2,12}$/.test(name)) {
                box.innerHTML = '<span style="color:var(--error);">会员名称须为 2-12 个字（中文 / 字母 / 数字）</span>';
                return;
            }
            box.innerHTML = '<span style="color:var(--text2);">正在登录…</span>';
            try {
                const d = await _qJson(await fetch('/api/member/license/activate', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ code: code, name: name })
                }));
                if (!d.success) {
                    box.innerHTML = '<span style="color:var(--error);">' + _mEsc(d.error || '登录失败') + '</span>';
                    return;
                }
                box.innerHTML = '<span style="color:var(--success);">✓ ' + _mEsc(d.message || '登录成功') + '</span>';
                const ce = document.getElementById('mLoginCode');
                if (ce) ce.value = '';
                const ne = document.getElementById('mLoginName');
                if (ne) ne.value = '';
                showToast(d.message || '登录成功', 'success');
                // 登录会重绑资产归属、切换会员作用域配置，刷新页面最稳
                setTimeout(function () { location.reload(); }, 700);
            } catch (e) {
                box.innerHTML = '<span style="color:var(--error);">登录失败：' + _mEsc((e && e.message) || e) + '</span>';
            }
        }

        function memberApplyLock() {
            const unlocked = !!MEMBER_DATA.unlocked;
            const lock = document.getElementById('memberLock');
            if (lock) lock.style.display = unlocked ? 'none' : 'block';
            // ⚠️ 全站唯一控制「解锁后主体」显隐的地方。
            // #memberBody 在 HTML 里写死 display:none，早先版本这里**忘了把它打开** ——
            // 于是解锁成功后：锁面板消失、但页签行 + 卡号发放/会员列表/资产归属/防编译/本机授权
            const body = document.getElementById('memberBody');
            if (body) body.style.display = unlocked ? 'block' : 'none';
            ['mTabCards', 'mTabMembers', 'mTabGuard'].forEach(id => {
                const b = document.getElementById(id);
                if (b) b.style.opacity = unlocked ? '1' : '.45';
            });
        }

        async function memberUnlock() {
            const v = (document.getElementById('memberAdminPwd') || {}).value || '';
            const box = document.getElementById('memberLockMsg');
            if (!v) { box.innerHTML = '<span style="color:var(--error);">请输入管理密码</span>'; return; }
            box.innerHTML = '<span style="color:var(--text2);">验证中…</span>';
            const d = await (await fetch('/api/member/admin/login', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ password: v })
            })).json();
            if (!d.success) {
                box.innerHTML = '<span style="color:var(--error);">' + (d.error || '解锁失败') + '</span>';
                return;
            }
            MEMBER_TOKEN = d.token;
            localStorage.setItem('agnes_admin_token', d.token);
            document.getElementById('memberAdminPwd').value = '';
            box.innerHTML = '';
            showToast(d.using_default ? '已解锁（当前仍是出厂密码，建议尽快修改）' : '已解锁', 'success');
            await loadMemberModule();
        }

        function memberLockNow() {
            MEMBER_TOKEN = '';
            localStorage.removeItem('agnes_admin_token');
            MEMBER_DATA.unlocked = false;
            memberApplyLock();
        }

        async function loadMemberModule() {
            const d = await _mFetch('/api/member/overview');
            if (d && typeof d.unlocked !== 'undefined') MEMBER_DATA = d;
            memberApplyLock();
            memberRenderStats();
            // ⚠️ 这里原来还多调了一个已经改名的旧函数（名字见 tools/check_undefined_calls.py
            // 的注释）—— 那是「本机授权」面板改名前的旧函数名，函数体早已变成
            // memberRenderLicense()，调用点却没跟着改。它是个**未定义标识符**，
            // 一执行就抛 ReferenceError，把 loadMemberModule() 后半段整个掐断：
            if (MEMBER_DATA.unlocked) memberRenderGuard();
            memberRenderLicense();
            if (MEMBER_DATA.unlocked && mPanel === 'cards') memberLoadCards();
            if (MEMBER_DATA.unlocked && mPanel === 'members') memberLoadMembers();
            if (!MEMBER_DATA.unlocked && mPanel !== 'license') memberSwitch('license');
            else memberSwitch(mPanel, true);
            // 第一屏的登录/登出状态（不受管理后台是否解锁影响）
            memberRefreshNow();
            memberToggleAdmin(localStorage.getItem(MEMBER_ADMIN_OPEN_KEY) === '1');
        }

        function memberSwitch(p, quiet) {
            mPanel = p;
            ['cards', 'members', 'assets', 'guard', 'sentinel', 'license', 'keys'].forEach(k => {
                const pane = document.getElementById('mPanel' + k.charAt(0).toUpperCase() + k.slice(1));
                const btn = document.getElementById('mTab' + k.charAt(0).toUpperCase() + k.slice(1));
                if (pane) pane.style.display = (k === p) ? 'block' : 'none';
                if (btn) {
                    btn.style.background = (k === p) ? 'var(--accent)' : '';
                    btn.style.borderColor = (k === p) ? 'var(--accent)' : '';
                }
            });
            if (quiet) return;
            if (p === 'cards') memberLoadCards();
            if (p === 'members') memberLoadMembers();
            if (p === 'assets') memberLoadAssets();
            if (p === 'guard') memberRenderGuard();
            if (p === 'sentinel') memberRenderSentinel();
            if (p === 'license') memberRenderLicense();
            if (p === 'keys') memberLoadUserKeys();
        }

        // 只清会员独立配置（data/member_cfg/*.json），管理员/平台内置 KEY 不动。
        let USER_KEYS = null;

        function _mKeysMsg(txt, isErr) {
            const el = document.getElementById('mKeysMsg');
            if (el) { el.textContent = txt || ''; el.style.color = isErr ? 'var(--error)' : 'var(--text2)'; }
        }

        async function memberLoadUserKeys() {
            const stat = document.getElementById('mKeysStat');
            const list = document.getElementById('mKeysList');
            const btn = document.getElementById('mKeysClearBtn');
            if (stat) stat.textContent = '正在统计…';
            if (list) list.textContent = '';
            if (btn) btn.disabled = true;
            try {
                const d = await _mFetch('/api/member/admin/user-keys');
                if (!d.success) throw new Error(d.error || '读取失败');
                USER_KEYS = d;
                if (stat) {
                    stat.innerHTML = `共扫到 <b>${d.scanned}</b> 个会员独立配置，其中 <b>${d.with_keys}</b> 个填过 KEY，`
                        + `合计 <b>${d.key_count}</b> 处。${d.note ? '（' + d.note + '）' : ''}`;
                }
                if (list) {
                    list.innerHTML = (d.rows && d.rows.length)
                        ? d.rows.map(r => `<div>· <code>${_mEsc(r.scope)}</code> — ${_mEsc(r.fields.join('、'))}</div>`).join('')
                        : '<div>（当前没有会员填过 KEY）</div>';
                }
                if (btn) btn.disabled = !(d.key_count > 0);
            } catch (e) {
                if (stat) stat.textContent = '读取失败：' + e.message;
                USER_KEYS = null;
            }
        }

        async function memberClearUserKeys() {
            if (!USER_KEYS || !USER_KEYS.key_count) { _mKeysMsg('没有可清空的 KEY', true); return; }
            const n = USER_KEYS.with_keys, c = USER_KEYS.key_count;
            if (!confirm(`确定清空 ${n} 个会员填的 ${c} 处 KEY 吗？\n\n`
                + `· 会员需要重新填写 KEY 才能继续用生成功能\n`
                + `· 管理员/平台内置的 KEY 不会被动`)) return;
            _mKeysMsg('正在清空…');
            try {
                const d = await _mFetch('/api/member/admin/clear-user-keys', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ confirm: true })
                });
                if (!d.success) throw new Error(d.error || '清空失败');
                showToast(d.message || '已清空', 'success');
                _mKeysMsg('✅ ' + (d.message || '已清空'));
                await memberLoadUserKeys();
            } catch (e) {
                _mKeysMsg('清空失败：' + e.message, true);
            }
        }

        let ASSET_OVERVIEW = { owners: [], orphans: {}, orphan_total: 0 };

        function _mEsc(s) {
            return String(s == null ? '' : s).replace(/[&<>"]/g, c =>
                ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
        }

        async function memberLoadAssets() {
            const box = document.getElementById('mAssetSummary');
            if (box) box.textContent = '正在统计…';
            try {
                const d = await _mFetch('/api/member/assets/overview');
                if (!d.success) throw new Error(d.error || '读取失败');
                ASSET_OVERVIEW = d;
                await memberLoadAssetTargets();
                memberRenderAssets();
            } catch (e) {
                if (box) box.textContent = '读取失败：' + e.message;
            }
        }

        async function memberLoadAssetTargets() {
            const d = await _mFetch('/api/member/members');
            const sel = document.getElementById('mAssetTarget');
            if (!sel) return;
            const cur = sel.value;
            const ms = (d.items || []);
            sel.innerHTML = '<option value="">认领给…（选择会员）</option>' + ms.map(m =>
                '<option value="' + _mEsc(m.id) + '">' + _mEsc(m.name || '未命名') +
                ' · ' + _mEsc(m.code || '') + '</option>').join('');
            if (cur) sel.value = cur;
        }

        function memberRenderAssets() {
            const d = ASSET_OVERVIEW;
            const sum = document.getElementById('mAssetSummary');
            const total = (d.owners || []).reduce((a, b) => a + (b.total || 0), 0);
            if (sum) {
                sum.innerHTML = '已归属资产 <b>' + total + '</b> 项，分布在 <b>' +
                    (d.owners || []).length + '</b> 个身份下；无主 <b style="color:var(--error);">' +
                    (d.orphan_total || 0) + '</b> 项。';
            }
            const oc = document.getElementById('mOrphanCount');
            if (oc) oc.textContent = d.orphan_total ? ('(' + d.orphan_total + ' 项)') : '(无)';

            const ol = document.getElementById('mAssetOwnerList');
            if (ol) {
                ol.innerHTML = (d.owners || []).length
                    ? (d.owners || []).map(o =>
                        '<div style="display:flex;gap:8px;align-items:center;padding:6px 8px;border-bottom:1px solid var(--border);">' +
                        '<span style="flex:1;">' + _mEsc(o.label) + '</span>' +
                        '<span style="color:var(--text2);font-size:11px;">' +
                        Object.entries(o.by_dir || {}).map(([k, v]) => k + ' ' + v).join(' · ') +
                        '</span><b>' + o.total + ' 项</b></div>').join('')
                    : '<div style="color:var(--text2);padding:8px;">暂无已归属资产</div>';
            }

            const al = document.getElementById('mAssetOrphanList');
            if (al) {
                const keys = Object.keys(d.orphans || {});
                al.innerHTML = keys.length
                    ? keys.map(k =>
                        '<div style="padding:4px 8px;"><b>' + _mEsc(k) + '</b>（' +
                        (d.orphans[k] || []).length + '）<br><span style="color:var(--text2);">' +
                        (d.orphans[k] || []).slice(0, 12).map(_mEsc).join('、') +
                        ((d.orphans[k] || []).length > 12 ? ' …' : '') + '</span></div>').join('')
                    : '<div style="color:var(--text2);padding:8px;">没有待认领的资产</div>';
            }
        }

        async function memberClaimOrphans() {
            const sel = document.getElementById('mAssetTarget');
            const mid = (sel && sel.value) || '';
            if (!mid) { showToast('请先选择要认领给的会员', 'error'); return; }
            if (!ASSET_OVERVIEW.orphan_total) { showToast('当前没有待认领资产', 'info'); return; }
            if (!confirm('将该 ' + ASSET_OVERVIEW.orphan_total + ' 项无主资产认领给所选会员？已有主人的资产不受影响。')) return;
            try {
                const d = await _mFetch('/api/member/assets/claim', {
                    method: 'POST',
                    body: JSON.stringify({ member_id: mid, names: ASSET_OVERVIEW.orphans || {} })
                });
                if (!d.success) throw new Error(d.error || '认领失败');
                showToast('已认领 ' + d.moved + ' 项资产', 'success');
                await memberLoadAssets();
            } catch (e) {
                showToast('认领失败：' + e.message, 'error');
            }
        }

        function memberRenderStats() {
            const el = document.getElementById('memberStats');
            if (!el) return;
            const s = (MEMBER_DATA.stats) || {};
            const c = s.cards || {}, m = s.members || {};
            const lic = MEMBER_DATA.license || {};
            const ok = lic.valid !== false;
            el.innerHTML =
                `卡号 <b>${s.cards_total || 0}</b> 张（🟢未用 ${c.unused || 0} · 🔵已用 ${c.used || 0} · 🔴作废 ${c.revoked || 0}）　` +
                `会员 <b>${s.members_total || 0}</b> 位（🟢生效 ${m.active || 0} · 🟡过期 ${m.expired || 0} · 🔴停用 ${m.disabled || 0}）　` +
                `批次 <b>${s.batches || 0}</b>　` +
                `本机：<span style="color:${ok ? 'var(--success)' : 'var(--error)'};font-weight:600;">${ok ? '已授权' : (lic.reason || '未授权')}</span>` +
                `　机器码 <code style="font-size:11px;">${MEMBER_DATA.machine || '-'}</code>`;
        }

        function memberCardFilter(st) {
            mCardStatus = st;
            ['', 'unused', 'used', 'revoked'].forEach(s => {
                const b = document.getElementById('mFilter' + (s === '' ? 'All' : s.charAt(0).toUpperCase() + s.slice(1)));
                if (b) { b.style.background = (s === st) ? 'var(--accent)' : ''; b.style.borderColor = (s === st) ? 'var(--accent)' : ''; }
            });
            memberLoadCards();
        }

        async function memberLoadCards() {
            const q = (document.getElementById('mCardSearch') || {}).value || '';
            const b = (document.getElementById('mCardBatch') || {}).value || '';
            const d = await _mFetch(`/api/member/cards?status=${encodeURIComponent(mCardStatus)}&q=${encodeURIComponent(q)}&batch=${encodeURIComponent(b)}`);
            if (!d.success) return;
            // 批次下拉（只填充一次，避免筛选时抖动）
            const sel = document.getElementById('mCardBatch');
            if (sel && !sel.dataset.filled && (d.batches || []).length) {
                sel.innerHTML = '<option value="">全部批次</option>' +
                    d.batches.map(x => `<option value="${x.batch}">${x.batch}（${x.total} 张 · ${x.level_name || ''}）</option>`).join('');
                sel.dataset.filled = '1';
            }
            const stName = { unused: '🟢 未使用', used: '🔵 已使用', revoked: '🔴 已作废' };
            const rows = (d.items || []).map(c => `
                <tr>
                  <td style="padding:5px 6px;"><input type="checkbox" class="mCardChk" value="${c.code}" ${mSelected.has(c.code) ? 'checked' : ''} onchange="memberToggleChk('${c.code}', this.checked)"></td>
                  <td style="padding:5px 6px;font-family:monospace;font-size:12px;">${c.code}</td>
                  <td style="padding:5px 6px;font-size:12px;color:${c.name ? 'var(--accent)' : 'var(--text2)'};font-weight:${c.name ? '600' : '400'};">${c.name || '—'}</td>
                  <td style="padding:5px 6px;">${c.level_name || ''}<span style="color:var(--text2);"> · ${c.minutes > 0 ? c.minutes + '分钟' : (c.days === 0 ? '永久' : c.days + '天')}</span></td>
                  <td style="padding:5px 6px;">${stName[c.status] || c.status}</td>
                  <td style="padding:5px 6px;color:var(--text2);font-size:11px;">${c.batch || ''}</td>
                  <td style="padding:5px 6px;color:var(--text2);font-size:11px;">${c.used_at || '-'}</td>
                  <td style="padding:5px 6px;color:var(--text2);">${c.note || ''}</td>
                  <td style="padding:5px 6px;"><button class="btn btn-sm" style="font-size:11px;padding:2px 6px;" onclick="memberCopyOne('${c.code}')">📋</button></td>
                </tr>`).join('');
            document.getElementById('mCardList').innerHTML =
                `<table style="width:100%;border-collapse:collapse;font-size:12px;">
                   <thead><tr style="text-align:left;color:var(--text2);border-bottom:1px solid var(--border);">
                     <th style="padding:5px 6px;width:28px;"><input type="checkbox" onchange="memberToggleAll(this.checked)"></th>
                     <th style="padding:5px 6px;">卡号</th><th>绑定名字</th><th>等级</th><th>状态</th><th>批次</th><th>使用时间</th><th>备注</th><th></th>
                   </tr></thead><tbody>${rows || '<tr><td colspan="9" style="padding:16px;text-align:center;color:var(--text2);">暂无卡号，用上方表单生成</td></tr>'}</tbody></table>`;
        }

        function memberToggleChk(code, on) { on ? mSelected.add(code) : mSelected.delete(code); }
        function memberToggleAll(on) {
            document.querySelectorAll('.mCardChk').forEach(c => {
                c.checked = on;
                on ? mSelected.add(c.value) : mSelected.delete(c.value);
            });
        }

        async function memberCopyOne(code) {
            try { await navigator.clipboard.writeText(code); showToast('已复制 ' + code, 'success'); }
            catch (e) { showToast(code, 'success'); }
        }

        async function memberCopySelected() {
            if (!mSelected.size) { showToast('请先勾选卡号', 'error'); return; }
            const txt = [...mSelected].join('\n');
            try { await navigator.clipboard.writeText(txt); showToast(`已复制 ${mSelected.size} 个卡号`, 'success'); }
            catch (e) { showToast('复制失败，请手动选择', 'error'); }
        }

        async function memberGenCards() {
            const d = await _mFetch('/api/member/cards/generate', {
                method: 'POST',
                body: JSON.stringify({
                    level: (document.getElementById('mCardLevel') || {}).value || 'month',
                    count: (document.getElementById('mCardCount') || {}).value || 10,
                    days: (document.getElementById('mCardDays') || {}).value || null,
                    note: (document.getElementById('mCardNote') || {}).value || '',
                    minutes: (document.getElementById('mCardMinutes') || {}).value || null
                })
            });
            if (!d.success) { showToast(d.error || '生成失败', 'error'); return; }
            showToast(d.message, 'success');
            const sel = document.getElementById('mCardBatch');
            if (sel) sel.dataset.filled = '';
            MEMBER_DATA.stats = d.stats;
            memberRenderStats();
            await memberLoadCards();
        }

        function mSetGenMode(mode) {
            const r = document.getElementById('mGenModeRandom');
            const p = document.getElementById('mGenModePlain');
            document.getElementById('mGenRandomBox').style.display = (mode === 'random') ? '' : 'none';
            document.getElementById('mGenPlainBox').style.display = (mode === 'plain') ? '' : 'none';
            r.style.background = (mode === 'random') ? 'var(--accent)' : '';
            r.style.borderColor = (mode === 'random') ? 'var(--accent)' : '';
            p.style.background = (mode === 'plain') ? 'var(--accent)' : '';
            p.style.borderColor = (mode === 'plain') ? 'var(--accent)' : '';
        }

        async function memberImportCards() {
            const raw = (document.getElementById('mPlainCodes').value || '').trim();
            if (!raw) { showToast('请先粘贴卡号', 'error'); return; }
            const d = await _mFetch('/api/member/cards/import', {
                method: 'POST',
                body: JSON.stringify({
                    level: (document.getElementById('mPlainLevel') || {}).value || 'month',
                    days: (document.getElementById('mPlainDays') || {}).value || null,
                    minutes: (document.getElementById('mPlainMinutes') || {}).value || null,
                    note: (document.getElementById('mPlainNote') || {}).value || '',
                    codes: raw.split('\n')
                })
            });
            if (!d.success) { showToast(d.error || '发放失败', 'error'); return; }
            const box = document.getElementById('mPlainResult');
            let html = '✅ 已发放 <b style="color:var(--accent);">' + d.created_count + '</b> 张';
            if (d.created_count) {
                html += '<br><span style="font-family:monospace;">' +
                    d.created.slice(0, 30).map(c => c).join('　') + '</span>';
            }
            if (d.skipped_count) {
                html += '<br>⚠️ 跳过 <b style="color:var(--error);">' + d.skipped_count + '</b> 张：' +
                    (d.skipped || []).slice(0, 20).map(s =>
                        '<span style="color:var(--error);">' + s.code + '</span>(' + s.reason + ')').join('，');
            }
            box.innerHTML = html;
            showToast(d.message, 'success');
            document.getElementById('mPlainCodes').value = '';
            const sel = document.getElementById('mCardBatch');
            if (sel) sel.dataset.filled = '';
            MEMBER_DATA.stats = d.stats;
            memberRenderStats();
            await memberLoadCards();
        }

        function memberToggleBindBox() {
            const b = document.getElementById('mBindBox');
            b.style.display = (b.style.display === 'none' || !b.style.display) ? '' : 'none';
        }

        function _mBindMsg(d) {
            let html = '✅ 已绑定 <b style="color:var(--accent);">' + (d.ok || 0) + '</b> 张';
            if (d.bound && d.bound.length) {
                html += '<br><span style="font-family:monospace;">' +
                    d.bound.slice(0, 30).map(x => x.code + ' → ' + (x.name || '（解绑）')).join('<br>') + '</span>';
            }
            if (d.skipped && d.skipped.length) {
                html += '<br>⚠️ 跳过 ' + d.skipped.length + ' 张：' +
                    d.skipped.slice(0, 10).map(s => '<span style="color:var(--error);">' + s.code + '</span>(' + s.reason + ')').join('，');
            }
            return html;
        }

        async function memberBindText() {
            const txt = (document.getElementById('mBindText').value || '').trim();
            if (!txt) { showToast('请粘贴「卡号 名字」', 'error'); return; }
            const d = await _mFetch('/api/member/cards/bind', {
                method: 'POST', body: JSON.stringify({ text: txt })
            });
            if (!d.success) { showToast(d.error || '绑定失败', 'error'); return; }
            document.getElementById('mBindResult').innerHTML = _mBindMsg(d);
            showToast(d.message, 'success');
            await memberLoadCards();
        }

        async function memberBindNames() {
            if (!mSelected.size) { showToast('请先勾选卡号', 'error'); return; }
            const nm = (document.getElementById('mBindName').value || '').trim();
            if (!nm && !confirm(`解绑选中的 ${mSelected.size} 张卡号的名字？`)) return;
            if (nm && !confirm(`把选中的 ${mSelected.size} 张卡号绑定到「${nm}」？绑定后只能用该名字登录。`)) return;
            const d = await _mFetch('/api/member/cards/bind', {
                method: 'POST', body: JSON.stringify({ items: [...mSelected], name: nm })
            });
            if (!d.success) { showToast(d.error || '绑定失败', 'error'); return; }
            showToast(d.message, 'success');
            document.getElementById('mBindName').value = '';
            await memberLoadCards();
        }

        async function memberCardAction(action) {
            if (!mSelected.size) { showToast('请先勾选卡号', 'error'); return; }
            const tip = { revoke: '作废', restore: '恢复为未使用', delete: '删除' }[action] || action;
            if (!confirm(`确定${tip}选中的 ${mSelected.size} 张卡号？`)) return;
            const d = await _mFetch('/api/member/cards/action', {
                method: 'POST', body: JSON.stringify({ codes: [...mSelected], action: action })
            });
            if (!d.success) { showToast(d.error || '操作失败', 'error'); return; }
            mSelected.clear();
            MEMBER_DATA.stats = d.stats;
            memberRenderStats();
            await memberLoadCards();
        }

        async function memberExportCards() {
            const q = (document.getElementById('mCardSearch') || {}).value || '';
            const r = await fetch(`/api/member/cards/export?status=${encodeURIComponent(mCardStatus)}&q=${encodeURIComponent(q)}`,
                                  { headers: _mHdr() });
            if (!r.ok) { showToast('导出失败，请确认已解锁', 'error'); return; }
            const blob = await r.blob();
            const a = document.createElement('a');
            a.href = URL.createObjectURL(blob);
            a.download = 'cards.csv';
            a.click();
            setTimeout(() => URL.revokeObjectURL(a.href), 3000);
            showToast('已导出 CSV', 'success');
        }

        function memberMemFilter(st) {
            mMemStatus = st;
            ['', 'active', 'expired', 'disabled'].forEach(s => {
                const b = document.getElementById('mMem' + (s === '' ? 'All' : s.charAt(0).toUpperCase() + s.slice(1)));
                if (b) { b.style.background = (s === st) ? 'var(--accent)' : ''; b.style.borderColor = (s === st) ? 'var(--accent)' : ''; }
            });
            memberLoadMembers();
        }

        function memberToggleCreate(force) {
            const box = document.getElementById('mCreateBox');
            if (!box) return;
            const open = (typeof force === 'boolean') ? force : (box.style.display === 'none');
            box.style.display = open ? 'block' : 'none';
            if (open) {
                const nm = document.getElementById('mCreateName');
                if (nm) nm.focus();
            }
        }

        async function memberCreate() {
            const box = document.getElementById('mCreateResult');
            if (!box) return;
            const name = ((document.getElementById('mCreateName') || {}).value || '').trim();
            const level = (document.getElementById('mCreateLevel') || {}).value || 'month';
            const daysV = ((document.getElementById('mCreateDays') || {}).value || '').trim();
            const code = ((document.getElementById('mCreateCode') || {}).value || '').trim();
            const note = ((document.getElementById('mCreateNote') || {}).value || '').trim();
            if (!name) { box.innerHTML = '<span style="color:var(--error);">请填写会员名称</span>'; return; }
            if (!/^[\u4e00-\u9fa5A-Za-z0-9_\-·]{2,12}$/.test(name)) {
                box.innerHTML = '<span style="color:var(--error);">会员名称须为 2-12 个字（中文 / 字母 / 数字，可用 - _ ·）</span>';
                return;
            }
            box.innerHTML = '<span style="color:var(--text2);">正在建档…</span>';
            const d = await _mFetch('/api/member/members/create', {
                method: 'POST',
                body: JSON.stringify({ name: name, level: level, days: daysV === '' ? null : daysV,
                                       code: code, note: note })
            });
            if (!d.success) {
                box.innerHTML = '<span style="color:var(--error);">✗ ' + _mEsc(d.error || '建档失败') + '</span>';
                return;
            }
            const m = d.member || {};
            box.innerHTML =
                '<span style="color:var(--success);">✓ 已新增会员「' + _mEsc(m.name || name) + '」</span>' +
                '　卡号 <code style="color:var(--accent);font-weight:600;">' + _mEsc(d.code || '') + '</code>' +
                '　<button class="btn btn-sm" style="font-size:11px;padding:2px 6px;" onclick="memberCopyOne(\'' + (d.code || '') + '\')">📋 复制卡号</button>' +
                '<div style="color:var(--text2);margin-top:4px;">把卡号发给本人，他在自己设备上登录即完成绑定；这里也能直接 续期 / 停用 / 解绑 / 删除。</div>';
            // 清掉输入，保留名称方便连续建同名批次时可自行改
            ['mCreateName', 'mCreateDays', 'mCreateCode', 'mCreateNote'].forEach(id => {
                const el = document.getElementById(id);
                if (el) el.value = '';
            });
            if (d.stats) MEMBER_DATA.stats = d.stats;
            memberRenderStats();
            showToast('已新增会员「' + (m.name || name) + '」', 'success');
            mMemStatus = '';
            await memberLoadMembers();
        }

        async function memberLoadMembers() {
            const q = (document.getElementById('mMemSearch') || {}).value || '';
            const d = await _mFetch(`/api/member/members?q=${encodeURIComponent(q)}&status=${encodeURIComponent(mMemStatus)}`);
            if (!d.success) return;
            const stName = { active: '🟢 生效中', expired: '🟡 已过期', disabled: '🔴 已停用' };
            const rows = (d.items || []).map(m => `
                <tr>
                  <td style="padding:6px;font-family:monospace;font-size:12px;">${m.code}</td>
                  <td style="padding:6px;">${m.name || '-'}</td>
                  <td style="padding:6px;">${m.level_name || '-'}</td>
                  <td style="padding:6px;color:var(--text2);font-size:11px;">${(m.activated_at || '').slice(0, 10)}</td>
                  <td style="padding:6px;color:var(--text2);font-size:11px;">${m.expire_at ? m.expire_at.slice(0, 10) : '永久'}</td>
                  <td style="padding:6px;">${m.days_left === null ? '∞' : (m.days_left < 0 ? '<span style="color:var(--error);">已过期</span>' : (m.minutes_left != null && m.days_left === 0 ? (m.minutes_left >= 60 ? Math.floor(m.minutes_left / 60) + ' 小时' + (m.minutes_left % 60 ? ' ' + (m.minutes_left % 60) + ' 分' : '') : m.minutes_left + ' 分钟') : m.days_left + ' 天'))}</td>
                  <td style="padding:6px;color:var(--text2);font-size:11px;font-family:monospace;">${(m.machine || '未绑定').slice(0, 10)}</td>
                  <td style="padding:6px;">${stName[m.status] || m.status}</td>
                  <td style="padding:6px;white-space:nowrap;">
                    <button class="btn btn-sm" style="font-size:11px;padding:2px 6px;" onclick="memberAct('${m.id}','extend')">➕续期</button>
                    <button class="btn btn-sm" style="font-size:11px;padding:2px 6px;" onclick="memberAct('${m.id}','${m.status === 'disabled' ? 'enable' : 'disable'}')">${m.status === 'disabled' ? '▶启用' : '⏸停用'}</button>
                    <button class="btn btn-sm" style="font-size:11px;padding:2px 6px;" onclick="memberAct('${m.id}','unbind')">🔓解绑</button>
                    <button class="btn btn-sm" style="font-size:11px;padding:2px 6px;" onclick="memberAct('${m.id}','delete')">🗑</button>
                  </td>
                </tr>`).join('');
            document.getElementById('mMemberList').innerHTML =
                `<table style="width:100%;border-collapse:collapse;font-size:12px;">
                   <thead><tr style="text-align:left;color:var(--text2);border-bottom:1px solid var(--border);">
                     <th style="padding:6px;">卡号</th><th>名称</th><th>等级</th><th>激活</th><th>到期</th><th>剩余</th><th>机器码</th><th>状态</th><th>操作</th>
                   </tr></thead><tbody>${rows || '<tr><td colspan="9" style="padding:16px;text-align:center;color:var(--text2);">还没有会员激活记录</td></tr>'}</tbody></table>`;
        }

        async function memberAct(id, action) {
            let days = 0;
            if (action === 'extend') {
                const v = prompt('续期多少天？', '30');
                if (v === null) return;
                days = parseInt(v, 10);
                if (!days || days <= 0) { showToast('天数无效', 'error'); return; }
            }
            if (action === 'delete' && !confirm('删除该会员记录？（卡号不会退回）')) return;
            const d = await _mFetch('/api/member/members/action', {
                method: 'POST', body: JSON.stringify({ id: id, action: action, days: days })
            });
            if (!d.success) { showToast(d.error || '操作失败', 'error'); return; }
            showToast('已更新', 'success');
            MEMBER_DATA.stats = d.stats;
            memberRenderStats();
            await memberLoadMembers();
        }

        const M_GUARD_SWITCHES = [
            ['integrity_check', '代码完整性自检', '启动时比对核心文件哈希，被改过就报警'],
            ['anti_debug', '反调试 / 反注入', '检测到调试器或 PYTHONINSPECT 等注入环境就拒绝启动'],
            ['no_bytecode', '禁止 .pyc 落盘', '不在磁盘留下可被直接读走的字节码缓存'],
            ['env_cleanup', '清理注入型环境变量', '清除 PYTHONPATH / PYTHONSTARTUP 等外部注入'],
        ];

        function memberRenderGuard() {
            const g = MEMBER_DATA.guard;
            if (!g) return;
            const cfg = g.config || {};
            document.getElementById('mGuardSwitches').innerHTML =
                M_GUARD_SWITCHES.map(([k, title, hint]) => `
                    <label style="display:flex;gap:8px;align-items:flex-start;padding:7px 0;border-bottom:1px dashed var(--border);cursor:pointer;">
                        <input type="checkbox" id="mGs_${k}" ${cfg[k] ? 'checked' : ''} style="margin-top:3px;">
                        <span><b style="font-size:13px;">${title}</b><br>
                        <span style="font-size:12px;color:var(--text2);">${hint}</span></span>
                    </label>`).join('') +
                `<div style="padding:8px 0;font-size:13px;">完整性不通过时：
                    <select class="form-input" id="mGsAction" style="width:140px;display:inline-block;font-size:12px;">
                        <option value="warn" ${cfg.integrity_action === 'warn' ? 'selected' : ''}>只报警，照常启动</option>
                        <option value="exit" ${cfg.integrity_action === 'exit' ? 'selected' : ''}>拒绝启动</option>
                    </select>
                 </div>`;

            const it = g.integrity;
            document.getElementById('mGuardIntegrity').innerHTML = !it
                ? '未开启完整性自检。'
                : (it.no_baseline
                    ? '⚠ 尚未建立基线 —— 现在的文件就是"正版"的话，点一下右边按钮记下来。'
                    : (it.ok
                        ? `✓ 校验通过：${it.checked} 个文件与基线一致（基线建于 ${it.baseline_at || '-'}）`
                        : `⚠ 与基线不一致 —— 改动 ${(it.changed || []).length} / 缺失 ${(it.missing || []).length} / 新增 ${(it.new || []).length} 个文件` +
                          ((it.changed || []).slice(0, 8).map(f => `<div style="color:var(--error);">· ${f}</div>`).join(''))));
            const dbg = document.getElementById('mGuardIntegrity');
            if (dbg && (g.debug_hits || []).length) {
                dbg.innerHTML += `<div style="color:var(--error);margin-top:4px;">⛔ 检测到调试/注入环境：${g.debug_hits.join('；')}</div>`;
            }
            document.getElementById('mGuardHarden').innerHTML = g.hardened_exists
                ? '✓ <code>hardened/</code> 已存在，下次打包会优先用它（只有 .pyc）。'
                : '尚未加固。执行后产物在程序目录 <code>hardened/</code>，源码不动。';
        }

        async function memberGuardSave() {
            const cfg = {};
            M_GUARD_SWITCHES.forEach(([k]) => {
                const el = document.getElementById('mGs_' + k);
                if (el) cfg[k] = el.checked;
            });
            const act = document.getElementById('mGsAction');
            if (act) cfg.integrity_action = act.value;
            const d = await _mFetch('/api/member/guard', { method: 'POST', body: JSON.stringify({ config: cfg }) });
            if (!d.success) { showToast(d.error || '保存失败', 'error'); return; }
            MEMBER_DATA.guard = { config: d.config, integrity: d.integrity, debug_hits: d.debug_hits, hardened_exists: d.hardened_exists };
            memberRenderGuard();
            showToast('已保存，下次启动生效', 'success');
        }

        async function memberGuardBaseline() {
            if (!confirm('以「当前代码」作为正版基线？之后任何改动都会被标记为异常。')) return;
            const d = await _mFetch('/api/member/guard/baseline', { method: 'POST', body: '{}' });
            if (!d.success) { showToast(d.error || '失败', 'error'); return; }
            MEMBER_DATA.guard = { config: d.config, integrity: d.integrity, debug_hits: d.debug_hits, hardened_exists: d.hardened_exists };
            memberRenderGuard();
            showToast(d.message, 'success');
        }

        async function memberGuardVerify() {
            const d = await _mFetch('/api/member/guard/verify', { method: 'POST', body: '{}' });
            if (!d.success) { showToast(d.error || '失败', 'error'); return; }
            MEMBER_DATA.guard = { config: d.config, integrity: d.integrity, debug_hits: d.debug_hits, hardened_exists: d.hardened_exists };
            memberRenderGuard();
            showToast(d.integrity && d.integrity.ok ? '✓ 与基线一致' : '⚠ 存在差异，见上方列表', d.integrity && d.integrity.ok ? 'success' : 'error');
        }

        async function memberGuardHarden() {
            const d = await _mFetch('/api/member/guard/harden', { method: 'POST', body: '{}' });
            if (!d.success) { showToast(d.error || '加固失败', 'error'); return; }
            MEMBER_DATA.guard = { config: d.config, integrity: d.integrity, debug_hits: d.debug_hits, hardened_exists: d.hardened_exists };
            memberRenderGuard();
            showToast(d.message, 'success');
        }

        async function memberChangePwd() {
            const oldP = (document.getElementById('mPwdOld') || {}).value || '';
            const newP = (document.getElementById('mPwdNew') || {}).value || '';
            const box = document.getElementById('mPwdMsg');
            const d = await _mFetch('/api/member/admin/password', {
                method: 'POST', body: JSON.stringify({ old_password: oldP, new_password: newP })
            });
            if (!d.success) { box.innerHTML = '<span style="color:var(--error);">' + (d.error || '修改失败') + '</span>'; return; }
            MEMBER_TOKEN = d.token;
            localStorage.setItem('agnes_admin_token', d.token);
            box.innerHTML = '<span style="color:var(--success);">✓ ' + d.message + '</span>';
            document.getElementById('mPwdOld').value = '';
            document.getElementById('mPwdNew').value = '';
        }

        let SENTINEL_DATA = null;
        const M_SENTINEL_KEYS = [
            ['enabled', '总开关', '关掉后所有防护立即失效（不推荐）'],
            ['protect_data_json', '保护提示词库', '提示词库（/data/*.json）必须带放行令牌，否则返回假数据'],
        ];
        function _fmtLeft(s) {
            s = Math.max(0, s | 0);
            if (s >= 3600) return Math.floor(s / 3600) + ' 小时 ' + Math.floor((s % 3600) / 60) + ' 分';
            if (s >= 60) return Math.floor(s / 60) + ' 分 ' + (s % 60) + ' 秒';
            return s + ' 秒';
        }
        function _fmtTime(ts) {
            try { return new Date(ts * 1000).toLocaleString('zh-CN', { hour12: false }); } catch (e) { return '-'; }
        }
        async function memberRenderSentinel() {
            const d = await _mFetch('/api/sentinel/status?limit=120', { method: 'GET' });
            if (!d.success) { showToast(d.error || '读取失败', 'error'); return; }
            SENTINEL_DATA = d;
            const st = d.stats || {};
            const el = document.getElementById('mSentinelStats');
            if (el) el.innerHTML =
                `运行时长 <b>${_fmtLeft(Date.now() / 1000 - (st.since || 0)).replace('小时', '时')}</b>　` +
                `累计请求 <b>${st.total || 0}</b>　投毒 <b style="color:var(--warning);">${st.poisoned || 0}</b>　` +
                `封禁命中 <b style="color:var(--error);">${st.blocked || 0}</b>　` +
                `累计封禁 <b>${st.banned_total || 0}</b> 次　见过来源 <b>${st.clients_seen || 0}</b> 个`;
            const cfg = d.config || {};
            const cfgEl = document.getElementById('mSentinelCfg');
            if (cfgEl) cfgEl.innerHTML =
                M_SENTINEL_KEYS.map(([k, title, hint]) => `
                    <label style="display:flex;gap:8px;align-items:flex-start;padding:6px 0;border-bottom:1px dashed var(--border);cursor:pointer;">
                        <input type="checkbox" id="mSx_${k}" ${cfg[k] ? 'checked' : ''} style="margin-top:3px;">
                        <span><b style="font-size:13px;">${title}</b><br>
                        <span style="font-size:12px;color:var(--text2);">${hint}</span></span>
                    </label>`).join('') +
                `<div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;padding:8px 0;font-size:12.5px;">
                    <span>投毒阈值 <input type="number" id="mSxPoison" value="${cfg.poison_score}" style="width:64px;" class="form-input"></span>
                    <span>封禁阈值 <input type="number" id="mSxBlock" value="${cfg.block_score}" style="width:64px;" class="form-input"></span>
                    <span>限速 <input type="number" id="mSxRate" value="${cfg.rate_limit}" style="width:74px;" class="form-input"> 次 /
                          <input type="number" id="mSxRateWin" value="${cfg.rate_window}" style="width:56px;" class="form-input"> 秒</span>
                    <span>首封 <input type="number" id="mSxBan" value="${Math.round((cfg.ban_seconds || 1800) / 60)}" style="width:56px;" class="form-input"> 分钟（重复翻倍）</span>
                    <button class="btn btn-sm" onclick="sentinelSaveCfg()">💾 保存</button>
                 </div>`;
            const bans = d.bans || [];
            document.getElementById('mSentinelBanCount').textContent = bans.length;
            const bEl = document.getElementById('mSentinelBans');
            if (bEl) bEl.innerHTML = bans.length ? bans.map(b => `
                <div style="display:flex;gap:8px;align-items:center;padding:4px 0;border-bottom:1px dashed var(--border);">
                    <span style="flex:1;">
                        <code>${b.ip || b.fp}</code>　剩余 <b>${_fmtLeft(b.left)}</b>　
                        <span style="color:var(--error);">${b.reason || ''}</span><br>
                        <span style="opacity:.7;">${(b.ua || '').slice(0, 70)}</span>
                    </span>
                    <button class="btn btn-sm" onclick="sentinelUnban('${b.fp}')">解封</button>
                </div>`).join('') : '暂无封禁。';
            const evs = d.events || [];
            const eEl = document.getElementById('mSentinelEvents');
            if (eEl) eEl.innerHTML = evs.length ? evs.map(e => {
                const color = e.action === 'block' ? 'var(--error)'
                    : (e.action === 'poison' ? 'var(--warning)' : 'var(--text2)');
                return `<div>[${_fmtTime(e.at)}] <b style="color:${color};">${e.action}</b> ` +
                    `<code>${e.path}</code> <span style="opacity:.7;">score=${e.score} ${e.ip || ''}</span><br>` +
                    `<span style="opacity:.65;">${(e.reasons || []).join('；')}</span></div>`;
            }).join('') : '暂无事件。';
        }
        async function sentinelSaveCfg() {
            const cfg = {};
            M_SENTINEL_KEYS.forEach(([k]) => {
                const el = document.getElementById('mSx_' + k);
                if (el) cfg[k] = el.checked;
            });
            const num = (id, dft) => { const v = parseInt((document.getElementById(id) || {}).value, 10); return isNaN(v) ? dft : v; };
            cfg.poison_score = num('mSxPoison', 45);
            cfg.block_score = num('mSxBlock', 110);
            cfg.rate_limit = num('mSxRate', 900);
            cfg.rate_window = num('mSxRateWin', 60);
            cfg.ban_seconds = Math.max(60, num('mSxBan', 30) * 60);
            const d = await _mFetch('/api/sentinel/config', { method: 'POST', body: JSON.stringify(cfg) });
            if (!d.success) { showToast(d.error || '保存失败', 'error'); return; }
            showToast('防护设置已保存（立即生效）', 'success');
            memberRenderSentinel();
        }
        async function sentinelBanIp() {
            const ip = ((document.getElementById('mSentinelBanIp') || {}).value || '').trim();
            if (!ip) { showToast('请填 IP', 'error'); return; }
            const d = await _mFetch('/api/sentinel/ban', { method: 'POST', body: JSON.stringify({ ip, seconds: 3600 }) });
            if (!d.success) { showToast(d.error || '封禁失败', 'error'); return; }
            showToast('已封禁 ' + ip + '（1 小时）', 'success');
            document.getElementById('mSentinelBanIp').value = '';
            memberRenderSentinel();
        }
        async function sentinelUnban(fp) {
            const d = await _mFetch('/api/sentinel/unban', { method: 'POST', body: JSON.stringify({ fp }) });
            if (!d.success) { showToast(d.error || '解封失败', 'error'); return; }
            showToast('已解封', 'success');
            memberRenderSentinel();
        }
        async function sentinelClearEvents() {
            if (!confirm('清空防护事件记录？')) return;
            const d = await _mFetch('/api/sentinel/clear', { method: 'POST', body: '{}' });
            if (!d.success) { showToast(d.error || '清空失败', 'error'); return; }
            memberRenderSentinel();
        }

        function memberRenderLicense() {
            const el = document.getElementById('mLicenseBox');
            if (!el) return;
            const lic = MEMBER_DATA.license || {};
            const m = lic.member;
            const ok = lic.valid !== false;
            el.innerHTML =
                `<div style="font-size:15px;font-weight:700;color:${ok ? 'var(--success)' : 'var(--error)'};">
                    ${ok ? '✓ 本机已授权' : '✗ ' + (lic.reason || '未授权')}
                 </div>` +
                (m ? `<div>会员：<b>${m.name || '-'}</b>　卡号 <code>${m.code}</code>　等级 ${m.level_name || '-'}</div>
                      <div>激活 ${(m.activated_at || '').slice(0, 10)}　到期 <b>${m.expire_at ? m.expire_at.slice(0, 10) : '永久'}</b>　剩余 <b>${m.days_left === null ? '∞' : Math.max(0, m.days_left) + ' 天'}</b></div>`
                    : '<div style="color:var(--text2);">还没有会员记录。输入卡号即可激活本机。</div>') +
                `<div style="margin-top:6px;color:var(--text2);font-size:12px;">机器码 <code>${MEMBER_DATA.machine || '-'}</code>（换机器需解绑后再激活）</div>` +
                `<div style="margin-top:4px;font-size:12px;color:var(--text2);">强制校验：
                    <b style="color:${lic.required ? 'var(--warning)' : 'var(--text2)'};">${lic.required ? '已开启' : '关闭'}</b>
                 </div>`;
            const cb = document.getElementById('mRequireLicense');
            if (cb) cb.checked = !!lic.required;
        }

        async function memberActivate() {
            const code = (document.getElementById('mActivateCode') || {}).value || '';
            const name = (document.getElementById('mActivateName') || {}).value || '';
            const box = document.getElementById('mActivateMsg');
            if (!code.trim()) { box.innerHTML = '<span style="color:var(--error);">请输入卡号</span>'; return; }
            if (name.trim() && !/^[\u4e00-\u9fa5A-Za-z0-9_\-·]{2,12}$/.test(name.trim())) {
                box.innerHTML = '<span style="color:var(--error);">会员名称须为 2-12 个字（中文 / 字母 / 数字）</span>';
                return;
            }
            const d = await _qJson(await fetch('/api/member/license/activate', {
                method: 'POST', headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ code: code, name: name })
            }));
            if (!d.success) { box.innerHTML = '<span style="color:var(--error);">' + (d.error || '激活失败') + '</span>'; return; }
            box.innerHTML = '<span style="color:var(--success);">✓ ' + d.message + '</span>';
            document.getElementById('mActivateCode').value = '';
            MEMBER_DATA.license = d.license;
            memberRenderLicense();
            memberRenderStats();
        }

        async function memberToggleRequire(on) {
            const d = await _mFetch('/api/member/license/require', {
                method: 'POST', body: JSON.stringify({ require: on })
            });
            if (!d.success) {
                showToast(d.error || '操作失败，请先解锁管理密码', 'error');
                const cb = document.getElementById('mRequireLicense');
                if (cb) cb.checked = !on;
                return;
            }
            MEMBER_DATA.license = d.license;
            memberRenderLicense();
            showToast(on ? '已开启会员校验' : '已关闭会员校验', 'success');
        }

        // 会员到期提示条：后端任何 402 都会弹出来
        function showLicenseBanner(msg) {
            let b = document.getElementById('licenseBanner');
            if (!b) {
                b = document.createElement('div');
                b.id = 'licenseBanner';
                b.style.cssText = 'position:fixed;left:50%;top:14px;transform:translateX(-50%);z-index:9999;' +
                    'background:#fee2e2;color:#991b1b;border:1px solid var(--err-fg);border-radius:10px;' +
                    'padding:10px 16px;font-size:13px;box-shadow:0 6px 20px rgba(0,0,0,.15);display:flex;gap:10px;align-items:center;';
                document.body.appendChild(b);
            }
            b.innerHTML = `<span>⚠ ${msg || '会员未激活或已过期'}</span>
                <button class="btn btn-sm" style="background:#991b1b;border-color:#991b1b;color:var(--on-accent);"
                        onclick="openMemberSettings()">去激活</button>
                <button class="btn btn-sm" onclick="document.getElementById('licenseBanner').remove()">✕</button>`;
        }

        // 拦一层 fetch：①后端返回 402（会员到期）时自动提示 ②带身份头
        // X-Client-Id：门户 iframe / 禁三方 Cookie 环境下 Cookie 可能被浏览器
        // 拦掉，用 localStorage 持久化的请求头兜底，身份照样稳定。
        // ③ /data/*.json 提示词库带放行令牌 X-Ags-Token（反爬哨兵，见 services/sentinel.py）
        (function () {
            function _cid() {
                let v = '';
                try { v = localStorage.getItem('ags_cid') || ''; } catch (e) { }
                if (!v) {
                    try { v = (crypto.randomUUID ? crypto.randomUUID() : ('c' + Date.now().toString(16) + Math.random().toString(16).slice(2, 10))).replace(/-/g, ''); } catch (e2) { v = 'c' + Date.now().toString(16); }
                    try { localStorage.setItem('ags_cid', v); } catch (e3) { }
                }
                return v;
            }
            const _raw = window.fetch.bind(window);
            let _tokVal = '';
            let _tokP = null;
            try { _tokVal = sessionStorage.getItem('ags_tok') || ''; } catch (e) { }
            function _tok() {
                if (_tokVal) return Promise.resolve(_tokVal);
                if (_tokP) return _tokP;
                _tokP = _raw('/api/sentinel/token', { headers: { 'X-Client-Id': _cid() } })
                    .then(r => r.json())
                    .then(d => {
                        if (d && d.success && d.token) {
                            _tokVal = d.token;
                            try { sessionStorage.setItem('ags_tok', d.token); } catch (e) { }
                        }
                        return _tokVal;
                    })
                    .catch(() => { _tokP = null; return ''; });
                return _tokP;
            }
            window._agsSentinelToken = _tok;   // 给别处复用
            window.fetch = async function () {
                try {
                    const args = Array.prototype.slice.call(arguments);
                    const url = typeof args[0] === 'string' ? args[0] : (args[0] && args[0].url) || '';
                    const isApi = url.indexOf('/api/') === 0 || (url.indexOf('/api/') > 0 && url.indexOf(location.host) > -1);
                    const isData = url.indexOf('/data/') === 0;
                    if (isApi || isData) {
                        const opts = args[1] = Object.assign({}, args[1]);
                        opts.headers = Object.assign({}, opts.headers, { 'X-Client-Id': _cid() });
                        try {
                            const at = localStorage.getItem('agnes_admin_token') || '';
                            if (at && !opts.headers['X-Admin-Token']) opts.headers['X-Admin-Token'] = at;
                        } catch (e4) { }
                        if (isData) {
                            const t = await _tok();
                            if (t) opts.headers['X-Ags-Token'] = t;
                        }
                    }
                    let r = await _raw.apply(null, args);
                    // 提示词库被投毒（令牌过期 / 服务端密钥轮换）→ 丢掉缓存令牌重取一次
                    if (isData && r && r.headers && r.headers.get('X-Ags-P') === '1' && _tokVal) {
                        _tokVal = ''; _tokP = null;
                        try { sessionStorage.removeItem('ags_tok'); } catch (e5) { }
                        const t2 = await _tok();
                        if (t2) {
                            const o2 = Object.assign({}, args[1]);
                            o2.headers = Object.assign({}, o2.headers, { 'X-Ags-Token': t2 });
                            r = await _raw.apply(null, [args[0], o2]);
                        }
                    }
                    try {
                        if (r && r.status === 402) {
                            const d = await r.clone().json();
                            if (d && d.need_license) showLicenseBanner(d.error);
                        }
                    } catch (e) { /* 不是 JSON 就算了 */ }
                    return r;
                } catch (err) { return _raw.apply(null, arguments); }
            };
        })();

        // 防护哨兵 · 前端自检：页面被自动化工具（webdriver/headless）驱动时上报。
        // 真人浏览器不会命中；本机回环只记录不封（不挡自己的自动化测试）。
        (function () {
            function _sig() {
                const s = [];
                try { if (navigator.webdriver) s.push('webdriver'); } catch (e) { }
                try {
                    if (/HeadlessChrome|PhantomJS/i.test(navigator.userAgent || '')) s.push('headless');
                } catch (e) { }
                try { if (window.__nightmare || window._phantom || window.callPhantom) s.push('automation'); } catch (e) { }
                try {
                    // 缺 languages 只在「自称 Chrome 却没有语言列表」时才可疑
                    const ua = navigator.userAgent || '';
                    if (/\bChrome\//.test(ua) && (!navigator.languages || !navigator.languages.length)) s.push('headless');
                } catch (e) { }
                return s;
            }
            function _go() {
                try {
                    const s = _sig();
                    if (!s.length) return;
                    const f = (window.__agsRawFetch || window.fetch);
                    f('/api/sentinel/report', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ signals: s, path: location.pathname })
                    }).catch(() => { });
                } catch (e) { }
            }
            if (document.readyState === 'loading') {
                document.addEventListener('DOMContentLoaded', function () { setTimeout(_go, 1200); });
            } else { setTimeout(_go, 1200); }
        })();

        let _randomPromptBusy = { image: false, video: false };
        async function aiRandomPrompts(kind) {
            if (_randomPromptBusy[kind]) { showToast('正在生成中，稍等…', 'info'); return; }
            const btnWrap = document.getElementById(kind + 'Presets');
            const btn = btnWrap ? btnWrap.querySelector('button') : null;
            _randomPromptBusy[kind] = true;
            if (btn) { btn.disabled = true; btn.textContent = '⏳ AI 正在构思…'; }
            try {
                const resp = await fetch('/api/text/random-prompts', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ kind, count: 3 })
                });
                const d = await resp.json();
                if (!d.success) { showToast(d.error || '生成失败', 'error'); return; }
                renderRandomPrompts(kind, d.prompts || []);
                showToast('已生成 ' + (d.prompts || []).length + ' 条灵感提示词', 'success');
            } catch (e) {
                showToast('生成失败: ' + e.message, 'error');
            } finally {
                _randomPromptBusy[kind] = false;
                if (btn) { btn.disabled = false; btn.textContent = '🎲 AI 随机灵感 ×3'; }
            }
        }
        function renderRandomPrompts(kind, prompts) {
            const box = document.getElementById(kind + 'RandomBox');
            if (!box) return;
            const label = kind === 'video' ? '视频提示词' : '绘画提示词';
            box.innerHTML = prompts.map((p, i) => `
                <div style="display:flex;gap:6px;align-items:stretch;margin-bottom:6px;">
                    <textarea class="form-textarea" id="${kind}Rp${i}" rows="2"
                        style="flex:1;font-size:12px;min-height:44px;resize:vertical;">${(p || '').replace(/</g, '&lt;').replace(/>/g, '&gt;')}</textarea>
                    <div style="display:flex;flex-direction:column;gap:4px;">
                        <button class="btn btn-sm" style="padding:2px 8px;font-size:11px;" onclick="copyRandomPrompt('${kind}',${i})" title="复制">📋 复制</button>
                        <button class="btn btn-sm" style="padding:2px 8px;font-size:11px;" onclick="fillRandomPrompt('${kind}',${i})" title="填入上方描述框">⬆ 填入</button>
                        <button class="btn btn-sm" style="padding:2px 8px;font-size:11px;" onclick="clearRandomPrompt('${kind}',${i})" title="清除">🗑 清除</button>
                    </div>
                </div>`).join('');
            box.style.display = 'block';
        }
        function copyRandomPrompt(kind, i) {
            const el = document.getElementById(`${kind}Rp${i}`);
            if (!el) return;
            const text = el.value.trim();
            if (!text) { showToast('这条是空的', 'error'); return; }
            (navigator.clipboard ? navigator.clipboard.writeText(text) : Promise.reject())
                .then(() => showToast('已复制到剪贴板', 'success'))
                .catch(() => {
                    // 剪贴板 API 不可用（如非 https 环境）时回退到选中文本
                    el.select(); document.execCommand('copy');
                    showToast('已复制到剪贴板', 'success');
                });
        }
        function fillRandomPrompt(kind, i) {
            const el = document.getElementById(`${kind}Rp${i}`);
            if (!el) return;
            const target = document.getElementById(kind === 'video' ? 'videoPrompt' : 'imagePrompt');
            if (target) { target.value = el.value.trim(); target.focus(); showToast('已填入描述框', 'success'); }
        }
        function clearRandomPrompt(kind, i) {
            const el = document.getElementById(`${kind}Rp${i}`);
            if (el) { el.value = ''; }
        }

        const DUAL_MODEL_OPTIONS = {
            'sensenova-u1.5-lite': '商汤 SenseNova U1.5 Lite (2K/4K, 推荐)',
            'sensenova-u1-fast': '商汤 SenseNova U1 Fast',
            'agnes-image-2.5-flash': 'AGNES Image 2.5 Flash',
            'agnes-image-2.1-flash': 'AGNES Image 2.1 Flash',
            'agnes-image-2.0-flash': 'AGNES Image 2.0 Flash',
            'doubao-seedream-3-0': '豆包 Seedream 3.0 (付费)',
            'minimax-image-01': 'MiniMax Image 01 (付费)',
            'qwen-image-plus': 'Qwen Image Plus (付费)',
        };
        const DUAL_MODEL_SHORT = {
            'sensenova-u1.5-lite': '商汤 U1.5 Lite',
            'sensenova-u1-fast': '商汤 U1 Fast',
            'agnes-image-2.5-flash': 'AGNES 2.5 Flash',
            'agnes-image-2.1-flash': 'AGNES 2.1 Flash',
            'agnes-image-2.0-flash': 'AGNES 2.0 Flash',
            'doubao-seedream-3-0': '豆包 Seedream 3.0',
            'minimax-image-01': 'MiniMax Image 01',
            'qwen-image-plus': 'Qwen Image Plus',
        };
        // 商汤走 2K 尺寸表，其余模型走标准尺寸表
        // ⚠️ 标准表里不能写 1280x720 / 720x1280：720 不是 32 的倍数，上游会 400
        //    （与 2026-10-05 MV 定妆照事故同源）。16:9 / 9:16 用 1024x576 / 576x1024，
        //    后端 normalize_image_size 仍会兜底归一化。
        //
        // V1.8.215：Agnes Image 系（2.5/2.1/2.0 Flash）新增 4K 档。
        // 官方 Output Dimension Reference 的 4K 行，注意**长边会超过 4096**
        // （16:9 → 5248x2944，21:9 → 6272x2688）—— 后端已按模型族把上限
        // 放到 6272（商汤那道 4096 的闸没动，跨厂商不串味）。
        // 2.5 Flash 当前 1K~4K 全档免费（原价 24/千张），4K 不额外加钱。
        const DUAL_SIZE_MAP = {
            sensenova: { '16:9': '2720x1536', '1:1': '2048x2048', '9:16': '1536x2720', '4:3': '2496x1664', '3:4': '1664x2496' },
            // Agnes 4K 档（官方 4K 行；比例与 standard 表一一对应）
            agnes4k:   { '16:9': '5248x2944', '1:1': '4096x4096', '9:16': '2944x5248', '4:3': '4608x3456', '3:4': '3456x4608' },
            standard:  { '16:9': '1024x576',  '1:1': '1024x1024', '9:16': '576x1024',  '4:3': '1024x768',  '3:4': '768x1024' },
        };
        // 当前生效的 4K 开关（生图页的清晰度下拉写它；封面/三视图等旧入口保持默认 1K）
        let dualUse4k = false;
        function _isAgnesImage(model) {
            return String(model || '').toLowerCase().startsWith('agnes-image');
        }
        function dualSizeTable(model) {
            const m = String(model || '').toLowerCase();
            if (m.startsWith('sensenova')) return DUAL_SIZE_MAP.sensenova;
            // 4K 只对 Agnes 系有意义：商汤白名单里 4096x4096 之外的长边全被上游拒，
            // 其它厂商（豆包/MiniMax/Qwen）没有 4K 档，发过去只会 400。
            if (dualUse4k && _isAgnesImage(m)) return DUAL_SIZE_MAP.agnes4k;
            return DUAL_SIZE_MAP.standard;
        }
        function initDualModelSelects() {
            ['dualModelLeft', 'dualModelRight'].forEach((id, idx) => {
                const sel = document.getElementById(id);
                if (!sel) return;
                const defaults = ['sensenova-u1.5-lite', 'agnes-image-2.5-flash'];
                sel.innerHTML = Object.entries(DUAL_MODEL_OPTIONS)
                    .map(([v, label]) => `<option value="${v}">${v === defaults[idx] ? '★ ' : ''}${label}</option>`)
                    .join('');
                sel.value = defaults[idx];
            });
            onDualModelChange();
        }
        function onDualModelChange() {
            const l = document.getElementById('dualModelLeft'), r = document.getElementById('dualModelRight');
            const btn = document.getElementById('btnGenerateImage');
            if (l && r && btn) {
                btn.innerHTML = '✨ 一键双模生成（' + (DUAL_MODEL_SHORT[l.value] || l.value)
                    + ' ⇄ ' + (DUAL_MODEL_SHORT[r.value] || r.value) + '）';
            }
            const lt = document.getElementById('dualPanelLeftTitle'), rt = document.getElementById('dualPanelRightTitle');
            if (l && lt) lt.textContent = '左 · ' + (DUAL_MODEL_SHORT[l.value] || l.value);
            if (r && rt) rt.textContent = '右 · ' + (DUAL_MODEL_SHORT[r.value] || r.value);
            syncImageResHint();
        }
        // 清晰度下拉（V1.8.215）：只有 dualSizeTable 真正认它，界面提示也要跟着变，
        // 否则选了 4K 却看到「商汤 2K」的文案 = 界面骗人。
        function onImageResChange() {
            const el = document.getElementById('imageRes');
            dualUse4k = !!(el && el.value === '4k');
            syncImageResHint();
        }
        function syncImageResHint() {
            const l = document.getElementById('dualModelLeft'), r = document.getElementById('dualModelRight');
            const ratioEl = document.getElementById('imageSize');
            const ratio = (ratioEl && ratioEl.value) || '16:9';
            const resEl = document.getElementById('imageRes');
            const note = document.getElementById('imageResActual');
            if (!resEl || !note) return;
            const l4k = dualUse4k && _isAgnesImage(l && l.value);
            const r4k = dualUse4k && _isAgnesImage(r && r.value);
            const parts = [];
            if (l) parts.push((DUAL_MODEL_SHORT[l.value] || l.value) + '：'
                + (dualSizeTable(l.value)[ratio] || '-'));
            if (r) parts.push((DUAL_MODEL_SHORT[r.value] || r.value) + '：'
                + (dualSizeTable(r.value)[ratio] || '-'));
            const badge = (dualUse4k && (l4k || r4k)) ? '高清 4K 生效中' : (dualUse4k ? '已选 4K（左右均非 AGNES，实际不生效）' : '标准 1K');
            note.textContent = badge + ' · 本次实际尺寸 → ' + parts.join('　/　');
        }
        let dualImageUrls = { left: null, right: null };

        async function generateImage() {
            const prompt = document.getElementById('imagePrompt').value.trim();
            if (!prompt) {
                showToast('请输入图片描述', 'error');
                return;
            }

            const ratioEl = document.getElementById('imageSize');
            const ratio = (ratioEl && ratioEl.value) || '16:9';
            const lSel = document.getElementById('dualModelLeft'), rSel = document.getElementById('dualModelRight');
            const leftModel = (lSel && lSel.value) || 'sensenova-u1.5-lite';
            const rightModel = (rSel && rSel.value) || 'agnes-image-2.5-flash';
            const btn = document.getElementById('btnGenerateImage');

            btn.disabled = true;
            btn.innerHTML = '<span class="loading-spinner"></span> 双模生成中...';

            // 左右两路并行跑，互不阻塞；全部结束后恢复按钮
            await Promise.allSettled([
                _dualRun('left', prompt, dualSizeTable(leftModel)[ratio] || '1024x576', leftModel),
                _dualRun('right', prompt, dualSizeTable(rightModel)[ratio] || '1024x576', rightModel),
            ]);

            btn.disabled = false;
            onDualModelChange();
        }

        async function _dualRun(slot, prompt, size, model) {
            const st = document.getElementById(slot + 'ResultStatus');
            const img = document.getElementById(slot + 'ResultImg');
            const act = document.getElementById(slot + 'ResultActions');
            if (st) { st.textContent = '⏳ 生成中…（' + size + '）'; st.style.color = 'var(--text2)'; }
            if (img) img.style.display = 'none';
            if (act) act.style.display = 'none';
            dualImageUrls[slot] = null;

            try {
                const resp = await fetch('/api/image/generate', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ prompt, model, size })
                });
                const data = await _qJson(resp);
                if (data.success && data.image_url) {
                    dualImageUrls[slot] = data.image_url;
                    if (img) { img.src = data.image_url; img.style.display = 'block'; }
                    if (act) act.style.display = 'flex';
                    if (st) {
                        st.style.color = 'var(--success)';
                        st.textContent = '✅ 完成' + (data.local_file ? ' · 已存 pictures/' + data.local_file : '');
                    }
                } else if (st) {
                    st.style.color = 'var(--error)';
                    st.textContent = '❌ ' + (data.error || '生成失败');
                }
            } catch (e) {
                if (st) { st.style.color = 'var(--error)'; st.textContent = '❌ 网络异常：' + e.message; }
            }
        }

        function downloadDualImage(slot) {
            const url = dualImageUrls[slot];
            if (!url) { showToast('该侧还没有生成结果', 'error'); return; }
            const a = document.createElement('a');
            a.href = url;
            a.download = 'dual-' + slot + '-image.png';
            a.target = '_blank';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
        }

        function copyDualUrl(slot) {
            const url = dualImageUrls[slot];
            if (!url) { showToast('该侧还没有生成结果', 'error'); return; }
            navigator.clipboard.writeText(url).then(() => {
                showToast('图片URL已复制到剪贴板', 'success');
            });
        }
        // ⚠️ initDualModelSelects / initQueueModels / initTriviewModels 不能在这里直接调用！
        // 它们会读到本文件后面才声明的 let/const（queueState、tvImages），
        // 在声明之前访问会抛 TDZ 错误，并把整段脚本从这里打断 —— 后面所有
        // let/const 都不会被初始化。统一放到脚本尾部 _lateInit() 里执行。

        function _qEsc(s) {
            return String(s || '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
        }

        // 安全解析 JSON：云端重启 / 反代 502 时后端会回 HTML 错误页，
        // 直接 resp.json() 会抛 "Unexpected token '<'" 这种没头没尾的报错。
        async function _qJson(resp) {
            const text = await resp.text();
            try {
                return JSON.parse(text);
            } catch (e) {
                throw new Error('服务无响应（HTTP ' + resp.status + '），可能正在重启或过载，稍后点「🔄 重来」即可');
            }
        }

        // 网关（CloudStudio Gateway）502/504 时返回的是 HTML 错误页，直接 JSON.parse 会抛
        // "Unexpected token '<'" —— 用户既看不懂，也分不清是网关中断还是后端出错，更不知道
        // 任务到底提交成功没有（后端是异步的，很可能已经在跑了）。这里统一翻译成人话，
        // 并把 HTTP 状态与错误页摘要带出来方便排障。
        async function gwJson(resp, what) {
            let txt = '';
            try { txt = await resp.text(); } catch (e) { txt = ''; }
            const t = (txt || '').trim();
            if (t.startsWith('{') || t.startsWith('[')) {
                try { return JSON.parse(t); }
                catch (e) { throw new Error((what || '接口') + '返回的数据无法解析，请稍后重试'); }
            }
            if (resp.status === 502 || resp.status === 503 || resp.status === 504 || /^\s*<html/i.test(t)) {
                let snip = '';
                const mt = t.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
                if (mt) snip = mt[1].replace(/\s+/g, ' ').trim();
                if (!snip) snip = t.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 60);
                throw new Error('云端网关超时/中断（HTTP ' + resp.status + (snip ? ' · ' + snip : '') + '）——'
                    + (what || '本次任务') + '可能已经提交成功。请先去「视频任务」页看一眼，'
                    + '确认没有再点一次（后端已做 3 分钟幂等去重，但别依赖它）');
            }
            throw new Error('服务无响应（HTTP ' + resp.status + '），请稍后重试');
        }

        // 稳定短哈希（djb2）：给视频提交生成幂等键，网关超时后重发同一请求时可被后端识别
        function gwHash32(s) {
            let h = 5381;
            for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) >>> 0;
            return h.toString(36) + (s.length % 36).toString(36);
        }

        const QUEUE_SAMPLE = [
            '一位年轻女性，黑长直发齐刘海，头戴白色蝴蝶结发箍。身穿黑色细吊带裙，脖子上戴着带铃铛的白色蕾丝项圈。低头温柔地抱着一个熟睡的婴儿，婴儿穿白色连体衣。室内背景，蓝色花纹墙面，粉色床单，温馨氛围，柔和光线，写实摄影，高清画质。',
            '户外阳台，逆光，一位年轻女性，黑长直发。身穿浅粉色无袖上衣，黑色百褶裙，下摆有粉白条纹。双手抓着头发，光腿。背景是金属栏杆和远处的山景，阳光明媚，光晕效果，日系写真，高细节。',
            '户外阳台，一位年轻女性，浅粉色上衣，黑色百褶裙。双腿交叉站立，双手撑在栏杆上。穿着带蓝红条纹的白色长筒袜，棕色毛绒熊掌拖鞋。脸部被蓝色心形遮挡。背景是蓝色围栏和山景，自然光，日常穿搭，写实摄影。',
            '室内对镜自拍，手机遮挡脸部。一位年轻女性，长发，头戴黄色蝴蝶结。身穿白色紧身短袖T恤，黑黄格纹百褶迷你裙。脚穿白色短袜，黑色蝴蝶结玛丽珍鞋。站在木地板上，木凳背景，室内自然光，日常穿搭，高清画质。',
            '一位年轻女性特写，黑长直发，红唇，面容精致。身穿浅灰色交叉V领无袖上衣。背景是仓库或工厂环境，蓝色货架，景深模糊，明亮光线，写实人像摄影，高细节。',
            '室内对镜自拍，手机遮挡脸部。女孩坐在白色沙发上。身穿白色开衫外套，内搭红色波点短裤套装。脚穿白色蕾丝短袜，袜口有红色蝴蝶结。沙发上放着Hello Kitty毛绒玩具。背景有镜子和华丽的门，温馨居家风格，写实摄影。',
            '室内对镜自拍，女孩坐在地板上。身穿白色蕾丝荷叶边连衣裙，腰间系浅绿色丝带。穿着白色连裤袜，光脚。手机遮挡脸部。背景是木质家具和动漫海报，柔和光线，洛丽塔风格，写实摄影。',
            '户外，女孩靠在黑色汽车旁。黑长直发，戴猫耳发箍。身穿浅蓝色长袖衬衫，深色格纹百褶裙。穿着白色蕾丝长筒袜，白色厚底玛丽珍鞋。身体微微前倾。背景是树木和山坡，自然光，日系街拍，高清画质。',
            '室内，女孩侧身看向镜头外。扎双马尾。身穿白色针织长袖开衫，内搭浅蓝色格子衬衫，胸前有浅蓝色蝴蝶结。背景是白色柜子和红色包包，柔和自然光，日常家居风，写实人像。',
            '室内，女孩坐在木椅上。戴金丝边圆形眼镜。身穿白色短袖宽松上衣，灰色短裙。穿着肉色丝袜。伸出一只手臂指向镜头，卡通感叹号贴纸特效。背景是桌子和窗帘，明亮光线，日常写实摄影。'
        ].join('\n');

        // 解析：支持「📸 图N / 正向提示词 / 反向提示词」批量文本，也支持一行一条
        function parseQueuePrompts(raw) {
            const lines = String(raw || '').replace(/\r/g, '').split('\n');
            const items = [];
            let cur = null, mode = null;
            const flush = () => { if (cur && (cur.prompt || '').trim()) items.push(cur); cur = null; mode = null; };
            for (const ln of lines) {
                const t = ln.trim();
                if (/^[-=—*]{3,}$/.test(t)) { flush(); continue; }
                const mHead = t.match(/^(?:#{1,6}\s*)?(?:📸\s*)?图\s*(\d+)\s*[：:·.\-]?\s*(.*)$/);
                if (mHead) {
                    flush();
                    cur = { title: '图' + mHead[1] + (mHead[2] ? '：' + mHead[2] : ''), prompt: '', negative: '' };
                    continue;
                }
                const mPos = t.match(/^\**\s*(?:正向提示词|正面提示词|提示词)\s*[：:]\s*\**\s*(.*)$/);
                if (mPos) { if (!cur) cur = { title: '', prompt: '', negative: '' }; cur.prompt = mPos[1]; mode = 'pos'; continue; }
                const mNeg = t.match(/^\**\s*(?:反向提示词|负面提示词|负向提示词)\s*[：:]\s*\**\s*(.*)$/);
                if (mNeg) { if (!cur) cur = { title: '', prompt: '', negative: '' }; cur.negative = mNeg[1]; mode = 'neg'; continue; }
                if (!t) { mode = null; continue; }
                if (!cur) { cur = { title: '', prompt: t, negative: '' }; continue; }
                if (mode === 'pos') cur.prompt += (cur.prompt ? ' ' : '') + t;
                else if (mode === 'neg') cur.negative += (cur.negative ? ' ' : '') + t;
                else if (!cur.prompt) cur.prompt += (cur.prompt ? ' ' : '') + t;
                else { flush(); cur = { title: '', prompt: t, negative: '' }; }   // 无标记文本：一行一条
            }
            flush();
            return items.map((it, i) => ({
                title: it.title || ('第' + (i + 1) + '条'),
                prompt: (it.prompt || '').trim(), negative: (it.negative || '').trim(),
                refs: [],            // 参照图（0 张 = 纯文生图；≥1 张 = 图生图）
                state: 'wait', url: '', file: '', err: ''
            }));
        }

        const queueState = { items: [], idx: 0, running: false, paused: false, skip: false, cdTimer: null, lanes: 1, keyInfo: null, refTarget: -1 };

        function initQueueModels() {
            const sel = document.getElementById('queueModel');
            if (!sel) return;
            sel.innerHTML = Object.entries(DUAL_MODEL_OPTIONS)
                .map(([v, label]) => '<option value="' + v + '">' + (v === 'sensenova-u1.5-lite' ? '★ ' : '') + label + '</option>').join('');
            sel.value = 'sensenova-u1.5-lite';
            queueInitRefInput();
            if (typeof queueRefreshLanes === 'function') queueRefreshLanes();
        }

        const QUEUE_MAX_REFS = 5;        // 图生图接口最多吃 5 张参考图

        // 隐藏的文件选择器只建一个，点哪一行就把「投递目标」切到那一行
        function queueInitRefInput() {
            const inp = document.getElementById('queueRefInput');
            if (!inp || inp._bound) return;
            inp._bound = true;
            inp.addEventListener('change', () => {
                const i = (typeof queueState.refTarget === 'number') ? queueState.refTarget : -1;
                if (i >= 0 && inp.files && inp.files.length) queueUploadRefFiles(i, inp.files);
                inp.value = '';
            });
        }

        function queuePickRefs(i) {
            queueState.refTarget = i;
            const inp = document.getElementById('queueRefInput');
            if (inp) { inp.value = ''; inp.click(); }
        }

        function queueDropRefs(e, i) {
            e.preventDefault();
            if (e.currentTarget) e.currentTarget.style.borderColor = 'var(--border)';
            const fs = (e.dataTransfer && e.dataTransfer.files) || [];
            if (fs.length) queueUploadRefFiles(i, fs);
        }

        async function queueUploadRefFiles(i, files) {
            const list = Array.from(files || []).filter(f => f && /^image\//.test(f.type || ''));
            if (!list.length) { showToast('请选择图片文件（png / jpg / webp）', 'error'); return; }
            const it = queueState.items[i];
            if (!it) return;
            if (!it.refs) it.refs = [];
            if (it.refs.length >= QUEUE_MAX_REFS) {
                showToast('第 ' + (i + 1) + ' 条已有 ' + QUEUE_MAX_REFS + ' 张参照图（接口上限），先清空再加', 'error');
                return;
            }
            for (const f of list) {
                if (it.refs.length >= QUEUE_MAX_REFS) {
                    showToast('已到上限，多出的图片被忽略（每条最多 ' + QUEUE_MAX_REFS + ' 张）', 'info');
                    break;
                }
                const fd = new FormData();
                fd.append('file', f);
                try {
                    const d = await _qJson(await fetch('/api/upload/image', { method: 'POST', body: fd }));
                    if (d && d.success) it.refs.push({ url: d.url, filename: d.filename });
                    else showToast('第 ' + (i + 1) + ' 条参照图上传失败：' + ((d && d.error) || '未知'), 'error');
                } catch (e) {
                    showToast('第 ' + (i + 1) + ' 条参照图上传异常：' + e.message, 'error');
                }
            }
            queueRenderList();
            showToast('第 ' + (i + 1) + ' 条参照图共 ' + it.refs.length + ' 张（生成时按图生图跑）', 'success');
        }

        function queueClearRefs(i) {
            const it = queueState.items[i];
            if (!it || !(it.refs || []).length) return;
            it.refs = [];
            queueRenderList();
            showToast('第 ' + (i + 1) + ' 条的参照图已清空', 'info');
        }

        // 行首的小窗口：没图显示 📎，有图显示第一张缩略图 + 张数角标
        function queueRefCell(i, it) {
            const refs = it.refs || [];
            const inner = refs.length
                ? `<img src="${_qEsc(refs[0].url)}" style="width:100%;height:100%;object-fit:cover;border-radius:6px;">`
                : `<div style="font-size:10px;color:var(--text2);line-height:1.25;text-align:center;">📎<br>参照图</div>`;
            const badge = refs.length > 1
                ? `<span style="position:absolute;right:-5px;bottom:-5px;background:var(--accent);color:var(--on-accent);border-radius:8px;padding:0 5px;font-size:10px;font-weight:700;">${refs.length}</span>`
                : '';
            const clear = refs.length
                ? `<button class="btn btn-sm" style="position:absolute;top:-6px;right:-6px;padding:0 4px;line-height:1.2;" title="清空该条参照图" onclick="event.stopPropagation();queueClearRefs(${i})">✕</button>`
                : '';
            const tip = refs.length
                ? `已挂 ${refs.length} 张参照图：点一下继续追加，也可把图片直接拖进来`
                : '点一下上传参照图（可多张，也可把图片拖进来）';
            return `<div style="position:relative;flex:0 0 auto;width:54px;height:54px;border:1px dashed var(--border);border-radius:6px;background:var(--surface2);cursor:pointer;display:flex;align-items:center;justify-content:center;"
                title="${tip}" onclick="queuePickRefs(${i})"
                ondragover="event.preventDefault();this.style.borderColor='var(--accent)';"
                ondragleave="this.style.borderColor='var(--border)';"
                ondrop="queueDropRefs(event,${i})">
                <div style="width:100%;height:100%;overflow:hidden;border-radius:6px;display:flex;align-items:center;justify-content:center;">${inner}</div>
                ${badge}${clear}</div>`;
        }

        async function queueFetchLanes() {
            try {
                const d = await (await fetch('/api/image/lanes')).json();
                queueState.keyInfo = d || null;
                return d;
            } catch (e) { return null; }
        }

        async function queueResolveLanes(model) {
            const sel = document.getElementById('queueLanes');
            const mode = (sel && sel.value) || 'auto';
            if (mode === '1') return 1;                 // 手动锁单线
            const d = await queueFetchLanes();
            const avail = Math.max(1, Math.min(2, parseInt((d && d.lanes) || 1, 10)));
            if (mode === '2') return 2;                 // 手动强制双线
            // 自动：商汤通道 + 双 KEY 才开双线；其他厂商通道保守走单线（避免触发限流）
            const isSn = /^sensenova/i.test(model || '');
            return (isSn && avail >= 2) ? 2 : 1;
        }

        async function queueRefreshLanes() {
            const box = document.getElementById('queueLaneInfo');
            if (box) box.textContent = '检测中…';
            const d = await queueFetchLanes();
            if (!box) return d;
            if (!d) { box.innerHTML = '<span style="color:var(--error);">检测失败</span>'; return null; }
            box.innerHTML = d.dual
                ? '<span style="color:var(--success);">✓ 双 KEY（' + (d.key_a_masked || 'A') + ' ＋ ' + (d.key_b_masked || 'B') + '）→ 排队自动双线</span>'
                : '<span style="color:var(--warning);">' + (d.message || '单 KEY → 单线运行') + '</span>';
            return d;
        }

        function openSensenovaKeySettings() {
            switchTab('providers');
            if (typeof loadSensenovaImageKeys === 'function') loadSensenovaImageKeys();
            const el = document.getElementById('settingsPanelImage');
            if (el) el.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }

        function queueParse() {
            const items = parseQueuePrompts(document.getElementById('queueInput').value);
            queueState.items = items; queueState.idx = 0;
            const c = document.getElementById('queueCount');
            if (c) c.textContent = items.length ? ('已解析 ' + items.length + ' 条') : '没解析到提示词';
            queueRenderList();
            showToast(items.length ? ('已解析 ' + items.length + ' 条提示词') : '没解析到提示词，检查粘贴内容', items.length ? 'success' : 'error');
            return items.length;
        }

        function queueLoadSample() {
            const ta = document.getElementById('queueInput');
            if (ta) ta.value = QUEUE_SAMPLE;
            queueParse();
        }

        function queueClearInput() {
            const ta = document.getElementById('queueInput');
            if (ta) ta.value = '';
            queueState.items = []; queueState.idx = 0;
            queueRenderList();
            const c = document.getElementById('queueCount'); if (c) c.textContent = '';
        }

        function queueRenderList() {
            const box = document.getElementById('queueList');
            if (!box) return;
            box.innerHTML = queueState.items.map((it, i) => {
                const color = { wait: 'var(--text2)', running: 'var(--warning)', done: 'var(--success)', fail: 'var(--error)' }[it.state] || 'var(--text2)';
                const label = { wait: '⏸ 等待中', running: '⏳ 生成中…', done: '✅ 已完成', fail: '❌ 失败' }[it.state] || '等待中';
                const laneTag = (queueState.lanes > 1 && typeof it.lane === 'number')
                    ? '<span style="margin-left:6px;padding:1px 6px;border-radius:8px;font-size:11px;border:1px solid var(--border);background:var(--surface2);">'
                      + (it.lane === 0 ? 'A 线 · KEY A' : 'B 线 · KEY B') + '</span>' : '';
                const thumb = (it.state === 'done' && it.file)
                    ? '<img src="/pictures/' + _qEsc(it.file) + '" style="width:60px;height:60px;object-fit:cover;border-radius:6px;cursor:zoom-in;" onclick="openDramaImageViewer(this)">' : '';
                const dl = it.file ? '<a class="btn btn-sm" href="/pictures/' + _qEsc(it.file) + '" download target="_blank">📥 下载</a>' : '';
                const saveBtn = it.state === 'done' ? '<button class="btn btn-sm" type="button" onclick="queueSaveOne(' + i + ')">💾 保存</button>' : '';
                const redoBtn = '<button class="btn btn-sm" type="button" onclick="queueRedoOne(' + i + ')">🔄 重来</button>';
                const refTag = (it.refs && it.refs.length)
                    ? '<span style="margin-left:6px;padding:1px 6px;border-radius:8px;font-size:11px;border:1px solid var(--border);background:var(--surface2);">📎 参照图 '
                      + it.refs.length + ' 张</span>' : '';
                return '<div style="display:flex;gap:10px;align-items:center;border:1px solid var(--border);border-radius:var(--radius-sm);padding:8px;background:var(--bg);">'
                    + queueRefCell(i, it)
                    + '<div style="width:24px;text-align:center;font-weight:700;color:var(--text2);">' + (i + 1) + '</div>'
                    + thumb
                    + '<div style="flex:1;min-width:0;">'
                    + '<div style="font-size:13px;font-weight:600;">' + _qEsc(it.title) + '</div>'
                    + '<div style="font-size:12px;color:var(--text2);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + _qEsc(it.prompt) + '</div>'
                    + '<div style="font-size:12px;color:' + color + ';margin-top:2px;">' + label + laneTag + refTag
                    + (it.file ? ' · 已存 pictures/' + _qEsc(it.file) : '') + (it.err ? ' · ' + _qEsc(it.err) : '') + '</div>'
                    + '</div>' + dl + saveBtn + redoBtn + '</div>';
            }).join('');
        }

        function queueSetStatus(t) {
            const el = document.getElementById('queueStatus');
            if (el) el.textContent = '状态：' + t;
        }

        // 间隔已固定为 0：一条生成完立刻跑下一条（保留函数，散落引用不报错）
        function queueIntervalSec() { return 0; }

        function queueWait(sec) {
            return new Promise(resolve => {
                let left = Math.max(0, sec);
                queueState.skip = false;
                const finish = () => { if (queueState.cdTimer) { clearInterval(queueState.cdTimer); queueState.cdTimer = null; } resolve(); };
                if (left <= 0) { finish(); return; }
                queueSetStatus('等待 ' + left + 's 后生成第 ' + (queueState.idx + 1) + '/' + queueState.items.length + ' 条');
                queueState.cdTimer = setInterval(() => {
                    if (!queueState.running || queueState.skip) { finish(); return; }
                    if (queueState.paused) return;
                    left--;
                    queueSetStatus('等待 ' + left + 's 后生成第 ' + (queueState.idx + 1) + '/' + queueState.items.length + ' 条');
                    if (left <= 0) finish();
                }, 1000);
            });
        }

        async function queueRunOne(i, lane) {
            const it = queueState.items[i];
            it.state = 'running';
            if (typeof lane === 'number') it.lane = lane;
            queueRenderList();
            const mEl = document.getElementById('queueModel');
            const rEl = document.getElementById('queueRatio');
            const model = (mEl && mEl.value) || 'sensenova-u1.5-lite';
            const ratio = (rEl && rEl.value) || '1:1';
            const size = dualSizeTable(model)[ratio] || '1024x1024';
            const laneTxt = (typeof lane === 'number') ? (' · ' + (lane === 0 ? 'A 线' : 'B 线')) : '';
            const refs = (it.refs || []).map(r => r.url).filter(Boolean).slice(0, QUEUE_MAX_REFS);
            const refTxt = refs.length ? (' · 参照图 ' + refs.length + ' 张') : '';
            queueSetStatus('正在生成第 ' + (i + 1) + '/' + queueState.items.length + ' 条（' + model + ' · ' + size + refTxt + laneTxt + '）');
            try {
                const body = { prompt: it.prompt, negative_prompt: it.negative || '', model: model, size: size, save_local: true };
                // 车道绑定 KEY：A 线用 A 槽、B 线用 B 槽，两把 KEY 并行跑互不抢占。
                // 槽位没配 KEY 时后端会自动挑一把，单 KEY 用户照样跑得起来。
                if (typeof lane === 'number') body.key_slot = lane;
                // 挂了参照图就走图生图（多张一起传），没挂就是原来的纯文生图
                let endpoint = '/api/image/generate';
                if (refs.length) {
                    endpoint = '/api/image/img2img';
                    body.image_urls = refs;
                }
                const resp = await fetch(endpoint, {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify(body)
                });
                const d = await _qJson(resp);
                if (d.success && d.image_url) {
                    it.state = 'done'; it.url = d.image_url; it.file = d.local_file || '';
                } else {
                    it.state = 'fail'; it.err = d.error || '生成失败';
                }
            } catch (e) {
                it.state = 'fail'; it.err = '网络异常：' + e.message;
            }
            queueRenderList();
            queueUpdateBatchBar();
        }

        // 单项保存：生成时已落盘的直接确认；只有外链的补存进内部 pictures/
        async function queueSaveOne(i) {
            const it = queueState.items[i];
            if (!it || it.state !== 'done' || !it.url) { showToast('这一条还没有成片可保存', 'error'); return; }
            if (it.file) { showToast('已保存在内部目录 pictures/' + it.file, 'success'); return; }
            try {
                const blob = await (await fetch(it.url)).blob();
                const fd = new FormData();
                fd.append('file', blob, 'queue_' + Date.now() + '.png');
                const d = await _qJson(await fetch('/api/upload/image', { method: 'POST', body: fd }));
                if (d && d.success) {
                    it.file = d.filename; it.url = d.url;
                    queueRenderList();
                    queueUpdateBatchBar();
                    showToast('已保存到内部目录 pictures/' + d.filename, 'success');
                } else {
                    showToast('保存失败：' + ((d && d.error) || '未知'), 'error');
                }
            } catch (e) { showToast('保存异常：' + e.message, 'error'); }
        }

        // 批量汇总条：队列跑完后显示（跑动中隐藏），提供一键保存 / 一键下载
        function queueUpdateBatchBar() {
            const bar = document.getElementById('queueBatchBar');
            if (!bar) return;
            const done = queueState.items.filter(x => x.state === 'done');
            if (queueState.running || !done.length) { bar.style.display = 'none'; return; }
            const unsaved = done.filter(x => !x.file).length;
            const info = document.getElementById('queueBatchInfo');
            if (info) info.textContent = '批量结果：完成 ' + done.length + ' / ' + queueState.items.length + ' 条'
                + (unsaved ? '（' + unsaved + ' 条还没存进 pictures/）' : '（已全部存入 pictures/）');
            bar.style.display = 'flex';
        }

        // 一键保存：把所有还没落盘的外链成片补存进内部 pictures/
        async function queueSaveAll() {
            const targets = queueState.items.filter(x => x.state === 'done' && x.url && !x.file);
            if (!targets.length) { showToast('全部成片都已在 pictures/ 里，无需保存', 'info'); return; }
            showToast('开始保存 ' + targets.length + ' 张…', 'info');
            let ok = 0, bad = 0;
            for (const it of targets) {
                try {
                    const blob = await (await fetch(it.url)).blob();
                    const fd = new FormData();
                    fd.append('file', blob, 'queue_' + Date.now() + '_' + Math.floor(Math.random() * 1e4) + '.png');
                    const d = await _qJson(await fetch('/api/upload/image', { method: 'POST', body: fd }));
                    if (d && d.success) { it.file = d.filename; it.url = d.url; ok++; }
                    else bad++;
                } catch (e) { bad++; }
                queueUpdateBatchBar();
            }
            queueRenderList();
            queueUpdateBatchBar();
            showToast('一键保存完成：成功 ' + ok + ' 张' + (bad ? '，失败 ' + bad + ' 张（可单独重试）' : ''), bad ? 'error' : 'success');
        }

        function _queueTriggerDownload(url, name) {
            const a = document.createElement('a');
            a.href = url;
            a.download = name || '';
            document.body.appendChild(a);
            a.click();
            a.remove();
        }

        // 一键下载：把全部成片下载到本机（内部文件直接下，外链先取回再下）
        async function queueDownloadAll() {
            const targets = queueState.items.filter(x => x.state === 'done' && (x.file || x.url));
            if (!targets.length) { showToast('还没有可下载的成片', 'error'); return; }
            showToast('开始下载 ' + targets.length + ' 张（浏览器若询问多文件下载，请选允许）', 'info');
            let i = 0;
            for (const it of targets) {
                i++;
                try {
                    if (it.file) {
                        _queueTriggerDownload('/pictures/' + it.file, it.file);
                    } else {
                        const blob = await (await fetch(it.url)).blob();
                        const obj = URL.createObjectURL(blob);
                        _queueTriggerDownload(obj, 'queue_' + Date.now() + '_' + i + '.png');
                        setTimeout(() => URL.revokeObjectURL(obj), 30000);
                    }
                } catch (e) { /* 单张失败不挡后面 */ }
                await new Promise(r => setTimeout(r, 400));   // 间隔触发，太快会被浏览器吞掉
            }
            showToast('已触发下载 ' + targets.length + ' 张', 'success');
        }

        // 单项重来：重跑这一条（排队进行中时不允许，避免抢队列）
        async function queueRedoOne(i) {
            if (queueState.running) { showToast('排队进行中，请先 ⏹ 停止 或等跑完再重来', 'info'); return; }
            const it = queueState.items[i];
            if (!it) return;
            it.state = 'wait'; it.file = ''; it.url = ''; it.err = '';
            queueRenderList();
            await queueRunOne(i);
            if (it.state === 'done') showToast('第 ' + (i + 1) + ' 条已重新生成', 'success');
            else showToast('第 ' + (i + 1) + ' 条重来失败：' + (it.err || '未知'), 'error');
        }

        async function queueStart() {
            if (queueState.running) { showToast('排队已经在跑', 'info'); return; }
            if (!queueState.items.length && !queueParse()) return;
            const _mEl = document.getElementById('queueModel');
            const lanes = await queueResolveLanes((_mEl && _mEl.value) || '');
            queueState.running = true; queueState.paused = false; queueState.skip = false;
            queueState.idx = 0; queueState.lanes = lanes;
            showToast('开始排队：' + queueState.items.length + ' 条 · '
                + (lanes > 1 ? '双线并行（KEY A ＋ KEY B）' : '单线顺序生成'), 'success');
            // 多车道并发：车道数 = 已配置的 KEY 数（1 或 2）。每条车道从共享游标领任务，
            // 谁先跑完谁领下一条；只有一把 KEY 时 lanes=1，自动退化成原来的串行。
            let cursor = 0;
            const worker = async (lane) => {
                while (queueState.running) {
                    if (queueState.paused) {
                        queueSetStatus(lanes > 1 ? '已暂停（双线全部挂起，点「继续」恢复）' : '已暂停（点「继续」恢复）');
                        await new Promise(r => setTimeout(r, 400));
                        continue;
                    }
                    const i = cursor++;
                    if (i >= queueState.items.length) return;
                    queueState.idx = i + 1;
                    await queueRunOne(i, lanes > 1 ? lane : null);
                    await queueWait(queueIntervalSec());
                }
            };
            const runners = [];
            for (let l = 0; l < lanes; l++) runners.push(worker(l));
            await Promise.all(runners);
            queueState.running = false;
            queueState.lanes = 1;
            const done = queueState.items.filter(x => x.state === 'done').length;
            const fail = queueState.items.filter(x => x.state === 'fail').length;
            queueSetStatus('队列结束：完成 ' + done + ' 条' + (fail ? '，失败 ' + fail + ' 条' : '') + '（图片已存 pictures/）');
            showToast('队列跑完：完成 ' + done + ' 条' + (fail ? '，失败 ' + fail + ' 条' : ''), fail ? 'error' : 'success');
            queueRenderList();
            queueUpdateBatchBar();
        }

        function queuePause() {
            if (!queueState.running) { showToast('排队没在跑', 'info'); return; }
            queueState.paused = !queueState.paused;
            const b = document.getElementById('btnQueuePause');
            if (b) b.textContent = queueState.paused ? '▶ 继续' : '⏸ 暂停';
            showToast(queueState.paused ? '已暂停' : '已继续', 'info');
        }

        function queueSkip() {
            if (!queueState.running) { showToast('排队没在跑', 'info'); return; }
            queueState.skip = true;
            showToast('跳过等待，立即生成下一条', 'info');
        }

        function queueStop() {
            if (!queueState.running) return;
            queueState.running = false;
            queueState.paused = false;
            queueState.skip = true;
            if (queueState.cdTimer) { clearInterval(queueState.cdTimer); queueState.cdTimer = null; }
            queueSetStatus('已停止（已完成的部分仍保存在 pictures/）');
            showToast('已停止排队', 'info');
            queueRenderList();
            queueUpdateBatchBar();
        }

        // 后端：services/web_search.py（免费引擎 + 正文深读）+ services/search_agent.py（带引用的回答）        const WS_HISTORY_KEY = 'agnes.searchHistory';
        let wsCfg = null;            // /api/search/config 结果缓存
        let wsBusy = false;
        let wsLastAnswer = '';
        let wsLastSources = [];

        function wsEsc(s) {
            return String(s || '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
        }

        // 对话窗里展示联网来源（紧凑版，点标题开原网页，可一键带到搜索页）
        function hcSourcesHtml(sources, query) {
            const list = sources.map(s => '<div style="line-height:1.75;">[' + s.index + '] '
                + '<a href="' + wsEsc(s.url) + '" target="_blank" rel="noopener" style="color:var(--accent);">'
                + wsEsc(s.title || s.host) + '</a>'
                + (s.chars ? ' <span style="opacity:.7;">(' + s.chars + ' 字)</span>' : '')
                + '</div>').join('');
            const q = JSON.stringify(query || '').replace(/"/g, '&quot;');
            return '<div style="margin-top:8px;border-top:1px dashed var(--border);padding-top:6px;font-size:12px;color:var(--text2);">'
                + '<div style="margin-bottom:4px;">📚 联网来源 ' + sources.length + ' 条（点标题开原网页）</div>'
                + list
                + '<div style="margin-top:6px;"><button class="btn btn-sm" type="button" onclick="hcToSearchPage(' + q + ')">🔍 在搜索页看完整结果</button></div>'
                + '</div>';
        }

        function hcToSearchPage(q) {
            switchTab('search');
            const el = document.getElementById('wsQuery');
            if (el) el.value = q || '';
            setTimeout(() => { if (typeof wsRun === 'function') wsRun(); }, 400);
        }

        // 云端重启 / 反代 502 时后端会回 HTML 错误页，直接 resp.json() 会抛
        // "Unexpected token '<'" 这种没头没尾的报错 —— 统一翻译成人话。
        async function wsJson(resp) {
            const text = await resp.text();
            try {
                return JSON.parse(text);
            } catch (e) {
                throw new Error('服务无响应（HTTP ' + resp.status + '），可能正在重启或过载，稍后重试');
            }
        }

        const WS_SAMPLES = [
            '2026 年新能源汽车销量数据',
            '量子计算最新进展',
            '人工智能大模型 行业应用案例',
            '国内低空经济政策 最新',
            '今年诺贝尔物理学奖',
        ];

        function wsRenderSamples() {
            const box = document.getElementById('wsSamples');
            if (!box) return;
            box.innerHTML = WS_SAMPLES.map(q =>
                '<button class="btn btn-sm" type="button" onclick="wsUseSample('
                + JSON.stringify(q).replace(/"/g, '&quot;') + ')">' + wsEsc(q) + '</button>'
            ).join('');
        }

        function wsUseSample(q) {
            const el = document.getElementById('wsQuery');
            if (el) { el.value = q; el.focus(); }
        }

        async function initSearchModule() {
            wsRenderSamples();
            wsRenderHistory();
            if (!wsCfg) await wsLoadConfig(); else wsRenderStats(wsCfg.stats);
        }

        async function wsLoadConfig() {
            const st = document.getElementById('wsStatus');
            try {
                const d = await wsJson(await fetch('/api/search/config'));
                if (!d || !d.success) throw new Error((d && d.error) || '配置读取失败');
                wsCfg = d;
                wsRenderModels(d);
                wsRenderEngines(d);
                wsRenderStats(d.stats);
            } catch (e) {
                if (st) st.textContent = '状态：配置读取失败（' + e.message + '）';
            }
        }

        function wsRenderModels(d) {
            const sel = document.getElementById('wsModel');
            if (!sel) return;
            const models = d.models || {};
            sel.innerHTML = Object.entries(models).map(([v, label]) =>
                '<option value="' + wsEsc(v) + '">' + wsEsc(label) + '</option>').join('');
            sel.value = d.default_model && models[d.default_model] ? d.default_model : Object.keys(models)[0];
        }

        function wsRenderEngines(d) {
            const sel = document.getElementById('wsEngines');
            if (!sel) return;
            const list = d.engines || [];
            const auto = (d.default_engines || []).map(k => {
                const hit = list.find(e => e.key === k);
                return hit ? hit.label.replace(/（.*?）/g, '') : k;
            }).join(' + ');
            let html = '<option value="auto" selected>自动（' + wsEsc(auto || '内置默认') + '）</option>';
            html += '<option value="all">全部引擎（更全，稍慢）</option>';
            list.forEach(e => {
                html += '<option value="' + wsEsc(e.key) + '">仅 ' + wsEsc(e.label)
                    + (e.cooling ? '（冷却中）' : '') + '</option>';
            });
            sel.innerHTML = html;
        }

        function wsRenderStats(s) {
            const box = document.getElementById('wsStatsBar');
            if (!box || !s) return;
            const rows = (s.engines || []).map(e => {
                const rate = (e.ok_rate === null || e.ok_rate === undefined) ? '未使用' : (e.ok_rate + '%');
                const color = (e.ok_rate !== null && e.ok_rate !== undefined && e.ok_rate < 60) ? 'var(--warning)' : 'var(--text2)';
                return '<span style="color:' + color + ';">' + wsEsc(e.label) + ' ' + rate
                    + '（' + (e.calls || 0) + ' 次）</span>';
            }).join(' · ');
            box.innerHTML = '<b>♾️ 无额度账本</b>（进程启动于 ' + wsEsc(s.since || '-') + '）<br>'
                + '检索 ' + (s.searches || 0) + ' 次 · 深读 ' + (s.deep_searches || 0) + ' 次 · '
                + '抓取正文 ' + (s.pages_fetched || 0) + ' 篇（失败 ' + (s.page_errors || 0) + '）· '
                + '缓存命中 ' + (s.cache_hits || 0) + ' 次 · 缓存条目 ' + (s.cache_size || 0) + '<br>'
                + '<span style="color:var(--success);">估算已省下付费检索/抓取调用 <b>' + (s.saved_calls || 0) + '</b> 次</span>'
                + '<br>引擎健康：' + (rows || '暂无');
        }

        async function wsRefreshStats() {
            try {
                const d = await wsJson(await fetch('/api/search/stats'));
                if (d && d.success) { if (wsCfg) wsCfg.stats = d.stats; wsRenderStats(d.stats); }
            } catch (e) { showToast('统计刷新失败：' + e.message, 'error'); }
        }

        function wsSetStatus(t, color) {
            const el = document.getElementById('wsStatus');
            if (el) {
                el.textContent = '状态：' + t;
                el.style.color = color || 'var(--text2)';
            }
        }

        function wsCollectEngines() {
            const sel = document.getElementById('wsEngines');
            const v = (sel && sel.value) || 'auto';
            if (v === 'auto') return null;
            if (v === 'all') return (wsCfg && wsCfg.engines || []).map(e => e.key);
            return [v];
        }

        async function wsRun() {
            if (wsBusy) { showToast('正在搜索中，请稍候…', 'info'); return; }
            const qEl = document.getElementById('wsQuery');
            const query = ((qEl && qEl.value) || '').trim();
            if (!query) { showToast('先输入要搜索的内容', 'error'); if (qEl) qEl.focus(); return; }

            const deep = (document.getElementById('wsDeep') || {}).value !== '0';
            const searchOnly = !!(document.getElementById('wsSearchOnly') || {}).checked;
            const limit = parseInt((document.getElementById('wsLimit') || {}).value || '8', 10);
            const topK = parseInt((document.getElementById('wsTopK') || {}).value || '4', 10);
            const model = (document.getElementById('wsModel') || {}).value || '';

            wsBusy = true;
            const btn = document.getElementById('wsBtn');
            if (btn) { btn.disabled = true; btn.textContent = '⏳ 搜索中…'; }
            const aCard = document.getElementById('wsAnswerCard');
            const sCard = document.getElementById('wsSourcesCard');
            if (aCard) aCard.style.display = 'none';
            if (sCard) sCard.style.display = 'none';
            wsSetStatus('正在检索' + (deep ? '并抓取网页正文' : '（仅摘要）') + '…', 'var(--warning)');

            wsPushHistory(query);

            try {
                const resp = await fetch('/api/search/run', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        query: query, deep: deep, search_only: searchOnly,
                        limit: limit, top_k: topK, model: model,
                        engines: wsCollectEngines()
                    })
                });
                const d = await wsJson(resp);
                if (!d || !d.success) {
                    wsSetStatus('搜索失败：' + ((d && d.error) || '未知错误'), 'var(--error)');
                    showToast('搜索失败：' + ((d && d.error) || '未知错误'), 'error');
                    if (d && d.sources && d.sources.length) wsRenderSources(d.sources, d.meta);
                    return;
                }
                const meta = d.meta || {};
                if (!searchOnly) {
                    wsLastAnswer = d.answer || '';
                    wsRenderAnswer(d.answer || '');
                    if (aCard) aCard.style.display = '';
                    const mEl = document.getElementById('wsAnswerMeta');
                    if (mEl) mEl.textContent = (meta.model || '') + ' · 用时 ' + (meta.elapsed || '?') + 's'
                        + ' · 引擎 ' + ((meta.engines || []).join('/') || '-')
                        + (meta.cache ? ' · 命中缓存' : '');
                }
                wsRenderSources(d.sources || [], meta);
                if (sCard && (d.sources || []).length) sCard.style.display = '';
                const note = (meta.retried ? '（原始查询带时效词，已自动去掉后重试）' : '')
                    + (meta.low_relevance ? '（⚠️ 结果与问题相关度很低，答案可能答不上来）' : '');
                wsSetStatus('完成：检索到 ' + (meta.results || 0) + ' 条结果'
                    + (deep ? '，成功抓到 ' + (meta.deep_ok || 0) + ' 篇正文' : '')
                    + '，总用时 ' + (meta.elapsed || '?') + 's' + note,
                    meta.low_relevance ? 'var(--warning)' : 'var(--success)');
                wsRefreshStats();
            } catch (e) {
                wsSetStatus('网络异常：' + e.message, 'var(--error)');
                showToast('网络异常：' + e.message, 'error');
            } finally {
                wsBusy = false;
                if (btn) { btn.disabled = false; btn.textContent = '🔍 开始搜索'; }
            }
        }

        // 轻量 Markdown：标题 / 粗体 / 行内代码 / 列表 / [编号] 引用
        function wsFmtAnswer(text) {
            let s = wsEsc(text || '');
            s = s.replace(/^#{1,6}\s*(.+)$/gm, '\u0001H\u0001$1\u0001/H\u0001');
            s = s.replace(/\*\*([^*\n]+)\*\*/g, '<b>$1</b>');
            s = s.replace(/`([^`\n]+)`/g, '<code style="background:var(--surface2);padding:1px 5px;border-radius:4px;">$1</code>');
            s = s.replace(/^\s*[-*·]\s+(.+)$/gm, '<div style="padding-left:14px;">· $1</div>');
            s = s.replace(/^\s*(\d{1,2})[.、]\s+(.+)$/gm, '<div style="padding-left:14px;">$1. $2</div>');
            // [数字] → 可点击的引用标记（必须放在转义之后，方括号不受转义影响）
            s = s.replace(/\[(\d{1,2})\]/g,
                '<sup onclick="wsJumpToSource($1)" title="跳到来源 $1" '
                + 'style="cursor:pointer;color:var(--accent);font-weight:700;padding:0 1px;">[$1]</sup>');
            s = s.replace(/\u0001H\u0001([^\u0001]+)\u0001\/H\u0001/g,
                '<div style="font-size:14px;font-weight:700;margin:12px 0 6px;">$1</div>');
            s = s.split(/\n{2,}/).map(p => {
                const t = p.trim();
                if (!t) return '';
                if (/^<(div|sup|b|code)/.test(t)) return t;
                return '<p style="margin:0 0 10px;">' + t.replace(/\n/g, '<br>') + '</p>';
            }).join('');
            return s;
        }

        function wsRenderAnswer(text) {
            const box = document.getElementById('wsAnswer');
            if (!box) return;
            box.innerHTML = text ? wsFmtAnswer(text) : '<span style="color:var(--text2);">（无回答）</span>';
        }

        function wsRenderSources(sources, meta) {
            const box = document.getElementById('wsSources');
            if (!box) return;
            wsLastSources = sources || [];
            const mEl = document.getElementById('wsSourcesMeta');
            if (mEl) mEl.textContent = (meta && meta.deep)
                ? ('深读成功 ' + (meta.deep_ok || 0) + ' / ' + (sources || []).length + ' 篇')
                : '仅摘要模式';
            if (!wsLastSources.length) {
                box.innerHTML = '<div style="font-size:13px;color:var(--text2);">没有检索到结果。可以换个说法，或去掉过于具体的限定词再试。</div>';
                return;
            }
            box.innerHTML = wsLastSources.map((it, i) => {
                const idx = it.index || (i + 1);
                const chars = it.chars ? (' · 正文 ' + it.chars + ' 字')
                    : (it.content_error ? (' · ' + wsEsc(it.content_error)) : '');
                const rel = (it.relevance === 0)
                    ? '<span style="color:var(--warning);margin-left:6px;">相关度低</span>' : '';
                return `<div id="wsSrc${idx}" style="display:flex;gap:10px;border:1px solid var(--border);border-radius:var(--radius-sm);padding:10px;background:var(--bg);cursor:pointer;" onclick="wsReadFull(${idx})">
                    <div style="flex:0 0 auto;width:26px;height:26px;border-radius:50%;background:var(--accent);color:var(--on-accent);display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:700;">${idx}</div>
                    <div style="flex:1;min-width:0;">
                        <div style="font-size:13px;font-weight:600;line-height:1.5;">${wsEsc(it.title)}</div>
                        <div style="font-size:12px;color:var(--text2);margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${wsEsc(it.host)}${chars}${rel}</div>
                        <div style="font-size:12px;color:var(--text2);margin-top:4px;line-height:1.7;">${wsEsc(it.snippet || '')}</div>
                    </div>
                    <div style="flex:0 0 auto;display:flex;flex-direction:column;gap:6px;">
                        <a class="btn btn-sm" href="${wsEsc(it.url)}" target="_blank" rel="noopener" onclick="event.stopPropagation()">↗</a>
                        <button class="btn btn-sm" type="button" onclick="event.stopPropagation();wsReadFull(${idx})">📖</button>
                    </div>
                </div>`;
            }).join('');
        }

        function wsJumpToSource(n) {
            const el = document.getElementById('wsSrc' + n);
            if (!el) return;
            el.scrollIntoView({ behavior: 'smooth', block: 'center' });
            const old = el.style.borderColor;
            el.style.borderColor = 'var(--accent)';
            el.style.boxShadow = '0 0 0 2px var(--glow)';
            setTimeout(() => { el.style.borderColor = old || 'var(--border)'; el.style.boxShadow = ''; }, 1600);
        }

        async function wsReadFull(idx) {
            const it = wsLastSources.find(x => (x.index || 0) === idx) || wsLastSources[idx - 1];
            if (!it) return;
            wsOpenReader(it.title, it.url, '正在抓取正文…');
            try {
                const d = await wsJson(await fetch('/api/search/fetch', {
                    method: 'POST', headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ url: it.url, max_chars: 6000 })
                }));
                const body = document.getElementById('wsReaderBody');
                if (!body) return;
                if (d && d.success) {
                    body.textContent = (d.title ? d.title + '\n\n' : '') + (d.text || '')
                        + (d.truncated ? '\n\n…（内容较长，已截断，可点右上角「原网页」看全文）' : '');
                    const t = document.getElementById('wsReaderTitle');
                    if (t && d.title) t.textContent = d.title;
                } else {
                    body.textContent = '抓取失败：' + ((d && d.error) || '未知错误')
                        + '\n\n（点右上角「原网页」可直接在浏览器里打开）';
                }
            } catch (e) {
                const body = document.getElementById('wsReaderBody');
                if (body) body.textContent = '抓取异常：' + e.message;
            }
        }

        function wsOpenReader(title, url, placeholder) {
            const m = document.getElementById('wsReaderModal');
            const t = document.getElementById('wsReaderTitle');
            const b = document.getElementById('wsReaderBody');
            const a = document.getElementById('wsReaderOpen');
            if (t) t.textContent = title || '正文';
            if (b) b.textContent = placeholder || '';
            if (a) a.href = url || '#';
            if (m) m.classList.add('show');
        }

        function wsCloseReader() {
            const m = document.getElementById('wsReaderModal');
            if (m) m.classList.remove('show');
        }

        async function wsCopyText(text, okMsg) {
            try {
                await navigator.clipboard.writeText(text);
                showToast(okMsg || '已复制', 'success');
                return true;
            } catch (e) {
                // 剪贴板 API 不可用（非 https / 权限被拒）时降级到 textarea
                try {
                    const ta = document.createElement('textarea');
                    ta.value = text;
                    ta.style.position = 'fixed';
                    ta.style.left = '-9999px';
                    document.body.appendChild(ta);
                    ta.select();
                    document.execCommand('copy');
                    ta.remove();
                    showToast(okMsg || '已复制', 'success');
                    return true;
                } catch (e2) {
                    showToast('复制失败，请手动选中复制', 'error');
                    return false;
                }
            }
        }

        function wsCopyAnswer() {
            if (!wsLastAnswer) { showToast('还没有可复制的回答', 'error'); return; }
            const srcs = wsLastSources.length
                ? '\n\n参考来源：\n' + wsLastSources.map(it => '[' + (it.index || '') + '] ' + it.title + ' ' + it.url).join('\n')
                : '';
            wsCopyText(wsLastAnswer + srcs, '回答已复制（含来源列表）');
        }

        async function wsHealth() {
            const box = document.getElementById('wsHealthBox');
            if (box) { box.style.display = ''; box.textContent = '正在自检各引擎（会真实发一次查询）…'; }
            try {
                const d = await wsJson(await fetch('/api/search/health'));
                const rows = (d && d.engines) || [];
                if (box) {
                    box.innerHTML = '<b>引擎自检：' + ((d && d.ok) || 0) + ' / ' + ((d && d.total) || 0) + ' 可用</b><br>'
                        + rows.map(r => {
                            const color = r.ok ? 'var(--success)' : 'var(--error)';
                            const extra = r.ok ? ('HTTP ' + r.status + ' · ' + r.ms + 'ms') : (r.error || 'HTTP ' + (r.status || '-'));
                            return '<span style="color:' + color + ';">' + (r.ok ? '✓' : '✗') + ' ' + wsEsc(r.label) + '</span>：' + extra;
                        }).join('<br>');
                }
                await wsRefreshStats();
            } catch (e) {
                if (box) box.textContent = '自检失败：' + e.message;
            }
        }

        async function wsClearCache() {
            try {
                const d = await wsJson(await fetch('/api/search/cache/clear', { method: 'POST' }));
                showToast('已清掉 ' + ((d && d.cleared) || 0) + ' 条缓存', 'success');
                wsRefreshStats();
            } catch (e) { showToast('清缓存失败：' + e.message, 'error'); }
        }

        function wsLoadHistory() {
            try { return JSON.parse(localStorage.getItem(WS_HISTORY_KEY)) || []; } catch (e) { return []; }
        }

        function wsPushHistory(q) {
            if (!q) return;
            let list = wsLoadHistory().filter(x => x && x.q !== q);
            list.unshift({ q: q, ts: Date.now() });
            list = list.slice(0, 20);
            try { localStorage.setItem(WS_HISTORY_KEY, JSON.stringify(list)); } catch (e) { /* ignore */ }
            wsRenderHistory();
        }

        function wsRenderHistory() {
            const card = document.getElementById('wsHistoryCard');
            const box = document.getElementById('wsHistory');
            if (!box) return;
            const list = wsLoadHistory();
            if (!list.length) { if (card) card.style.display = 'none'; return; }
            if (card) card.style.display = '';
            box.innerHTML = list.map((h, i) => {
                const t = new Date(h.ts || Date.now());
                const time = (t.getMonth() + 1) + '/' + t.getDate() + ' '
                    + String(t.getHours()).padStart(2, '0') + ':' + String(t.getMinutes()).padStart(2, '0');
                return `<div style="display:flex;gap:8px;align-items:center;font-size:13px;">
                    <span style="color:var(--text2);font-size:12px;flex:0 0 auto;">${time}</span>
                    <span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;cursor:pointer;" onclick="wsRerun(${i})" title="点一下重新搜索">${wsEsc(h.q)}</span>
                </div>`;
            }).join('');
        }

        function wsRerun(i) {
            const list = wsLoadHistory();
            const hit = list[i];
            if (!hit) return;
            const el = document.getElementById('wsQuery');
            if (el) el.value = hit.q;
            wsRun();
        }

        function wsClearHistory() {
            try { localStorage.removeItem(WS_HISTORY_KEY); } catch (e) { /* ignore */ }
            wsRenderHistory();
            showToast('搜索历史已清空', 'success');
        }

        const TV_DEFAULT_TEMPLATE = '生成人物三视图，16:9横版构图，角色严格按照参考图片。左侧1/3区域为超大高清面部特写，右侧2/3区域整齐排布角色三张全身三视图，包含角色的正面(Front)、侧面(Profile)及背面(Back)三个维度的全身站姿视图。背景为纯白色背景。视觉对齐:所有角度的比例必须严格一致，确保角色身高、五官位置、服装褶皱在不同视角下完美契合。超高清，超写实8K，cg建模渲染。';
        let tvImages = [];

        function initTriviewModels() {
            const sel = document.getElementById('tvModel');
            if (sel) {
                sel.innerHTML = Object.entries(DUAL_MODEL_OPTIONS)
                    .map(([v, label]) => '<option value="' + v + '">' + (v === 'sensenova-u1.5-lite' ? '★ ' : '') + label + '</option>').join('');
                sel.value = 'sensenova-u1.5-lite';
            }
            const dz = document.getElementById('tvDrop');
            if (dz) {
                ['dragenter', 'dragover'].forEach(ev => dz.addEventListener(ev, e => {
                    e.preventDefault(); dz.style.borderColor = 'var(--accent)';
                }));
                ['dragleave', 'drop'].forEach(ev => dz.addEventListener(ev, e => {
                    e.preventDefault(); dz.style.borderColor = 'var(--border)';
                }));
                dz.addEventListener('drop', e => {
                    const fs = (e.dataTransfer && e.dataTransfer.files) || [];
                    tvUploadFiles(fs);
                });
            }
            tvRenderThumbs();
        }

        async function tvUploadFiles(files) {
            const list = Array.from(files || []).filter(f => f && /image\//.test(f.type || ''));
            if (!list.length) return;
            for (const f of list) {
                const fd = new FormData();
                fd.append('file', f);
                try {
                    const r = await fetch('/api/upload/image', { method: 'POST', body: fd });
                    const d = await r.json();
                    if (d && d.success) tvImages.push({ url: d.url, filename: d.filename });
                    else showToast('上传失败：' + ((d && d.error) || '未知'), 'error');
                } catch (e) { showToast('上传失败：' + e.message, 'error'); }
            }
            tvRenderThumbs();
            showToast('参考图共 ' + tvImages.length + ' 张', 'success');
        }

        function tvRenderThumbs() {
            const box = document.getElementById('tvThumbs');
            if (!box) return;
            box.innerHTML = tvImages.map((im, i) => (
                '<div style="position:relative;">'
                + '<img src="' + im.url + '" style="width:78px;height:78px;object-fit:cover;border-radius:6px;border:1px solid var(--border);">'
                + '<button class="btn btn-sm" style="position:absolute;top:-6px;right:-6px;padding:0 5px;" onclick="tvRemoveImage(' + i + ')" title="移除">✕</button>'
                + (i === 0 ? '<div style="font-size:11px;color:var(--accent);text-align:center;">主参考</div>' : '')
                + '</div>'
            )).join('');
        }

        function tvRemoveImage(i) {
            tvImages.splice(i, 1);
            tvRenderThumbs();
        }

        let tvLast = { url: '', file: '' };   // 最近一次成片（供 保存/下载/重来 用）

        function tvSetBtns(on) {
            ['btnTvSave', 'btnTvDl'].forEach(id => {
                const b = document.getElementById(id);
                if (b) b.disabled = !on;
            });
        }

        function tvCompose() {
            // 三视图模板保密内置（不渲染到页面），只把用户的附加描述拼在前面
            const extraEl = document.getElementById('tvExtra');
            const extra = ((extraEl && extraEl.value) || '').trim();
            const head = extra ? extra.replace(/[，,;；]\s*$/, '') + '。' : '';
            return head + TV_DEFAULT_TEMPLATE;
        }

        async function tvGenerate() {
            const prompt = tvCompose();
            if (!prompt) { showToast('请先填写角色附加描述', 'error'); return; }
            const mEl = document.getElementById('tvModel');
            const rEl = document.getElementById('tvRatio');
            const model = (mEl && mEl.value) || 'sensenova-u1.5-lite';
            const ratio = (rEl && rEl.value) || '16:9';
            const size = dualSizeTable(model)[ratio] || '1024x576';
            const btn = document.getElementById('btnTvGen');
            const out = document.getElementById('tvResult');
            if (btn) { btn.disabled = true; btn.innerHTML = '<span class="loading-spinner"></span> 生成中…'; }
            if (out) out.textContent = '⏳ 生成中（' + model + ' · ' + size + (tvImages.length ? ' · 带 ' + tvImages.length + ' 张参考图' : '') + '）…';
            try {
                const useRef = tvImages.length > 0;
                const url = useRef ? '/api/image/img2img' : '/api/image/generate';
                const body = { prompt: prompt, model: model, size: size, save_local: true };
                if (useRef) body.image_urls = tvImages.map(x => x.url);
                const r = await fetch(url, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
                const d = await _qJson(r);
                if (d.success && d.image_url) {
                    tvLast = { url: d.image_url, file: d.local_file || '' };
                    const localUrl = d.local_file ? '/pictures/' + d.local_file : d.image_url;
                    tvLast.url = localUrl;
                    const img = document.getElementById('tvResultImg');
                    const wrap = document.getElementById('tvResultImgWrap');
                    if (img) img.src = localUrl;
                    if (wrap) wrap.style.display = 'block';
                    if (out) out.innerHTML = '✅ 完成 · 已保存 <b>pictures/' + _qEsc(d.local_file || '') + '</b>'
                        + (useRef ? '（已按参考图生成）' : '（未上传参考图，走文生图）');
                    tvSetBtns(true);
                    showToast('三视图已生成并保存', 'success');
                } else if (out) {
                    out.textContent = '❌ ' + (d.error || '生成失败');
                }
            } catch (e) {
                if (out) out.textContent = '❌ 网络异常：' + e.message;
            }
            if (btn) { btn.disabled = false; btn.textContent = '🚀 直接生成（参考图生效）'; }
        }

        function tvSendToGen() {
            const p = tvCompose();
            if (!p) { showToast('请先填写角色附加描述', 'error'); return; }
            const mEl = document.getElementById('tvModel');
            const model = (mEl && mEl.value) || 'sensenova-u1.5-lite';
            switchTab('image');
            const ta = document.getElementById('imagePrompt');
            if (ta) ta.value = p;
            const l = document.getElementById('dualModelLeft');
            if (l) { l.value = model; try { onDualModelChange(); } catch (e) { /* 忽略 */ } }
            showToast('已送入生图器，点「一键双模生成」即可出图', 'success');
        }

        // 保存（内部）：确保成片落进本机 pictures/ 目录（生成时已自动存，这里是补存/确认）
        async function tvSaveInternal() {
            if (!tvLast.url) { showToast('还没有成片可保存', 'error'); return; }
            if (tvLast.file) {
                showToast('已保存在内部目录 pictures/' + tvLast.file, 'success');
                return;
            }
            try {
                const blob = await (await fetch(tvLast.url)).blob();
                const fd = new FormData();
                fd.append('file', blob, 'triview_' + Date.now() + '.png');
                const d = await (await fetch('/api/upload/image', { method: 'POST', body: fd })).json();
                if (d && d.success) {
                    tvLast.file = d.filename; tvLast.url = d.url;
                    const out = document.getElementById('tvResult');
                    if (out) out.innerHTML += '<br>💾 已补存到内部目录 <b>pictures/' + _qEsc(d.filename) + '</b>';
                    showToast('已保存到内部目录', 'success');
                } else {
                    showToast('保存失败：' + ((d && d.error) || '未知'), 'error');
                }
            } catch (e) { showToast('保存异常：' + e.message, 'error'); }
        }

        function tvDownload() {
            if (!tvLast.url) { showToast('还没有成片可下载', 'error'); return; }
            const a = document.createElement('a');
            a.href = tvLast.url;
            a.download = tvLast.file || ('triview_' + Date.now() + '.png');
            a.target = '_blank';
            document.body.appendChild(a); a.click(); a.remove();
        }

        // 重来：清掉结果，保留参考图和附加描述，方便直接再出一张
        function tvRedo() {
            const wrap = document.getElementById('tvResultImgWrap');
            const img = document.getElementById('tvResultImg');
            if (img) img.src = '';
            if (wrap) wrap.style.display = 'none';
            const out = document.getElementById('tvResult');
            if (out) out.textContent = '已重来：参考图与附加描述都留着，直接点「🚀 直接生成」再出一张。';
            tvLast = { url: '', file: '' };
            tvSetBtns(false);
            showToast('已清空结果，可以再生成一次', 'info');
        }



